  ui_story_5029_50290002_52_dialog_content = "진짜로 현상금 의뢰잖아. 게다가 보수도 상당한 것 같은데?!",
  ui_story_5029_50290002_53_dialog_content = "...내, 내가 정말 이걸 뜯었다고? 왜 전혀 기억이 안 나는 거지?",
  ui_story_5029_50290002_54_dialog_content = "아까 넌 조금도 망설이지 않고 그걸 뜯었는걸.",
  ui_story_5029_50290002_55_dialog_content = "난 그냥 인기 없는 탐정 소설을 읽었을 뿐이지,\n진짜 탐정이 되고 싶은 건 아니었어.",
  ui_story_5029_50290002_56_dialog_content = "내가 대체 무슨 생각을 하고 있었던 건지 모르겠네...",
  ui_story_5029_50290002_57_dialog_content = "분명히 「고액의 현상금」이라는 단어에 현혹된 거겠지.",
  ui_story_5029_50290002_58_dialog_content = "난 아주 잘 이해할 수 있어!",
  ui_story_5029_50290002_59_dialog_content = "하버 시티는 치안 환경도 좋고 백성들도 부유한데,\n그런 흉악한 사건이 있었단 말이야?",
  ui_story_5029_50290002_60_dialog_content = "게다가 왜 이 사람은 영주한테 가서 문제를 해결하지 않는 거지?",
  ui_story_5029_50290002_61_dialog_content = "어쩌면 영주가 이 문제를 해결할 수 없는 건 아닐까...",
  ui_story_5029_50290002_62_dialog_content = "에이, 이렇게 좋은 기회를 놓칠 순 없잖아?",
  ui_story_5029_50290002_63_dialog_content = "어차피 우린 시간이 있으니까,\n이참에 탐정이 돼서 현상금을 벌어도 좋을 것 같아.",
  ui_story_5029_50290002_64_dialog_content = "이 일을 조사하는 건 나도 찬성이야.\n대신 조사는 어디까지나 백야성 호위대로서 진행하는 거야.",
  ui_story_5029_50290002_65_dialog_content = "이건 백야성의 속령에서 일어난 사건이니까,\n난 백야성의 법률로 이 범인을 심판했으면 해.",
  ui_story_5029_50290002_66_dialog_content = "근데 그러면... 현상금은 못 받는 거 아냐?",
  ui_story_5029_50290002_67_dialog_content = "......",
  ui_story_5029_50290002_68_dialog_content = "키아로, 플랜B, 즉시 실행!",
  ui_story_5029_50290002_69_dialog_content = "루!",
  ui_story_5029_50290002_70_dialog_content = "으앗, 현상 의뢰서를... 도둑맞았어!",
  ui_story_5029_50290002_71_dialog_content = "아하하, 잘했어, 키아로.",
  ui_story_5029_50290002_72_dialog_content = "피아?! 이번엔 또 어디서 갑자기 나타난 거야?",
  ui_story_5029_50290002_73_option_content = "강도인 줄 알았잖아...",
  ui_story_5029_50290002_74_dialog_content = "PlayerName, 그런 말 하면 피아 화낼 거야!",
  ui_story_5029_50290002_74X1_dialog_content = "똑바로 봐. 피아가 어딜 봐서 강도 같은데?",
  ui_story_5029_50290002_75_dialog_content = "난 그저 내 환상동물 PlayerName의 관심을 받은 물건이\n뭔지 궁금했을 뿐인걸.",
  ui_story_5029_50290002_76_option_content = "역시 환상동물 마스터답네...",
  ui_story_5029_50290002_77_dialog_content = "자기 기척을 아주 잘 숨길 수 있잖아.",
  ui_story_5029_50290002_78_dialog_content = "헤헤, 당연하지.",
  ui_story_5029_50290002_79_dialog_content = "안 그러면 내가 널 어떻게 잡았겠어~",
  ui_story_5029_50290002_80_dialog_content = "자, 그럼 네가 뭘 보고 있었는지 어디 한번 볼까?",
  ui_story_5029_50290002_81_dialog_content = "그래그래, 다음엔 이렇게 놀라게 만들지만 말아줘.",
  ui_story_5029_50290002_82_dialog_content = "우와, 이거 현상금 임무구나!",
  ui_story_5029_50290002_83_dialog_content = "키아로, 역시 우린 운이 좋은 것 같아!\n이제 앞으로의 여행 경비도 벌 수 있을 거야!",
  ui_story_5029_50290002_84_dialog_content = "루우우!",
  ui_story_5029_50290002_85_dialog_content = "허접 사부, 못된 사부, 이렇게 멀리까지 보내놓고\n경비는 쥐꼬리만큼밖에 안 줬다구.",
  ui_story_5029_50290002_86_dialog_content = "그래서 맛있는 것도 못 먹고, 재밌는 게 있어도 못 놀았잖아.\n흥, 두고 보자...",
  ui_story_5029_50290002_87_dialog_content = "피아가 임무도 완수하고 큰돈도 벌 거니까!",
  ui_story_5029_50290002_88_dialog_content = "루우우!",
  ui_story_5029_50290002_89_dialog_content = "피아, 설마 너도 이 임무를 받을 생각은 아니지?",
  ui_story_5029_50290002_90_dialog_content = "잘 봐, 이건 소꿉놀이가 아냐.",
  ui_story_5029_50290002_91_dialog_content = "임무를 받으면 진짜 범죄자와 싸워야만 해.",
  ui_story_5029_50290002_92_dialog_content = "나, 난...",
  ui_story_5029_50290002_93_dialog_content = "흥, 바보 취급하지 마.",
  ui_story_5029_50290002_94_dialog_content = "피아는 제일 사납고 제일 흉폭한 동물도 온순하게 만들었어!\n범죄자 따위가 무서울 리가 없잖아?",
  ui_story_5029_50290002_95_dialog_content = "피아, 범죄자랑 환상동물은 별개야.",
  ui_story_5029_50290002_96_dialog_content = "PlayerName 너까지 내 편 안 들어주는 거야?",
  ui_story_5029_50290002_97_dialog_content = "헤에~ 알았어. 사실 너희도 이 임무를 노리고 있었던 거지?",
  ui_story_5029_50290002_98_dialog_content = "그럼 별일 아니잖아. 우리 <color=#793f76>공평하게 경쟁하자</color>.",
  ui_story_5029_50290002_99_dialog_content = "범인을 잡은 사람이 현상금을 가진다는 거지? 좋은 생각이야!",
  ui_story_5029_50290002_100_dialog_content = "그렇다면 모두 각오하는 게 좋을 거야.",
  ui_story_5029_50290002_101_dialog_content = "난 백야성 호위대에서 오랫동안 활동해서 나름대로 경험이 있으니까.",
  ui_story_5029_50290002_102_dialog_content = "모두...? 그럼 난...?",
  ui_story_5029_50290002_103_dialog_content = "미안합니다. 다들 많이 기다리셨죠?",
  ui_story_5029_50290002_104_dialog_content = "저는 그 현상금 의뢰서에 적힌 담당자 젠이라고 합니다.",
  ui_story_5029_50290002_105_dialog_content = "네 분께서 임무를 받기로 결정하셨다면 절 따라오시죠.",
  ui_story_5029_50290003_1_dialog_content = "PlayerName.",
  ui_story_5029_50290003_2_dialog_content = "......",
  ui_story_5029_50290003_3_dialog_content = "PlayerName, 나 겁주지 마...",
  ui_story_5029_50290003_4_dialog_content = "그동안 우린 수많은 위기와 재난을 겪었지만, 넌 전부 이겨냈잖아.",
  ui_story_5029_50290003_5_dialog_content = "겨우 길에서 넘어진 정도로 머리가 어떻게 되는 건 아니지?",
  ui_story_5029_50290003_6_dialog_content = "아, 맞다... 콜로서스엔 생명유지 장치가 있잖아...",
  ui_story_5029_50290003_7_dialog_content = "PlayerName, 조금만 기다려. 내가 업고 데려다줄게.",
  ui_story_5029_50290003_8_dialog_content = "분명히 괜찮을 거야!",
  ui_story_5029_50290003_9_dialog_content = "난...",
  ui_story_5029_50290003_10_dialog_content = "드디어 깨어났구나! 정말 다행이야...",
  ui_story_5029_50290003_11_option_content = "너무 무서워...",
  ui_story_5029_50290003_12_dialog_content = "괜찮아, PlayerName. 내가 계속 여기 있잖아.",
  ui_story_5029_50290003_13_dialog_content = "이 도시는 안전해. 방금 넘어진 건 그냥 우연이야.",
  ui_story_5029_50290003_14_dialog_content = "무서워하지 마. 혹시나 무슨 일이 생겨도 내가 지켜줄 테니까.",
  ui_story_5029_50290003_15_dialog_content = "응, 무슨 얘기야?",
  ui_story_5029_50290003_16_option_content = "네가 곁에 있어 줘서 다행이야...",
  ui_story_5029_50290003_17_dialog_content = "어?",
  ui_story_5029_50290003_18_dialog_content = "갑자기 무슨 소리야.",
  ui_story_5029_50290003_19_dialog_content = "사람 부끄럽게.",
  ui_story_5029_50290003_20_dialog_content = "아, 그, 그게...",
  ui_story_5029_50290003_21_option_content = "난 괜찮아.",
  ui_story_5029_50290003_22_dialog_content = "정말?",
  ui_story_5029_50290003_23_dialog_content = "머리는 안 아파? 아니면 몸에 어디 불편한 데 있어?",
  ui_story_5029_50290003_24_dialog_content = "없어. 괜찮은 것 같아. 그냥...",
  ui_story_5029_50290003_25_option_content = "네가 걱정할 거 없잖아.",
  ui_story_5029_50290003_26_dialog_content = "너...",
  ui_story_5029_50290003_27_dialog_content = "한 번 넘어졌을 뿐인데 갑자기 왜 성격이 이렇게 나빠졌어?",
  ui_story_5029_50290003_28_dialog_content = "혹시 다시 넘어지면 원래 PlayerName의 성격으로 돌아갈 수 있는 걸까?",
  ui_story_5029_50290003_29_dialog_content = "앗, 바이스? 뭘 하려는 거야?",
  ui_story_5029_50290003_30_dialog_content = "내 얘기 좀 들어 봐...",
  ui_story_5029_50290003_31_dialog_content = "나 왠지 꿈을 꾼 것 같아.",
  ui_story_5029_50290003_32_dialog_content = "혹시 내가 방금 이상한 말을 했어도 절대 신경 쓰지 마...",
  ui_story_5029_50290003_33_dialog_content = "그래, 그래. 네가 괜찮은 게 제일 중요하니까.",
  ui_story_5029_50290003_34_dialog_content = "바닥은 차가워, 계속 누워 있으면 안 돼.",
  ui_story_5029_50290003_35_dialog_content = "내가 부축해 줄게. 조심해.",
  ui_story_5029_50290003_36_dialog_content = "고마워...",
  ui_story_5029_50290003_37_dialog_content = "바이스, 근데 네가 왜 여기 있는 거야?\n미술관에 가서 심미안을 키우겠다던 거 아니었어?",
  ui_story_5029_50290003_38_dialog_content = "헤헤, 가다가 일이 좀 있었거든.",
  ui_story_5029_50290003_39_dialog_content = "어머? PlayerName도 있었어...?",
  ui_story_5029_50290003_40_dialog_content = "안색이 안 좋은 것 같은데, 무슨 일 있어?",
  ui_story_5029_50290003_41_option_content = "별거 아니야.",
  ui_story_5029_50290003_42_dialog_content = "카렌도 있는 걸 보니까 더 안심할 수 있을 것 같아.",
  ui_story_5029_50290003_43_dialog_content = "걱정 마, 하버 시티는 안전하니까.",
  ui_story_5029_50290003_44_option_content = "이 동네 이상해.",
  ui_story_5029_50290003_45_dialog_content = "하버 시티는 길을 어떻게 만들길래 이렇게 미끄러운 거야?",
  ui_story_5029_50290003_45X1_dialog_content = "길은 아주 평평해. 정말 길 문제라고 확신해?",
  ui_story_5029_50290003_45X2_dialog_content = "(카렌... 화가 난 건가? 아, 맞다... 여긴 백야성의 영토였지...\n얼른 다른 얘기로 넘어가자...)",
  ui_story_5029_50290003_46_dialog_content = "갑자기 생각 난 건데... 방금 왠지 꿈을 꾼 것 같아...",
  ui_story_5029_50290003_47_dialog_content = "근데 내가 여기서 뭘 하고 있었는지 기억이 안 나...",
  ui_story_5029_50290003_48_dialog_content = "어? 기억이 안 난다고?",
  ui_story_5029_50290003_49_dialog_content = "너 방금 벽에 붙은 <color=#793f76>현상금 임무 의뢰서</color>를 보더니\n돌아갈 경비를 벌어야겠다고 했어...",
  ui_story_5029_50290003_50_dialog_content = "근데 의뢰서를 떼려다가 발을 헛디뎌서 넘어졌던 거야.",
  ui_story_5029_50290003_51_dialog_content = "의뢰서?",
  ui_story_5029_50290003_52_dialog_content = "응, 지금 PlayerName 네가 들고 있는 그거 말이야.",
  ui_story_5029_50290003_53_dialog_content = "어라... 내가 진짜로 종이를 들고 있네?!",
  ui_story_5029_50290003_54_dialog_content = "탐정을 찾습니다. 보물을 훔쳐 간 범인을 잡아주시면\n고액의 현상금을 드립니다.",
  ui_story_5029_50290003_55_dialog_content = "관심이 있으신 분은 의뢰서를 뜯으세요. 담당자가 알아서 찾아갑니다.",
  ui_story_5029_50290003_56_dialog_content = "...내, 내가 정말 이걸 뜯었다고? 왜 전혀 기억이 안 나는 거지?",
  ui_story_5029_50290003_57_dialog_content = "아까 내가 지나갈 때, 넌 엄청 신난 것 같았어.",
  ui_story_5029_50290003_58_dialog_content = "게다가 날 붙잡고 한참 동안 「고액 현상금」이 얼마일까 얘기했다니까.",
  ui_story_5029_50290003_59_dialog_content = "난 그냥 인기 없는 탐정 소설을 읽었을 뿐이지,\n진짜 탐정이 되고 싶은 건 아니었어.",
