  ui_story_5029_50290003_84_dialog_content = "루우우!",
  ui_story_5029_50290003_85_dialog_content = "허접 사부, 못된 사부, 이렇게 멀리까지 보내놓고\n경비는 쥐꼬리만큼밖에 안 줬다구.",
  ui_story_5029_50290003_86_dialog_content = "그래서 맛있는 것도 못 먹고, 재밌는 게 있어도 못 놀았잖아.\n흥, 두고 보자...",
  ui_story_5029_50290003_87_dialog_content = "피아가 임무도 완수하고 큰돈도 벌 거니까!",
  ui_story_5029_50290003_88_dialog_content = "루우우!",
  ui_story_5029_50290003_89_dialog_content = "피아, 설마 너도 이 임무를 받을 생각은 아니지?",
  ui_story_5029_50290003_90_dialog_content = "잘 봐, 이건 소꿉놀이가 아냐.",
  ui_story_5029_50290003_91_dialog_content = "임무를 받으면 진짜 범죄자와 싸워야만 해.",
  ui_story_5029_50290003_92_dialog_content = "나, 난...",
  ui_story_5029_50290003_93_dialog_content = "흥, 바보 취급하지 마.",
  ui_story_5029_50290003_94_dialog_content = "피아는 제일 사납고 제일 흉폭한 동물도 온순하게 만들었어!\n범죄자 따위가 무서울 리가 없잖아?",
  ui_story_5029_50290003_95_dialog_content = "피아, 범죄자랑 환상동물은 별개야.",
  ui_story_5029_50290003_96_dialog_content = "PlayerName 너까지 내 편 안 들어주는 거야?",
  ui_story_5029_50290003_97_dialog_content = "헤에~ 알았어. 사실 너희도 이 임무를 노리고 있었던 거지?",
  ui_story_5029_50290003_98_dialog_content = "그럼 별일 아니잖아. 우리 <color=#793f76>공평하게 경쟁하자</color>.",
  ui_story_5029_50290003_99_dialog_content = "범인을 잡은 사람이 현상금을 가진다는 거지? 좋은 생각이야!",
  ui_story_5029_50290003_100_dialog_content = "그렇다면 모두 각오하는 게 좋을 거야.",
  ui_story_5029_50290003_101_dialog_content = "난 백야성 호위대에서 오랫동안 활동해서 나름대로 경험이 있으니까.",
  ui_story_5029_50290003_102_dialog_content = "모두...? 그럼 난...?",
  ui_story_5029_50290003_103_dialog_content = "미안합니다. 다들 많이 기다리셨죠?",
  ui_story_5029_50290003_104_dialog_content = "저는 그 현상금 의뢰서에 적힌 담당자 젠이라고 합니다.",
  ui_story_5029_50290003_105_dialog_content = "네 분께서 임무를 받기로 결정하셨다면 절 따라오시죠.",
  ui_story_5029_50290004_1_dialog_content = "PlayerName!",
  ui_story_5029_50290004_2_dialog_content = "......",
  ui_story_5029_50290004_3_dialog_content = "어라, PlayerName, 넘어져서 말도 못 하게 된 거야?",
  ui_story_5029_50290004_4_dialog_content = "키아로, 우리 어떡하지?",
  ui_story_5029_50290004_5_dialog_content = "루우!",
  ui_story_5029_50290004_6_dialog_content = "그래, 난 환상동물 마스터잖아.",
  ui_story_5029_50290004_7_dialog_content = "이럴 때일수록 마스터의 클래스를 보여 줘야지!",
  ui_story_5029_50290004_8_dialog_content = "사부의 노트에 육지 환상동물 기절 시 처방법이 쓰여 있었던 것 같아.",
  ui_story_5029_50290004_8X1_dialog_content = "아이테르한테도 쓸 수 있겠지?",
  ui_story_5029_50290004_9_dialog_content = "아, 찾았어! 정신을 차리려면... 키아로의 인공호흡이 필요하다고?",
  ui_story_5029_50290004_10_dialog_content = "루?",
  ui_story_5029_50290004_11_dialog_content = "크흠...",
  ui_story_5029_50290004_12_dialog_content = "앗, 이제 정신이 들어?!",
  ui_story_5029_50290004_13_option_content = "네 덕분이야, 피아.",
  ui_story_5029_50290004_14_dialog_content = "훗, 천만에~",
  ui_story_5029_50290004_15_dialog_content = "넌 내가 힘들게 잡은 환상동물이야. 널 돌보는 것도 내 의무라구.",
  ui_story_5029_50290004_16_dialog_content = "아, 맞다. 키아로도 도와줬어!",
  ui_story_5029_50290004_17_dialog_content = "루~",
  ui_story_5029_50290004_18_option_content = "많이 좋아졌어.",
  ui_story_5029_50290004_19_dialog_content = "그거야 당연하지.",
  ui_story_5029_50290004_20_dialog_content = "나랑 키아로가 있으니까 문제없을 거야!",
  ui_story_5029_50290004_21_dialog_content = "루!",
  ui_story_5029_50290004_22_option_content = "날 죽일 작정이야?",
  ui_story_5029_50290004_23_dialog_content = "PlayerName, 너...",
  ui_story_5029_50290004_24_dialog_content = "나도 키아로도 좋은 마음으로 도와준 건데, 똑바로 알고 말하는 거 맞아?",
  ui_story_5029_50290004_25_dialog_content = "흥, 역시 아이테르라고 해도 딱히 키울 가치는 없을 것 같네.\n차라리 암귀를 키우고 말지.",
  ui_story_5029_50290004_26_dialog_content = "루!",
  ui_story_5029_50290004_27_option_content = "키아로! 가까이 오지 마!",
  ui_story_5029_50290004_28_dialog_content = "싫으면 싫은 거지, 뭘 그렇게 소리를 지르고 그래?",
  ui_story_5029_50290004_29_dialog_content = "뭐, 그래도 멀쩡한 걸 보니까 키아로가 나설 필요는 없을 것 같네.",
  ui_story_5029_50290004_30_dialog_content = "루우우~",
  ui_story_5029_50290004_31_dialog_content = "방금... 그건 다 꿈이었나?",
  ui_story_5029_50290004_32_dialog_content = "너 아까 넘어지고 지금까지 얼마 되지도 않았는데 꿈까지 꿨단 말이야?",
  ui_story_5029_50290004_33_dialog_content = "아이테르는 개꿈을 잘 꾸는 특성이 있는 걸까?\n으음... 중요한 내용이니까 잘 기록해야겠어.",
  ui_story_5029_50290004_34_dialog_content = "잠깐만, 그런 걸 기록할 필요는 없잖아...",
  ui_story_5029_50290004_35_dialog_content = "어라, PlayerName?",
  ui_story_5029_50290004_36_dialog_content = "바닥에 누워서 뭐 해? 그러다 감기 들어!",
  ui_story_5029_50290004_37_dialog_content = "자, 내 손 잡아.",
  ui_story_5029_50290004_38_option_content = "고, 고마워!",
  ui_story_5029_50290004_39_dialog_content = "그냥 일으켜주는 거 가지고 뭘.",
  ui_story_5029_50290004_40_option_content = "내가 알아서 일어날게.",
  ui_story_5029_50290004_41_dialog_content = "아... 그래.",
  ui_story_5029_50290004_41X1_dialog_content = "으앗...! 쥐가 난 것 같아...",
  ui_story_5029_50290004_42_dialog_content = "그러니까 무리하지 말지...",
  ui_story_5029_50290004_43_dialog_content = "「아이테르는 여자를 만나면 긴장한다...」",
  ui_story_5029_50290004_44_dialog_content = "응? 피아, PlayerName의 행동 습관을 기록하는 거야?",
  ui_story_5029_50290004_45_dialog_content = "맞아! 환상동물의 생활 습관과 표현 방법을 잘 알아야만\n제대로 소통할 수 있거든.",
  ui_story_5029_50290004_46_dialog_content = "난 진짜로 긴장 같은 거 안 했다고!",
  ui_story_5029_50290004_47_dialog_content = "그래? 근데... 손에 쥐고 있는 건 뭐야?",
  ui_story_5029_50290004_48_dialog_content = "어라? 네가 말하기 전까지 전혀 몰랐잖아... 뭐지? 웬 종이...?",
  ui_story_5029_50290004_49_dialog_content = "하! PlayerName! 너 아까 넘어졌었어.",
  ui_story_5029_50290004_49X1_dialog_content = "벽에서 그 종이를 뜯으려다 힘을 너무 줘서 말이야.",
  ui_story_5029_50290004_50_dialog_content = "도대체 뭐가 아이테르를 그렇게 잘 유혹한 거지?",
  ui_story_5029_50290004_51_dialog_content = "얼른 그 종이가 뭔지 보여줘!",
  ui_story_5029_50290004_52_dialog_content = "조심해. 험하게 다루면 찢어진다고...",
  ui_story_5029_50290004_53_dialog_content = "<color=#828282>휘이잉──</color>",
  ui_story_5029_50290004_54_dialog_content = "으아아... 바람에 날려가 버렸어!",
  ui_story_5029_50290004_55_dialog_content = "키아로, 플랜A, 즉시 실행!",
  ui_story_5029_50290004_56_dialog_content = "루!",
  ui_story_5029_50290004_57_dialog_content = "잠깐만, 키아로가 나설 필요는 없을 것 같아. 저기 벌써 누가 주워줬어.",
  ui_story_5029_50290004_58_dialog_content = "너희들이었어?",
  ui_story_5029_50290004_59_dialog_content = "방금 종이를 한 장 주웠는데, 너희들 거야?",
  ui_story_5029_50290004_60_dialog_content = "맞아! 그 종이엔 PlayerName의 비밀이 숨겨져 있어!",
  ui_story_5029_50290004_61_dialog_content = "카렌, 그 종이...",
  ui_story_5029_50290004_62_option_content = "주워줘서 고마워.",
  ui_story_5029_50290004_63_dialog_content = "천만에.",
  ui_story_5029_50290004_64_dialog_content = "사실 나도 거기 뭐가 적혀 있는진 모르지만 말이야.",
  ui_story_5029_50290004_65_option_content = "얼른 이리 줘!",
  ui_story_5029_50290004_65X1_dialog_content = "너 벌써 레디젤 렌치에 가입한 거야?",
  ui_story_5029_50290004_65X2_dialog_content = "어째서 말하는 스타일이 그 녀석들처럼 교양이 없어진 걸까...?",
  ui_story_5029_50290004_66_dialog_content = "아, 아직 거기 뭐가 적혀 있는지 모른단 말이야.",
  ui_story_5029_50290004_67_dialog_content = "또 무슨 유언비어일지도 모르잖아.",
  ui_story_5029_50290004_68_dialog_content = "자, 보면 알 거야.",
  ui_story_5029_50290004_69_dialog_content = "탐정을 찾습니다. 보물을 훔쳐 간 범인을 잡아주시면\n고액의 현상금을 드립니다.",
  ui_story_5029_50290004_70_dialog_content = "관심이 있으신 분은 의뢰서를 뜯으세요. 담당자가 알아서 찾아갑니다.",
  ui_story_5029_50290004_71_dialog_content = "우와, 이거 <color=#793f76>현상금 임무</color>구나!",
  ui_story_5029_50290004_72_dialog_content = "하버 시티는 치안 환경도 좋고 백성들도 부유한데,\n그런 흉악한 사건이 있었단 말이야?",
  ui_story_5029_50290004_73_dialog_content = "...내, 내가 정말 이걸 뜯었다고? 왜 전혀 기억이 안 나는 거지?",
  ui_story_5029_50290004_74_dialog_content = "PlayerName, 네 마음은 충분히 이해해.",
  ui_story_5029_50290004_74X1_dialog_content = "분명히 「고액의 현상금」이라는 단어에 현혹된 거겠지!",
  ui_story_5029_50290004_75_dialog_content = "난 그냥 인기 없는 탐정 소설을 읽었을 뿐이지,\n진짜 탐정이 되고 싶은 건 아니었어.",
  ui_story_5029_50290004_76_dialog_content = "내가 대체 무슨 생각을 하고 있었던 건지 모르겠네...",
  ui_story_5029_50290004_77_dialog_content = "PlayerName, 설마 무서운 건 아니지?",
  ui_story_5029_50290004_78_dialog_content = "그럼 이 일은 피아한테 맡겨! 나랑 키아로는 마침 돈이 궁하거든.",
  ui_story_5029_50290004_79_dialog_content = "루우우!",
  ui_story_5029_50290004_80_dialog_content = "너네 사부가 경비도 안 줬어?",
  ui_story_5029_50290004_81_dialog_content = "허접 사부, 못된 사부, 이렇게 멀리까지 보내놓고\n경비는 쥐꼬리만큼밖에 안 줬다구.",
  ui_story_5029_50290004_82_dialog_content = "그래서 맛있는 것도 못 먹고, 재밌는 게 있어도 못 놀았잖아.\n흥, 두고 보자...",
  ui_story_5029_50290004_83_dialog_content = "피아가 임무도 완수하고 큰돈도 벌 거니까!",
  ui_story_5029_50290004_84_dialog_content = "이상해...",
  ui_story_5029_50290004_85_dialog_content = "왜 이 사람은 영주한테 가서 문제를 해결하지 않는 거지?",
  ui_story_5029_50290004_86_dialog_content = "어쩌면 영주가 이 문제를 해결할 수 없는 건 아닐까...",
  ui_story_5029_50290004_87_dialog_content = "아하하, 그럼 여기 영주한테 피아가 얼마나 대단한지 보여줄게!",
  ui_story_5029_50290004_88_dialog_content = "잘 생각해, 이건 소꿉놀이가 아냐.",
  ui_story_5029_50290004_89_dialog_content = "임무를 받으면 진짜 범죄자와 싸워야만 해.",
  ui_story_5029_50290004_90_dialog_content = "나, 난...",
  ui_story_5029_50290004_91_dialog_content = "흥, 바보 취급하지 마.",
  ui_story_5029_50290004_92_dialog_content = "피아는 제일 사납고 제일 흉폭한 동물도 온순하게 만들었어!\n범죄자 따위가 무서울 리가 없잖아?",
  ui_story_5029_50290004_93_dialog_content = "피아, 범죄자랑 환상동물은 별개야.",
  ui_story_5029_50290004_94_dialog_content = "PlayerName 너까지 내 편 안 들어주는 거야?",
  ui_story_5029_50290004_95_dialog_content = "어쨌든 이 일은 백야성의 속령에서 일어난 사건이니까,\n난 못 본 척 넘어갈 순 없어.",
  ui_story_5029_50290004_96_dialog_content = "백야성 호위대로서 난 백야성의 법률로 이 범인을 심판했으면 해.",
  ui_story_5029_50290004_97_dialog_content = "근데 그러면... 현상금은 못 받는 거 아냐?",
  ui_story_5029_50290004_98_dialog_content = "아~ 이해했어. 다들 피아가 이 일을 맡는 걸 말리는 걸 보니까...",
  ui_story_5029_50290004_99_dialog_content = "사실은 너희도 임무를 차지하고 싶었던 거지?",
  ui_story_5029_50290004_100_dialog_content = "그럼 별일 아니잖아. 우리 <color=#793f76>공평하게 경쟁하자</color>.",
  ui_story_5029_50290004_101_dialog_content = "범인을 잡은 사람이 현상금을 가진다는 거지? 좋은 생각이야!",
  ui_story_5029_50290004_102_dialog_content = "그렇다면 모두 각오하는 게 좋을 거야.",
  ui_story_5029_50290004_103_dialog_content = "난 백야성 호위대에서 오랫동안 활동해서 나름대로 경험이 있으니까.",
  ui_story_5029_50290004_104_dialog_content = "모두...? 그럼 난...?",
  ui_story_5029_50290004_105_dialog_content = "미안합니다. 다들 많이 기다리셨죠?",
  ui_story_5029_50290004_106_dialog_content = "저는 그 현상금 의뢰서에 적힌 담당자 젠이라고 합니다.",
  ui_story_5029_50290004_107_dialog_content = "네 분께서 임무를 받기로 결정하셨다면 절 따라오시죠.",
  ui_story_5029_50290005_1_dialog_content = "잠깐만, 여긴...",
  ui_story_5029_50290005_2_dialog_content = "내가 잘못 본 거 아니지?",
  ui_story_5029_50290005_3_dialog_content = "설마 의뢰인이 <color=#793f76>그 사람</color>이었던 건가?",
  ui_story_5029_50290005_4_dialog_content = "다들 무슨 수수께끼 같은 소릴 하는 거야?\n피아도 알 수 있게 통용어로 얘기해 줄래?",
  ui_story_5029_50290005_5_dialog_content = "여러분, 입구에 서 계실 필요는 없습니다. 들어오세요.",
  ui_story_5029_50290005_6_dialog_content = "영주님은 이미 안에서 탐정 여러분을 기다리고 계십니다.",
  ui_story_5029_50290005_7_dialog_content = "들었어? 「탐정」이래. 저 아저씨 우릴 탐정이라고 불렀어!",
  ui_story_5029_50290005_8_dialog_content = "쉿, 탐정은 이럴 때 진중한 모습을 보여야 되는 거야.",
  ui_story_5029_50290005_9_dialog_content = "메에롱, PlayerName 너 갈수록 허접 사부를 닮아가는 것 같아.",
  ui_story_5029_50290005_10_dialog_content = "탐정 여러분, 환영합니다...",
  ui_story_5029_50290005_11_dialog_content = "<color=#793f76>엘비스</color> 영주, 다시 만났군요.",
  ui_story_5029_50290005_12_dialog_content = "카렌 전하?!",
  ui_story_5029_50290005_13_dialog_content = "전하께서 친구분들과 함께 오실 줄은 정말 몰랐습니다...",
  ui_story_5029_50290005_14_dialog_content = "젠, 이게 대체 어떻게 된 일입니까?\n제가 탐정을 찾으라고 하지 않았습니까?",
  ui_story_5029_50290005_15_dialog_content = "그게...",
  ui_story_5029_50290005_16_dialog_content = "우린 당신이 붙인 현상 임무 의뢰서를 보고 지원하러 온 거예요.",
  ui_story_5029_50290005_17_dialog_content = "여러분은 하버 시티의 손님이십니다.\n손님에게 일을 맡기는 것은 도리가 아닙니다.",
  ui_story_5029_50290005_18_dialog_content = "손님은 현상금 임무를 받으면 안 되는 건가요?",
  ui_story_5029_50290005_19_dialog_content = "헤헤헤, 왠지 지금 손님이 아닌 건 저뿐인 것 같네요.",
  ui_story_5029_50290005_20_dialog_content = "그럼 의뢰는 피아한테만 맡기면 돼요!",
  ui_story_5029_50290005_21_dialog_content = "미안하지만... 그런 뜻은 아닙니다.",
  ui_story_5029_50290005_22_dialog_content = "하버 시티에 오신 분들은 모두 저희의 손님입니다.",
  ui_story_5029_50290005_23_dialog_content = "여러분은 하버 시티를 좀 더 둘러보며 즐기고 싶지 않으십니까?",
  ui_story_5029_50290005_24_dialog_content = "임무를 해결하는 과정도 색다른 체험일 거라고 생각해요.",
  ui_story_5029_50290005_25_dialog_content = "단순한 관광보다 훨씬 더 깊게 이 도시에 대해 알 수 있겠죠.",
  ui_story_5029_50290005_26_dialog_content = "하하하, 여러분께서 실력이 뛰어나고 비범한 기개가\n있으시다는 것은 이미 알고 있습니다.",
  ui_story_5029_50290005_27_dialog_content = "여러분의 도움을 받을 수 있다면 잃어버린 제 보물도\n분명 순조롭게 되찾을 수 있겠지요.",
  ui_story_5029_50290005_28_dialog_content = "알았으니까 얼른 말해줘요. 대체 잃어버린 물건이 뭔데요?",
  ui_story_5029_50290005_29_dialog_content = "제가 잃어버린 것은 한 <color=#793f76>은 재질의 상자</color>입니다.",
  ui_story_5029_50290005_30_dialog_content = "그 상자는 백야성에서 가장 저명한 예술가 레오나르도 씨가\n직접 설계하고 제작한 예술 작품입니다.",
  ui_story_5029_50290005_31_dialog_content = "레오나르도... 왠지 어디서 들어본 것 같은데요?",
  ui_story_5029_50290005_32_dialog_content = "레오나르도는 백야성의 예술사에 여러 번 이름이 언급된\n매우 재능 있는 예술가야.",
  ui_story_5029_50290005_33_dialog_content = "그가 남긴 작품은 지금도 많은 수집가들에게 추앙받고 있어.",
  ui_story_5029_50290005_34_dialog_content = "그중 하나를 당신이 가지고 계실 줄은 몰랐네요.",
  ui_story_5029_50290005_35_dialog_content = "과연 카렌 전하이십니다.\n진작에 전하와 예술 담론을 나눌 수 있었으면 좋았을 텐데 말이지요.",
  ui_story_5029_50290005_36_dialog_content = "아쉽게도 상자는 이미...",
  ui_story_5029_50290005_37_dialog_content = "그런 뜬구름 잡는 얘긴 됐어요. 그래서 그 상자가 어떻게 생겼는데요?",
  ui_story_5029_50290005_38_dialog_content = "맞아요. 좀 더 정확한 정보가 필요해요. 무게나 치수라든지 말이죠...",
  ui_story_5029_50290005_39_dialog_content = "물론 간단한 그림이 있다면 더 좋구요.",
  ui_story_5029_50290005_40_dialog_content = "여러분, 보시지요.",
  ui_story_5029_50290005_41_dialog_content = "급하게 그린 것이지만 부디 도움이 되었으면 좋겠습니다.",
  ui_story_5029_50290005_42_dialog_content = "정말 멋진 그림이네요!\n설계도 같으면서 예술적인 아름다움도 지니고 있어요.",
  ui_story_5029_50290005_43_dialog_content = "설마 아스트라 대륙에서 그림을 못 그리는 건 나뿐인 건가...",
  ui_story_5029_50290005_44_dialog_content = "키아로, 잘 봐. 이걸 찾으면 우린 밥을 먹을 수 있어.",
  ui_story_5029_50290005_45_dialog_content = "루!",
  ui_story_5029_50290005_46_dialog_content = "이 상자는 평소 어디에 두셨죠? 사라졌다는 사실은 언제 아셨나요?",
  ui_story_5029_50290005_47_dialog_content = "상자는 항상 서재의 <color=#793f76>수납장</color> 안에 들어 있었습니다.",
  ui_story_5029_50290005_48_dialog_content = "어제 점심 전에 한 번 꺼내서 살펴봤었는데,\n저녁 식사를 마치고 오니 사라져 버렸습니다.",
  ui_story_5029_50290005_49_dialog_content = "그럼 상자가 없어진 건 <color=#793f76>어제 점심부터 저녁</color> 사이겠네요.",
  ui_story_5029_50290005_50_dialog_content = "그 시간 동안 이 저택에 누가 드나들었죠?",
  ui_story_5029_50290005_51_dialog_content = "출입한 사람은 세 명뿐이었습니다.",
  ui_story_5029_50290005_52_dialog_content = "첫째는 점심에 청소하러 온 <color=#793f76>메이드</color>였습니다.",
  ui_story_5029_50290005_53_dialog_content = "둘째는 오후에 하버 시티를 찾아온 <color=#793f76>백야성 공작</color>이었죠.",
  ui_story_5029_50290005_54_dialog_content = "셋째는 저녁에 와서 투자 계획을 논의했던 <color=#793f76>상인</color>이었습니다.",
  ui_story_5029_50290005_55_dialog_content = "세 사람뿐이라... 확실한가요?",
  ui_story_5029_50290005_56_dialog_content = "그 점은 제가 증언할 수 있습니다.",
  ui_story_5029_50290005_56X1_dialog_content = "점심부터 저녁까지 계속 입구를 지켰거든요.\n출입한 사람은 확실히 그 세 분뿐이었습니다.",
  ui_story_5029_50290005_57_dialog_content = "어제 영주님은 사무로 바쁘셨습니다.\n그래서 그 손님들은 저마다 혼자 저택에서 조금 기다리셔야 했죠.",
  ui_story_5029_50290005_58_dialog_content = "그렇습니다. 마지막 손님과의 이야기가 끝난 후,\n저는 서재 문을 잠그고 저녁 식사를 하러 갔습니다.",
  ui_story_5029_50290005_59_dialog_content = "그럼 서재로 돌아왔을 때 문의 열쇠가 부서진 흔적이 있었나요?",
  ui_story_5029_50290005_60_dialog_content = "아니요, 없었습니다.\n게다가 창문은 모두 <color=#793f76>안쪽에서 자물쇠가 잠겨 있었습니다</color>.",
  ui_story_5029_50290005_61_dialog_content = "그래서 저는 이 저택에 출입했던 그 세 사람을 의심하고 있는 것입니다.",
  ui_story_5029_50290005_62_dialog_content = "수상한 사람이 세 명뿐이라고요? 그럼 사건 해결도 쉬운 거 아니에요?",
  ui_story_5029_50290005_63_dialog_content = "그 세 명을 잡아다 물어보면 되는 거잖아요.",
  ui_story_5029_50290005_64_dialog_content = "이 사건엔 그렇게 할 수 없는 모종의 이유가 있는 거겠지.",
  ui_story_5029_50290005_65_dialog_content = "크흠... 카렌 전하께선 간파하셨군요.",
  ui_story_5029_50290005_66_dialog_content = "그 사람들 중에는 고귀한 백야성 귀족도 있고,\n움브라톤 상회의 추천을 받은 메이드도 있습니다.",
  ui_story_5029_50290005_67_dialog_content = "또한 투자 의향이 있는 상인도 있지요...\n저는 지금의 우호적인 관계를 해치고 싶지는 않습니다.",
  ui_story_5029_50290005_68_dialog_content = "게다가 여러분도 아시겠지만,\n최근 며칠간 거리에서는 축제가 개최되고 있습니다.",
  ui_story_5029_50290005_69_dialog_content = "영주로서 개인적인 일 때문에 모두의 기분을 상하게 만들 순 없습니다.",
  ui_story_5029_50290005_70_dialog_content = "그래서 이 건을 여러분께 말씀드리기 전까지,\n이 일을 아는 사람은 젠 외에는 없었습니다.",
  ui_story_5029_50290005_71_dialog_content = "그러니까 우리가 <color=#793f76>비밀리에 조사</color>하길 바라는 거죠?",
  ui_story_5029_50290005_72_dialog_content = "극비 조사라니... 난이도가 갑자기 확 높아졌네요.",
  ui_story_5029_50290005_73_dialog_content = "힘든 부탁이라는 건 잘 알고 있습니다.\n그러니 여러분은 <color=#793f76>상자를 되찾아 주시기만 하면 됩니다</color>.",
  ui_story_5029_50290005_74_dialog_content = "만약 범인이 정말로 세 분의 손님 중에 있었다면...",
  ui_story_5029_50290005_75_dialog_content = "스스로 떠나시도록 제가 방법을 생각해 보겠습니다.",
  ui_story_5029_50290006_1_dialog_content = "영주님은 축제 관련 사무를 보러 가셨습니다.",
  ui_story_5029_50290006_2_dialog_content = "이제 여러분께선 자유롭게 저택 안을 조사하셔도 됩니다.",
  ui_story_5029_50290006_3_dialog_content = "무슨 일이 있으시면 저는 홀에 있을 테니 언제든지 말씀하세요.",
  ui_story_5029_50290006_4_dialog_content = "영주님께 여쭤보실 게 있다면 제가 전해드리겠습니다.",
  ui_story_5029_50290006_5_option_content = "(젠에게 말을 건다)",
  ui_story_5029_50290006_6_dialog_content = "뭔가 궁금한 점이 있으십니까?",
  ui_story_5029_50290006_7_option_content = "(저택의 쓰임새)",
  ui_story_5029_50290006_8_dialog_content = "이 저택은 영주님의 <color=#793f76>장서관</color>이고, 평소 이곳에서 사무를 보십니다.",
  ui_story_5029_50290006_9_dialog_content = "영주님은 대부분의 시간을 홀로 이 집에서 보내고 계시죠.",
  ui_story_5029_50290006_10_dialog_content = "때로는 친한 친구분과 만나기도 하십니다.",
  ui_story_5029_50290006_11_dialog_content = "열쇠도 영주님께서 직접 가지고 계십니다.",
  ui_story_5029_50290006_12_dialog_content = "다른 질문이 더 있으십니까?",
  ui_story_5029_50290006_13_option_content = "(저택의 구조)",
  ui_story_5029_50290006_14_dialog_content = "이 저택은 2층 건물입니다.",
  ui_story_5029_50290006_15_dialog_content = "1층은 홀이 있고, 작은 카페도 있습니다.",
  ui_story_5029_50290006_16_dialog_content = "2층은 영주님의 서재입니다.",
  ui_story_5029_50290006_17_dialog_content = "다른 질문이 더 있으십니까?",
  ui_story_5029_50290006_18_option_content = "당신은...?",
  ui_story_5029_50290006_19_dialog_content = "저는 영주님의 경호원 젠이라고 합니다.",
  ui_story_5029_50290006_20_dialog_content = "전에는 부두의 평범한 짐꾼이었습니다.",
  ui_story_5029_50290006_21_dialog_content = "하지만 영주님께서 좋게 봐주신 덕에 오늘의 제가 있게 됐죠.",
  ui_story_5029_50290006_22_dialog_content = "다른 질문이 더 있으십니까?",
  ui_story_5029_50290006_23_option_content = "(없다)",
  ui_story_5029_50290006_24_dialog_content = "만약 또 질문이 있으시면 언제든지 말씀하세요.",
  ui_story_5029_50290006_25_dialog_content = "알았어요, 고마워요.",
  ui_story_5029_50290006_26_option_content = "(적당히 둘러본다)",
  ui_story_5029_50290006_27_dialog_content = "다들 조사는 시작했어?",
  ui_story_5029_50290006_28_dialog_content = "흥.",
  ui_story_5029_50290006_29_dialog_content = "......",
  ui_story_5029_50290006_30_dialog_content = "......",
  ui_story_5029_50290006_31_dialog_content = "(왠지 어색한 분위기네...)",
  ui_story_5029_50290006_32_dialog_content = "(설마 세 사람, 정말 이 일을 가지고 승부하려는 건가?)",
  ui_story_5029_50290006_33_dialog_content = "(아니겠지... 그럼 나까지 경쟁 상대가 되는 거야?)",
  ui_story_5029_50290006_34_dialog_content = "(어떡하지...)",
  ui_story_5029_50290006_35_option_content = "(카렌을 찾아간다)",
  ui_story_5029_50290006_36_dialog_content = "카렌...",
  ui_story_5029_50290006_37_dialog_content = "무슨 일이야?",
  ui_story_5029_50290006_38_option_content = "너랑 같이 조사하고 싶어.",
  ui_story_5029_50290006_39_dialog_content = "나랑 같이...? 좋아.",
  ui_story_5029_50290006_40_dialog_content = "대신 나도 널 테스트해 봐야겠어.",
  ui_story_5029_50290006_41_option_content = "힘내!",
  ui_story_5029_50290006_42_dialog_content = "고마워.",
  ui_story_5029_50290006_43_dialog_content = "절대 백야성 호위대의 이름을 부끄럽게 만들지 않겠어.",
  ui_story_5029_50290006_44_dialog_content = "(어? 이렇게 그냥 가 버리는 거야?)",
  ui_story_5029_50290006_45_dialog_content = "(내가 뭔가 말을 잘못했나...)",
  ui_story_5029_50290006_46_option_content = "아무것도 아냐.",
  ui_story_5029_50290006_47_dialog_content = "그래. 그럼 난 조사를 계속할게.",
  ui_story_5029_50290006_48_dialog_content = "(카렌, 방금 그 눈빛은 어떻게 된 거지... 얼어붙는 줄 알았잖아.)",
  ui_story_5029_50290006_49_dialog_content = "(역시 나도 나대로 분발하는 게 좋겠어.)",
  ui_story_5029_50290006_50_dialog_content = "(어딜 살펴볼까?)",
  ui_story_5029_50290006_51_option_content = "(바이스를 찾아간다)",
  ui_story_5029_50290006_52_dialog_content = "바이스...",
  ui_story_5029_50290006_53_dialog_content = "PlayerName, 왜 그래?",
  ui_story_5029_50290006_54_option_content = "너랑 같이 조사하고 싶어.",
  ui_story_5029_50290006_55_dialog_content = "마침 나도 계속 네가 날 찾아오길 기다렸어.",
  ui_story_5029_50290006_56_dialog_content = "근데 문제가 하나 있어...",
  ui_story_5029_50290006_57_option_content = "힘내!",
  ui_story_5029_50290006_58_dialog_content = "걱정 마. 물론 열심히 할 거니까.",
  ui_story_5029_50290006_59_dialog_content = "반드시 현상금을 손에 넣을게!",
  ui_story_5029_50290006_60_dialog_content = "(어? 그렇다고 그렇게 빨리 가버릴 건 없잖아...)",
  ui_story_5029_50290006_61_option_content = "아무것도 아냐.",
  ui_story_5029_50290006_62_dialog_content = "그래.",
  ui_story_5029_50290006_63_dialog_content = "(바이스, 오늘 왠지 이상하네...)",
  ui_story_5029_50290006_64_dialog_content = "(역시 나도 나대로 분발하는 게 좋겠어.)",
  ui_story_5029_50290006_65_dialog_content = "(어딜 살펴볼까?)",
  ui_story_5029_50290006_66_option_content = "(피아를 찾아간다)",
  ui_story_5029_50290006_67_dialog_content = "피아...",
  ui_story_5029_50290006_68_dialog_content = "뭐야?",
  ui_story_5029_50290006_69_option_content = "너랑 같이 조사하고 싶어.",
  ui_story_5029_50290006_70_dialog_content = "진짜~?",
  ui_story_5029_50290006_71_dialog_content = "크흠, 나한텐 이미 키아로가 있지만, 일손이 많아서 나쁠 건 없으니까.",
  ui_story_5029_50290006_72_option_content = "힘내!",
  ui_story_5029_50290006_73_dialog_content = "흥, 말 안 해도 열심히 할 거거든.",
  ui_story_5029_50290006_74_dialog_content = "피아랑 키아로는 최선을 다할 거라구.",
  ui_story_5029_50290006_75_dialog_content = "(이 녀석, 설마 나까지 경쟁 상대로 생각하는 건가?)",
  ui_story_5029_50290006_76_option_content = "아무것도 아냐.",
  ui_story_5029_50290006_77_dialog_content = "흥, 그럼 난 사건을 해결할 영감을 얻어야 되니까 방해하지 마.",
  ui_story_5029_50290006_78_dialog_content = "(피아, 오늘은 왠지 거리감이 느껴지는데...)",
  ui_story_5029_50290006_79_dialog_content = "(역시 나도 나대로 분발하는 게 좋겠어.)",
  ui_story_5029_50290006_80_dialog_content = "(어딜 살펴볼까?)",
  ui_story_5029_50290006_81_option_content = "(혼자서 조사한다)",
  ui_story_5029_50290006_82_dialog_content = "(다들 바쁜 모양이네.)",
  ui_story_5029_50290006_83_dialog_content = "(역시 혼자서 알아보자...)",
  ui_story_5029_50290007_1_dialog_content = "이렇게 큰 저택을 어디서부터 조사해야 할까?",
  ui_story_5029_50290007_2_dialog_content = "어디 보자...",
  ui_story_5029_50290007_3_option_content = "(서재)",
  ui_story_5029_50290007_4_dialog_content = "책장이 정말 많네... 이거 완전 도서관 같잖아?",
  ui_story_5029_50290007_5_dialog_content = "엘비스는 여명 아카데미 시절부터 책벌레였고,\n성적도 최상위권이었다고 들었어.",
  ui_story_5029_50290007_6_dialog_content = "너보다 성적이 좋은 사람이 있을 것 같지는 않은데.",
  ui_story_5029_50290007_7_dialog_content = "......",
  ui_story_5029_50290007_8_dialog_content = "원래라면 난 엘비스를 선배라고 불러야 해.",
  ui_story_5029_50290007_9_dialog_content = "뭐, 지금 그런 걸 생각할 시간은 없어. 조사를 시작하자.",
  ui_story_5029_50290007_10_dialog_content = "어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_11_dialog_content = "생각해 볼게!",
  ui_story_5029_50290007_12_option_content = "(첫 번째 책장)",
  ui_story_5029_50290007_13_dialog_content = "이 책꽂이에 놓여 있는 책... 왠지 익숙한데? 어디서 본 것 같아.",
  ui_story_5029_50290007_14_dialog_content = "《아카나미 사메노스케 전기 제1권》?",
  ui_story_5029_50290007_15_dialog_content = "이 책은... 항상 가장 중요한 타이밍에 내용을 끊어버려서\n계속 읽게 만들었던 기억이 나.",
  ui_story_5029_50290007_16_dialog_content = "그런 통속소설은 영주의 취향은 아닐 것 같은데...",
  ui_story_5029_50290007_17_dialog_content = "난 책에는 귀천이 따로 없다고 생각해.\n재미있으면 당연히 인기가 있는 법이야.",
  ui_story_5029_50290007_18_dialog_content = "...아무래도 책에 대해서는 내 식견이 좁았던 모양이네.",
  ui_story_5029_50290007_19_dialog_content = "근데 여긴 왜 1권밖에 없지?\n설마 영주님은 전권 소장의 유혹을 참을 수 있는 건가?",
  ui_story_5029_50290007_20_dialog_content = "그건 확실히 이상한걸. 이따가 젠한테 어떻게 된 건지 물어봐야겠어.",
  ui_story_5029_50290007_21_dialog_content = "또 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_22_option_content = "(책상)",
  ui_story_5029_50290007_23_dialog_content = "책상 위에 놓여있는 저 책...\n왠지 다른 책들이랑은 조금 느낌이 다른 것 같아.",
  ui_story_5029_50290007_24_dialog_content = "그래? 어디 볼까.",
  ui_story_5029_50290007_25_dialog_content = "<color=#828282>툭!</color>",
  ui_story_5029_50290007_26_dialog_content = "이, 이런...",
  ui_story_5029_50290007_27_dialog_content = "무슨 일입니까?\n아니... 영주님께서 가장 아끼시는 고서를 망가트리신 겁니까?!",
  ui_story_5029_50290007_28_dialog_content = "지금 당장 이 일을 영주님께 보고하겠습니다!",
  ui_story_5029_50290007_29_dialog_content = "이, 일부러 그런 건 아니에요...",
  ui_story_5029_50290007_30_dialog_content = "이곳의 영주는 합리적인 사람이야.\n내가 가서 해명해줄 테니까 걱정하지 마.",
  ui_story_5029_50290007_31_dialog_content = "그것보다 또 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_32_option_content = "(수납장)",
  ui_story_5029_50290007_33_dialog_content = "영주님은 상자를 계속 이 수납장에 넣어 뒀었다고 했어.",
  ui_story_5029_50290007_34_dialog_content = "음... 주변에 특별한 흔적은 없어...\n창문도 영주가 말했던 것처럼 억지로 열리지도 않았어.",
  ui_story_5029_50290007_35_dialog_content = "근데 영주님도 너무 부주의한 거 아냐?\n그렇게 귀중한 물건을 놓고도 수납장에 자물쇠 하나 없잖아.",
  ui_story_5029_50290007_36_dialog_content = "영주가 그린 그림을 봤을 땐 은 상자에 자물쇠가 달려 있었어.",
  ui_story_5029_50290007_37_dialog_content = "그건 좀 이상하네...",
  ui_story_5029_50290007_38_dialog_content = "어쩌면 상자 안에 뭔가 더 귀중한 물건이 들어 있었을지도 몰라.",
  ui_story_5029_50290007_39_dialog_content = "그것도 왠지 궁금해지는걸.",
  ui_story_5029_50290007_40_dialog_content = "그것보다 또 신경 쓰이는 곳은 없어?",
  ui_story_5029_50290007_41_option_content = "이젠 없어.",
  ui_story_5029_50290007_42_dialog_content = "딱히 특별한 점은 더 없는 것 같아.",
  ui_story_5029_50290007_43_dialog_content = "다른 방을 보러 가 볼까?",
  ui_story_5029_50290007_44_option_content = "(홀)",
  ui_story_5029_50290007_45_dialog_content = "홀은 여러 방으로 통하니까, 뭔가 유용한 단서를 찾을 수 있을지도 몰라.",
  ui_story_5029_50290007_46_dialog_content = "어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_47_dialog_content = "생각해 볼게!",
  ui_story_5029_50290007_48_option_content = "(화분)",
  ui_story_5029_50290007_49_dialog_content = "뭐 해?",
  ui_story_5029_50290007_50_dialog_content = "창가의 화분 안에 뭔가 단서가 없는지 보고 있었어...",
  ui_story_5029_50290007_51_dialog_content = "꽤 꼼꼼하게 조사하는구나.",
  ui_story_5029_50290007_52_dialog_content = "어머? 엘비스는 사막 식물을 기르고 있었구나.",
  ui_story_5029_50290007_53_dialog_content = "이 식물엔 가시가 있으니까 조심해.",
  ui_story_5029_50290007_54_dialog_content = "여기 좀 봐. 왠지 뭔가가 이 화분에 부딪혔던 흔적 같아.",
  ui_story_5029_50290007_55_dialog_content = "가시도 많이 떨어졌어. 부딪힌 사람 엄청 아팠겠네...",
  ui_story_5029_50290007_56_dialog_content = "또 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_57_option_content = "(티 테이블)",
  ui_story_5029_50290007_58_dialog_content = "이 티 테이블에 놓여 있는 책... 왠지 익숙한데? 어디서 본 것 같아.",
  ui_story_5029_50290007_59_dialog_content = "《아카나미 사메노스케 전기 제1권》?",
  ui_story_5029_50290007_60_dialog_content = "이 책은... 항상 가장 중요한 타이밍에 내용을 끊어버려서\n계속 읽게 만들었던 기억이 나.",
  ui_story_5029_50290007_61_dialog_content = "그런 통속소설은 영주의 취향은 아닐 것 같은데...",
  ui_story_5029_50290007_62_dialog_content = "난 책에는 귀천이 따로 없다고 생각해.\n재미있으면 당연히 인기가 있는 법이야.",
  ui_story_5029_50290007_63_dialog_content = "...아무래도 책에 대해서는 내 식견이 좁았던 모양이네.",
  ui_story_5029_50290007_64_dialog_content = "근데 여긴 왜 1권밖에 없지?\n설마 영주님은 전권 소장의 유혹을 참을 수 있는 건가?",
  ui_story_5029_50290007_65_dialog_content = "그건 확실히 이상한걸. 이따가 젠한테 어떻게 된 건지 물어봐야겠어.",
  ui_story_5029_50290007_66_dialog_content = "또 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_67_option_content = "(장식품)",
  ui_story_5029_50290007_68_dialog_content = "무척 예쁜 소라고둥이네...",
  ui_story_5029_50290007_69_dialog_content = "전에 들은 적 있어. 소라고둥한테 소원을 말하면...",
  ui_story_5029_50290007_70_dialog_content = "소원이 이루어진다고?",
  ui_story_5029_50290007_71_dialog_content = "카렌도 알고 있었구나!",
  ui_story_5029_50290007_72_dialog_content = "그럼 좋은 기회니까 이 소라고둥한테 소원을 빌어볼래?",
  ui_story_5029_50290007_73_dialog_content = "너 의외로 동심을 간직하고 있구나. 아직도 그런 동화를 믿다니 말이야.",
  ui_story_5029_50290007_74_dialog_content = "그런 건 아닌데...\n난 그냥 말로 꺼내면 실현될 가능성이 더 높아진다고 생각했거든.",
  ui_story_5029_50290007_75_dialog_content = "일종의 심리 암시 같은 느낌이랄까?",
  ui_story_5029_50290007_76_dialog_content = "심리 암시라...",
  ui_story_5029_50290007_77_dialog_content = "크흠, 그럼 소라고둥한테 소원을 비는 게 너무 유치한 것 같으면,\n넌 나한테 얘기해주면 돼.",
  ui_story_5029_50290007_78_dialog_content = "그럼 내가 소원이 이루어지게 도와줄 수 있을지도 모르잖아.",
  ui_story_5029_50290007_79_dialog_content = "음, 그래? 그럼 난 우리가 어서 유의미한 단서를 찾았으면 좋겠어.",
  ui_story_5029_50290007_80_dialog_content = "그럼 지금 바로 다음 장소를 조사하러 가자!",
  ui_story_5029_50290007_81_option_content = "이젠 없어.",
  ui_story_5029_50290007_82_dialog_content = "딱히 특별한 점은 더 없는 것 같아.",
  ui_story_5029_50290007_83_dialog_content = "다른 방을 보러 가 볼까?",
  ui_story_5029_50290007_84_option_content = "(카페)",
  ui_story_5029_50290007_85_dialog_content = "카페에 가실 겁니까? 이쪽으로 가시죠.",
  ui_story_5029_50290007_86_dialog_content = "영주님께서는 일하실 때 방해를 받는 것을 싫어하십니다.\n그래서 이쪽에 카페가 생긴 겁니다.",
  ui_story_5029_50290007_87_dialog_content = "때로는 영주님께서 직접 손님들에게 커피를 만들어 주실 때도 있습니다.",
  ui_story_5029_50290007_88_dialog_content = "PlayerName, 어때? 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_89_dialog_content = "생각해 볼게!",
  ui_story_5029_50290007_90_option_content = "(의자)",
  ui_story_5029_50290007_91_dialog_content = "잠깐 앉아서 좀 쉬지 않을래?",
  ui_story_5029_50290007_92_dialog_content = "괜찮아, 아직 안 피곤해.",
  ui_story_5029_50290007_93_dialog_content = "그래... 그럼 나도 계속 조사할게!",
  ui_story_5029_50290007_94_dialog_content = "어라, 의자 위에 신문이 있는데?",
  ui_story_5029_50290007_95_dialog_content = "움브라톤에서 어제 발행된 신문인데...",
  ui_story_5029_50290007_96_dialog_content = "엘비스는 이렇게 빨리 손에 넣을 수 있는 거구나.",
  ui_story_5029_50290007_97_dialog_content = "「아이테르가 오랜 시간 동안 움브라톤에 모습을 드러내지 않자,\n그의 팬클럽 테르테르는 그의 사생활을 알아내기 위해\n거액의 돈을 준비했다...」",
  ui_story_5029_50290007_98_dialog_content = "이게 대체 무슨 기사야?",
  ui_story_5029_50290007_99_dialog_content = "크흠, 이 사건이랑은 확실히 관계가 없겠어.",
  ui_story_5029_50290007_100_dialog_content = "뭐, 됐어. 또 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_101_option_content = "(카운터)",
  ui_story_5029_50290007_102_dialog_content = "카운터에 놓여 있는 책... 왠지 익숙한데? 어디서 본 것 같아.",
  ui_story_5029_50290007_103_dialog_content = "《아카나미 사메노스케 전기 제1권》?",
  ui_story_5029_50290007_104_dialog_content = "이 책은... 항상 가장 중요한 타이밍에 내용을 끊어버려서\n계속 읽게 만들었던 기억이 나.",
  ui_story_5029_50290007_105_dialog_content = "그런 통속소설은 영주의 취향은 아닐 것 같은데...",
  ui_story_5029_50290007_106_dialog_content = "난 책에는 귀천이 따로 없다고 생각해.\n재미있으면 당연히 인기가 있는 법이야.",
  ui_story_5029_50290007_107_dialog_content = "...아무래도 책에 대해서는 내 식견이 좁았던 모양이네.",
  ui_story_5029_50290007_108_dialog_content = "근데 여긴 왜 1권밖에 없지?\n설마 영주님은 전권 소장의 유혹을 참을 수 있는 건가?",
  ui_story_5029_50290007_109_dialog_content = "그건 확실히 이상한걸. 이따가 젠한테 어떻게 된 건지 물어봐야겠어.",
  ui_story_5029_50290007_110_dialog_content = "또 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_111_option_content = "(벽)",
  ui_story_5029_50290007_112_dialog_content = "벽에 예쁜 유화가 잔뜩 걸려있네.",
  ui_story_5029_50290007_113_dialog_content = "무척 과장된 붓놀림이지만, 강렬한 충격과 압박감을 표현하고 있어.",
  ui_story_5029_50290007_114_dialog_content = "엘비스의 내면은 분명히 겉모습처럼 연약하진 않을 거야.",
  ui_story_5029_50290007_115_dialog_content = "어? 이 그림... 어디서 본 것 같은데...",
  ui_story_5029_50290007_116_dialog_content = "이건?!",
  ui_story_5029_50290007_117_dialog_content = "아... 생각났어.",
  ui_story_5029_50290007_118_dialog_content = "이건 솔라드 씨의 젊은 시절 초상화 아냐?",
  ui_story_5029_50290007_119_dialog_content = "엘비스가 어째서 이 초상화의 모사본을 가지고 있는 거지?",
  ui_story_5029_50290007_120_dialog_content = "백야성에 대한 충성을 드러내기 위해서 아닐까? 하하하.",
  ui_story_5029_50290007_121_dialog_content = "어쩌면 카렌 네 초상화도 가지고 있을지도 몰라.",
  ui_story_5029_50290007_122_dialog_content = "그게 내 눈에 띄지 않았으면 좋겠네...",
  ui_story_5029_50290007_123_dialog_content = "이 얘긴 그만하자. 또 어디 신경 쓰이는 곳 있어?",
  ui_story_5029_50290007_124_option_content = "이젠 없어.",
  ui_story_5029_50290007_125_dialog_content = "딱히 특별한 점은 더 없는 것 같아.",
  ui_story_5029_50290007_126_dialog_content = "다른 방을 보러 가 볼까?",
  ui_story_5029_50290007_127_option_content = "더 볼 필요는 없겠어.",
  ui_story_5029_50290007_128_dialog_content = "왠지 찾아볼 만한 곳은 전부 본 것 같아.",
  ui_story_5029_50290007_129_dialog_content = "그래?",
  ui_story_5029_50290007_130_dialog_content = "난 지금 의심스러운 곳이 하나 있거든...\n다시 한번 가서 확인해 볼게!",
  ui_story_5029_50290007_131_dialog_content = "그럼 난 소파에 앉아서 좀 쉬고 있을게.",
  ui_story_5029_50290008_1_dialog_content = "일단 어디부터 찾는 게 좋을까?",
  ui_story_5029_50290008_2_dialog_content = "어디 보자...",
  ui_story_5029_50290008_3_option_content = "(서재)",
  ui_story_5029_50290008_4_dialog_content = "책장이 정말 많네... 이거 완전 도서관 같잖아?",
  ui_story_5029_50290008_5_dialog_content = "마음에 들면 너도 콜로서스에 도서실을 하나 만들면 되잖아.",
  ui_story_5029_50290008_6_dialog_content = "아, 그렇네. 이번에 현상금을 받게 되면 그 돈으로 책을 사는 것도 좋겠어.",
  ui_story_5029_50290008_7_dialog_content = "그렇게 생각하니까 더 의욕이 생기는걸! 자, 얼른 증거를 찾아보자.",
  ui_story_5029_50290008_8_dialog_content = "어딜 찾아볼까...",
  ui_story_5029_50290008_9_option_content = "(첫 번째 책장)",
  ui_story_5029_50290008_10_dialog_content = "영주님이 보는 책들, 장르가 너무 다양한 거 아냐?",
  ui_story_5029_50290008_11_dialog_content = "제목조차 뭐라고 읽는지 알 수 없는 책들도 잔뜩 있어...",
  ui_story_5029_50290008_12_dialog_content = "일루미나에도 큰 도서관이 있어.\n공부하고 싶으면 나랑 같이 일루미나로 가서...",
  ui_story_5029_50290008_13_dialog_content = "어라? 잠깐만!\n《「잃어버린 비경」의 실례를 통한 아인족의 사회 분업 탐구》...",
  ui_story_5029_50290008_14_dialog_content = "이건 아인족 사회에 대한 최신 연구 성과잖아?",
  ui_story_5029_50290008_15_dialog_content = "나도 아직 읽어본 적 없는 건데!",
  ui_story_5029_50290008_16_dialog_content = "그...그럼 난 옆에 있는 통속소설이나 읽고 있을게...",
  ui_story_5029_50290008_17_dialog_content = "아, 아니지, 계속 단서를 찾을게!",
  ui_story_5029_50290008_18_option_content = "(두 번째 책장)",
  ui_story_5029_50290008_19_dialog_content = "바이스, 봐! 이 책 표지에 보석이 박혀 있어!",
  ui_story_5029_50290008_20_dialog_content = "왠지 영주의 가계도 같네.",
  ui_story_5029_50290008_21_dialog_content = "책 장식이 너무 호화로운 거 아냐?\n이거 한 권 값으로도 며칠 분의 식량을 살 수 있을 것 같아.",
  ui_story_5029_50290008_22_dialog_content = "만약... 나도 내 모든 일족의 이름을 알 수 있다면,\n마찬가지로 이런 책을 만들고 싶었을 거야.",
  ui_story_5029_50290008_23_dialog_content = "PlayerName...",
  ui_story_5029_50290008_24_dialog_content = "그럼 지금부터 당장 저축을 시작하자.",
  ui_story_5029_50290008_25_dialog_content = "...하, 하하하.",
  ui_story_5029_50290008_26_dialog_content = "그, 그럼 계속 단서를 찾을게!",
  ui_story_5029_50290008_27_option_content = "(수납장)",
  ui_story_5029_50290008_28_dialog_content = "영주님은 상자를 계속 이 수납장에 넣어 뒀었다고 했어.",
  ui_story_5029_50290008_29_dialog_content = "근데 이 수납장엔 자물쇠가 없어.",
  ui_story_5029_50290008_30_dialog_content = "안은 텅 비었어, 아무것도 안 들어 있어.",
  ui_story_5029_50290008_31_dialog_content = "나라면 분명 몇 겹으로 자물쇠를 채웠을 텐데 말이야.",
  ui_story_5029_50290008_32_dialog_content = "잘 때도 열쇠를 베개 밑에 숨겨뒀겠지!",
  ui_story_5029_50290008_33_dialog_content = "아~ 그렇구나!",
  ui_story_5029_50290008_34_dialog_content = "그럼 다음엔 네 베개 밑에 보물 열쇠가 있는지 살펴봐야겠네.",
  ui_story_5029_50290008_35_dialog_content = "......",
  ui_story_5029_50290008_36_dialog_content = "그럼 계속 단서를 찾을게!",
  ui_story_5029_50290008_37_option_content = "이제 충분히 찾은 것 같아.",
  ui_story_5029_50290008_38_dialog_content = "다른 방을 살펴볼까?",
  ui_story_5029_50290008_39_dialog_content = "그래, 어디로 갈까?",
  ui_story_5029_50290008_40_option_content = "(홀)",
  ui_story_5029_50290008_41_dialog_content = "이렇게 큰 저택을 영주님은 일을 할 때만 쓰는 건가?",
  ui_story_5029_50290008_42_dialog_content = "그냥 여기서 살아도 될 것 같은데...",
  ui_story_5029_50290008_43_dialog_content = "넌 콜로서스도 있으면서 이런 집이 부러워?",
  ui_story_5029_50290008_44_dialog_content = "헤헤, 그냥 신기해서 그래.",
  ui_story_5029_50290008_45_dialog_content = "나도 농담한 거야. 얼른 단서를 찾자.",
  ui_story_5029_50290008_46_dialog_content = "어딜 찾아볼까...",
  ui_story_5029_50290008_47_option_content = "(화분)",
  ui_story_5029_50290008_48_dialog_content = "화분 안에 뭔가 장치가 숨겨져 있진 않을까?",
  ui_story_5029_50290008_49_dialog_content = "넌 정말 상상력이 풍부하다니까.",
  ui_story_5029_50290008_50_dialog_content = "음... 아쉽지만 아무것도 없네.",
  ui_story_5029_50290008_51_dialog_content = "근데 이 꽃 진짜 예쁜 것 같아. 게다가 뭔가 상쾌한 향이 나는데? 킁킁...",
  ui_story_5029_50290008_52_dialog_content = "...뭐지? 갑자기 머리가 좀 어지러워.",
  ui_story_5029_50290008_53_dialog_content = "설마 이 꽃에 무슨 문제가 있는 건가...",
  ui_story_5029_50290008_54_dialog_content = "젠 씨, 얼른 와서 좀 보세요...\n이 꽃, 혹시 누가 독을 주입한 건 아닐까요?",
  ui_story_5029_50290008_55_dialog_content = "아니요, 이건 올렌더 캑터스라는 꽃입니다. 원래부터 독성을 가지고 있죠.",
  ui_story_5029_50290008_56_dialog_content = "그래도 먹지만 않으면 아무 일도 없을 겁니다.",
  ui_story_5029_50290008_57_dialog_content = "왜 독성이 있는 꽃을 실내에 장식하고 있는 거죠?\n귀족의 취미라는 건 정말 이해할 수가 없다니까요...",
  ui_story_5029_50290008_58_dialog_content = "PlayerName, 내가 부축해 줄게. 소파에서 좀 쉬고 있어.",
  ui_story_5029_50290008_59_dialog_content = "괜찮아... 계속 조사할 수 있어!",
  ui_story_5029_50290008_60_option_content = "(소파)",
  ui_story_5029_50290008_61_dialog_content = "진짜 푹신한 소파네...",
  ui_story_5029_50290008_62_dialog_content = "콜로서스에도 이런 소파가 있다면 좋을 텐데 말이야.",
  ui_story_5029_50290008_63_dialog_content = "크흠, 너 그 소파가 얼마짜리인지 분명히 모를 것 같네.",
  ui_story_5029_50290008_64_dialog_content = "......",
  ui_story_5029_50290008_65_dialog_content = "역시 그냥 서 있을래.",
  ui_story_5029_50290008_66_dialog_content = "왜 그래?",
  ui_story_5029_50290008_67_dialog_content = "사실... 난 풀더미 위에 앉는 것도 편안하고 좋은 것 같아!",
  ui_story_5029_50290008_68_dialog_content = "휴~ 그럼 오늘도 지출 절감 임무는 성공했네~",
  ui_story_5029_50290008_69_dialog_content = "크흠, 그럼 조사를 계속하자.",
  ui_story_5029_50290008_70_option_content = "(장식품)",
  ui_story_5029_50290008_71_dialog_content = "PlayerName, 이거 좀 바! 소라고둥이 있어!",
  ui_story_5029_50290008_72_dialog_content = "예쁘네. 이렇게 큰 소라고둥은 잘 없지 않아?",
  ui_story_5029_50290008_73_dialog_content = "어느 외딴섬에서는 조개나 소라고둥을 화폐로 사용한다고 들었어.",
  ui_story_5029_50290008_74_dialog_content = "그럼 이 소라고둥도 가치가 높다는 거겠지?",
  ui_story_5029_50290008_75_dialog_content = "아쉽지만 여기선 나이티움밖에 못 쓰잖아.",
  ui_story_5029_50290008_76_dialog_content = "그래도 네가 마음에 든다면 같이 바다에 가서 좀 찾아보자...",
  ui_story_5029_50290008_77_dialog_content = "이것보다 더 크고 예쁜 소라고둥을 찾을 수 있을지도 모르니까.",
  ui_story_5029_50290008_78_dialog_content = "응. 그럼 약속이야~",
  ui_story_5029_50290008_79_dialog_content = "물론이지! 그럼 조사를 계속하자.",
  ui_story_5029_50290008_80_option_content = "이제 충분히 찾은 것 같아.",
  ui_story_5029_50290008_81_dialog_content = "다른 방을 살펴볼까?",
  ui_story_5029_50290008_82_dialog_content = "그래, 어디로 갈까?",
  ui_story_5029_50290008_83_option_content = "(카페)",
  ui_story_5029_50290008_84_dialog_content = "카페에 가실 겁니까? 이쪽으로 가시죠.",
  ui_story_5029_50290008_85_dialog_content = "영주님께서는 일하실 때 방해를 받는 것을 싫어하십니다.\n그래서 이쪽에 카페가 생긴 겁니다.",
  ui_story_5029_50290008_86_dialog_content = "때로는 영주님께서 직접 손님들에게 커피를 만들어 주실 때도 있습니다.",
  ui_story_5029_50290008_87_dialog_content = "이 저택은 정말 별난 것 같아.",
  ui_story_5029_50290008_88_dialog_content = "물건이 너무 많아서 어디부터 찾아야 할지 모르겠어...",
  ui_story_5029_50290008_89_option_content = "(커피잔)",
  ui_story_5029_50290008_90_dialog_content = "잔의 디자인이랑 모양이 하나하나 전부 달라!",
  ui_story_5029_50290008_91_dialog_content = "이 잔들만 가지고도 전시회를 열 수 있겠는데?",
  ui_story_5029_50290008_92_dialog_content = "어라, 이상하네. 이 컵엔 왜 커피가 남아 있지?",
  ui_story_5029_50290008_93_dialog_content = "어제 손님 중 누군가가 먹다 남긴 건 아닐까?",
  ui_story_5029_50290008_94_dialog_content = "<color=#828282>딸랑...</color>",
  ui_story_5029_50290008_95_dialog_content = "안에 뭐가 들어 있는 것 같은데?",
  ui_story_5029_50290008_96_dialog_content = "꺼내 보자...",
  ui_story_5029_50290008_97_dialog_content = "앗, 휘장이잖아... 어디서 본 것 같은데?",
  ui_story_5029_50290008_98_dialog_content = "이건 백야성 기사단의 휘장이야!",
  ui_story_5029_50290008_99_dialog_content = "이게 왜 컵 안에 들어 있었던 거지? 설마 어제 여기 왔다는 그 공작이...?",
  ui_story_5029_50290008_100_dialog_content = "이따가 젠 씨한테 물어보자.",
  ui_story_5029_50290008_101_dialog_content = "그래! 그럼 조사를 계속하자.",
  ui_story_5029_50290008_102_option_content = "(의자)",
  ui_story_5029_50290008_103_dialog_content = "PlayerName, 그 의자 좀 꺼내줄래?",
  ui_story_5029_50290008_104_dialog_content = "알겠어. 혹시 피곤해?",
  ui_story_5029_50290008_105_dialog_content = "아니, 그 의자 위에 뭔가 있는 것 같거든.",
  ui_story_5029_50290008_106_dialog_content = "진짜네... 신문이잖아?",
  ui_story_5029_50290008_107_dialog_content = "「안데르센 가문은 니나 양의 대규모 상업 활동 전개를\n전적으로 지원하며...」",
  ui_story_5029_50290008_108_dialog_content = "「내막을 잘 알고 있는 관계자의 말에 따르면,\n니나 양은 한때 아이테르 때문에 가출한 적이 있다고 한다.」",
  ui_story_5029_50290008_109_dialog_content = "...이, 이렇게 쓰면 사람들이 오해하지 않겠어?",
  ui_story_5029_50290008_110_dialog_content = "근데 틀린 말은 아니잖아?",
  ui_story_5029_50290008_111_dialog_content = "크흠...",
  ui_story_5029_50290008_112_dialog_content = "그럼 조사를 계속하자.",
  ui_story_5029_50290008_113_option_content = "(벽)",
  ui_story_5029_50290008_114_dialog_content = "이 벽에 걸린 그림들은 모두 가치가 상당할 것 같네.",
  ui_story_5029_50290008_115_dialog_content = "그럼 범인은 왜 여기 그림들을 훔치지 않은 걸까?",
  ui_story_5029_50290008_116_dialog_content = "어쩌면 그리 대단한 작가의 작품이 아니라서 그럴지도 몰라.",
  ui_story_5029_50290008_117_dialog_content = "저기 구석에 뭔가 이상한 그림이 걸려있는 것 같은데...?",
  ui_story_5029_50290008_118_dialog_content = "이, 이건 네가 나한테 줬던 그림이잖아? 이게 왜 여기 있어?",
  ui_story_5029_50290008_119_dialog_content = "...그림 주변에 판매자 이름이 적혀 있지 않을까?",
  ui_story_5029_50290008_120_dialog_content = "호넷, 실버?!",
  ui_story_5029_50290008_121_dialog_content = "이 녀석들, 내 그림의 위작을 하버 시티에까지 팔아먹은 거야?",
  ui_story_5029_50290008_122_dialog_content = "어떤 의미로는 정말 대단하단 말이지...",
  ui_story_5029_50290008_123_dialog_content = "뭐, 일단 조사를 계속하자.",
  ui_story_5029_50290008_124_option_content = "이제 충분히 찾은 것 같아.",
  ui_story_5029_50290008_125_dialog_content = "다른 방을 살펴볼까?",
  ui_story_5029_50290008_126_dialog_content = "그래, 어디로 갈까?",
  ui_story_5029_50290008_127_option_content = "더 볼 필요는 없겠어.",
  ui_story_5029_50290008_128_dialog_content = "왠지 찾아볼 만한 곳은 전부 본 것 같아.",
  ui_story_5029_50290008_129_dialog_content = "난 지금 의심스러운 곳이 하나 있어...",
  ui_story_5029_50290008_130_dialog_content = "다시 한번 확인하고 올게!",
  ui_story_5029_50290008_131_dialog_content = "그럼 난 여기 소파에서 기다릴게.",
  ui_story_5029_50290009_1_dialog_content = "그럼 지금부터... 우린 뭘 해야 되는데?",
  ui_story_5029_50290009_2_dialog_content = "어디 보자...",
  ui_story_5029_50290009_3_option_content = "(서재)",
  ui_story_5029_50290009_4_dialog_content = "키아로, 대형을 갖추고 경계 태세를 유지해!",
  ui_story_5029_50290009_5_dialog_content = "루!",
  ui_story_5029_50290009_6_dialog_content = "대형도 있어?",
  ui_story_5029_50290009_7_dialog_content = "PlayerName 네가 선두, 키아로가 후미, 피아는 중앙!",
  ui_story_5029_50290009_7X1_dialog_content = "이게 바로 우리의 직선 대형이야!",
  ui_story_5029_50290009_8_dialog_content = "그래... 그나저나 이 방 진짜 넓네.",
  ui_story_5029_50290009_9_dialog_content = "어딜 조사할까?",
  ui_story_5029_50290009_10_option_content = "(첫 번째 책장)",
  ui_story_5029_50290009_11_dialog_content = "여기 공간을 엄청 차지하는 큰 책이 한 권 있어.",
  ui_story_5029_50290009_12_dialog_content = "뭐야? 이 엄청난 표지는...",
  ui_story_5029_50290009_13_dialog_content = "설마 전설의 환상동물 밀렵을 부추기는 책은 아니겠지?!",
  ui_story_5029_50290009_14_dialog_content = "어라, 이 책... 사부의 《신기한 작은 동물》이었잖아?",
  ui_story_5029_50290009_15_dialog_content = "그럼 영주님이 표지를 새로 만든 모양이네.",
  ui_story_5029_50290009_16_dialog_content = "영주 아저씨가 사부의 책도 읽었단 거야?",
  ui_story_5029_50290009_17_dialog_content = "그럼 분명히 피아의 책도 좋아하겠지?",
  ui_story_5029_50290009_18_dialog_content = "네 책도 벌써 출판했어?",
  ui_story_5029_50290009_19_dialog_content = "아직...",
  ui_story_5029_50290009_20_dialog_content = "그래도 앞으로 몇 년만 더 있으면 피아의 책이 사부 것보다\n더 인기가 많아질 거라구!",
  ui_story_5029_50290009_21_dialog_content = "그래그래. 그것보다 일단 조사를 계속하자.",
  ui_story_5029_50290009_22_option_content = "(벽)",
  ui_story_5029_50290009_23_dialog_content = "루...",
  ui_story_5029_50290009_24_dialog_content = "키아로, 무서워할 거 없어.",
  ui_story_5029_50290009_25_dialog_content = "그냥 사슴 머리일 뿐이야.",
  ui_story_5029_50290009_26_dialog_content = "루우...",
  ui_story_5029_50290009_27_dialog_content = "왠지 네가 설명해 주니까 더 무서워하는 것 같은데?",
  ui_story_5029_50290009_28_dialog_content = "키아로는 아마 또 사슴한테 받혀서 날아가 버렸을 때를 떠올렸을 거야.",
  ui_story_5029_50290009_29_dialog_content = "루우우!",
  ui_story_5029_50290009_30_dialog_content = "키아로, 멀리 가면 안 돼. 계속 조사해야 되니까!",
  ui_story_5029_50290009_31_option_content = "(수납장)",
  ui_story_5029_50290009_32_dialog_content = "영주님은 상자를 계속 이 수납장에 넣어 뒀었다고 했어.",
  ui_story_5029_50290009_33_dialog_content = "안은 이미 텅 비어 있어...",
  ui_story_5029_50290009_34_dialog_content = "이상하네. 이 수납장엔 자물쇠도 없단 말이야?",
  ui_story_5029_50290009_35_dialog_content = "아마 영주 아저씨는 방문을 잠글 수 있으니까,\n수납장엔 열쇠가 없어도 괜찮다고 생각한 거 아냐?",
  ui_story_5029_50290009_36_dialog_content = "근데 그 은 상자엔 자물쇠가 있었어.",
  ui_story_5029_50290009_37_dialog_content = "아~ 그럼 그 상자 안에 뭔가 더 귀중한 물건이 들어 있었겠네!",
  ui_story_5029_50290009_38_dialog_content = "너 꽤 영리하잖아?",
  ui_story_5029_50290009_39_dialog_content = "「환상동물 마스터 겸 영리한 명탐정」이라고 불러줘!",
  ui_story_5029_50290009_40_dialog_content = "알았어, 「환상동물 마스터 겸 영리한 명탐정」 씨,\n그럼 조사를 계속하자.",
  ui_story_5029_50290009_41_option_content = "이제 충분히 찾은 것 같아.",
  ui_story_5029_50290009_42_dialog_content = "그럼 이제 어떡하지...",
  ui_story_5029_50290009_43_dialog_content = "다른 방을 찾아보자!",
  ui_story_5029_50290009_44_dialog_content = "그럼 이제 어디로 갈 건데...?",
  ui_story_5029_50290009_45_option_content = "(홀)",
  ui_story_5029_50290009_46_dialog_content = "홀은 여러 방으로 통하니까, 확실하게 조사해 봐야지.",
  ui_story_5029_50290009_47_dialog_content = "그런 상식은 굳이 말하지 않아도 안다고.",
  ui_story_5029_50290009_48_dialog_content = "그럼 문제는...",
  ui_story_5029_50290009_49_dialog_content = "어딜 조사할까?",
  ui_story_5029_50290009_50_option_content = "(화분)",
  ui_story_5029_50290009_51_dialog_content = "화분 안에 뭔가 장치가 숨겨져 있진 않을까?",
  ui_story_5029_50290009_52_dialog_content = "잠깐만!",
  ui_story_5029_50290009_53_dialog_content = "왜, 왜 그래? 갑자기 소리를 지르고.",
  ui_story_5029_50290009_54_dialog_content = "이 꽃, 사부의 노트에서 본 적 있어! 왠지 맹독이 있다는 것 같아!",
  ui_story_5029_50290009_55_dialog_content = "말해줘서 고마워, 피아... 안 건드려서 다행이네!",
  ui_story_5029_50290009_56_dialog_content = "어? 키아로, 그 꽃 냄새 맡으면 안 돼!",
  ui_story_5029_50290009_57_dialog_content = "키아로, 얼른 돌아와. 계속 조사할 거야.",
  ui_story_5029_50290009_58_option_content = "(소파)",
  ui_story_5029_50290009_59_dialog_content = "왜 그래? 뭐 찾았어?",
  ui_story_5029_50290009_60_dialog_content = "보통 이야기 속에서는 소파 밑에 알려지지 않은 비밀이\n숨겨져 있기 마련이야.",
  ui_story_5029_50290009_61_dialog_content = "근데 그렇게 좁은 틈에는 키아로의 머리도 안 들어가겠는데?\n상자가 거기 있을 것 같진 않아.",
  ui_story_5029_50290009_62_dialog_content = "상자는 숨길 수 없어도, 뭔가 다른 게 있을지도 모른다구.",
  ui_story_5029_50290009_63_dialog_content = "예를 들면...",
  ui_story_5029_50290009_64_dialog_content = "어라? 소파 밑에 진짜로 뭐가 있었어?",
  ui_story_5029_50290009_65_dialog_content = "근데 난 이게 뭔지 모르겠는데?",
  ui_story_5029_50290009_66_dialog_content = "뭔가가 깨진 조각 같아.",
  ui_story_5029_50290009_67_dialog_content = "앗! 그럼 이건 중요한 단서 아냐?",
  ui_story_5029_50290009_68_dialog_content = "영주 아저씨가 말했잖아. 낮에 메이드가 청소를 했다고.",
  ui_story_5029_50290009_69_dialog_content = "그냥 청소를 제대로 못 한 건지도 모르잖아.",
  ui_story_5029_50290009_70_dialog_content = "아냐! 「환상동물 마스터 겸 영리한 명탐정」의 직감이 말해주고 있어.\n이건 그렇게 단순한 문제가 아냐!",
  ui_story_5029_50290009_71_dialog_content = "이따가 젠 씨한테 그 메이드에 대해 물어봐야겠어.",
  ui_story_5029_50290009_72_dialog_content = "그래, 그럼 조사를 계속하자.",
  ui_story_5029_50290009_73_option_content = "(장식품)",
  ui_story_5029_50290009_74_dialog_content = "우와! 여기 환상동물이 있어! PlayerName, 빨리 와 봐!",
  ui_story_5029_50290009_75_dialog_content = "어? 너 소라고둥 처음 봐?",
  ui_story_5029_50290009_76_dialog_content = "난 환상동물 마스터야! 처음 보는 동물 같은 건 없어!",
  ui_story_5029_50290009_77_dialog_content = "그, 그냥 이런 색의 소라고둥을 실제로 보는 건 처음이었을 뿐이라구...",
  ui_story_5029_50290009_78_dialog_content = "그거 알아? 소라고둥한테 소원을 빌면 소원이 이루어진대.",
  ui_story_5029_50290009_79_dialog_content = "야, 그런 건 어린애들 속일 때나 하는 말 아냐?",
  ui_story_5029_50290009_80_dialog_content = "난 이제 어린애가 아냐! 그런 수작엔 안 넘어간다구.",
  ui_story_5029_50290009_81_dialog_content = "소라고둥 씨, 소라고둥 씨,\n제가 영주님의 잃어버린 물건을 찾을 수 있게 해 주세요.",
  ui_story_5029_50290009_82_dialog_content = "왜 너 혼자만 자기만 소원 비는 거야? 그럼...",
  ui_story_5029_50290009_83_dialog_content = "소라고둥 씨, 소라고둥 씨,\n피아야말로 영주 아저씨의 잃어버린 물건을 찾을 수 있는 사람이에요.",
  ui_story_5029_50290009_84_dialog_content = "크흠, 그럼 조사를 계속하자.",
  ui_story_5029_50290009_85_option_content = "이제 충분히 찾은 것 같아.",
  ui_story_5029_50290009_86_dialog_content = "그럼 이제 어떡하지...",
  ui_story_5029_50290009_87_dialog_content = "다른 방을 찾아보자!",
  ui_story_5029_50290009_88_dialog_content = "그럼 이제 어디로 갈 건데...?",
  ui_story_5029_50290009_89_option_content = "(카페)",
  ui_story_5029_50290009_90_dialog_content = "카페에 가실 겁니까? 이쪽으로 가시죠.",
  ui_story_5029_50290009_91_dialog_content = "영주님께서는 일하실 때 방해를 받는 것을 싫어하십니다.\n그래서 이쪽에 카페가 생긴 겁니다.",
  ui_story_5029_50290009_92_dialog_content = "때로는 영주님께서 직접 손님들에게 커피를 만들어 주실 때도 있습니다.",
  ui_story_5029_50290009_93_dialog_content = "우와, 왠지 좋은 냄새가 나는 것 같아!",
  ui_story_5029_50290009_94_dialog_content = "루!",
  ui_story_5029_50290009_95_dialog_content = "또 어딜 조사할까?",
  ui_story_5029_50290009_96_option_content = "(조리실)",
  ui_story_5029_50290009_97_dialog_content = "어떻게 여기에...",
  ui_story_5029_50290009_98_dialog_content = "꿀케이크가 있지?",
  ui_story_5029_50290009_99_dialog_content = "하버 시티에서도 북방의 명물을 먹을 수 있을 줄은 몰랐네.",
  ui_story_5029_50290009_100_dialog_content = "움브라톤에서도 이런 건 못 먹어 봤다구.",
  ui_story_5029_50290009_101_dialog_content = "맛있는 거야?",
  ui_story_5029_50290009_102_dialog_content = "맛있긴 하지. 그래도 여기 있는 물건은 안 건드리는 게 좋아.",
  ui_story_5029_50290009_103_dialog_content = "흥, 피아도 당연히 알거든.",
  ui_story_5029_50290009_104_dialog_content = "하버 시티엔 맛있는 게 많다고 들었어.",
  ui_story_5029_50290009_105_dialog_content = "상자를 찾아서 현상금을 받으면... 얼마든지 먹을 수 있다구!",
  ui_story_5029_50290009_106_dialog_content = "루!",
  ui_story_5029_50290009_107_dialog_content = "크흠, 그럼 조사를 계속하자.",
  ui_story_5029_50290009_108_option_content = "(바닥)",
  ui_story_5029_50290009_109_dialog_content = "키아로, 왜 내 등 뒤에 숨어서 떨고 있는 거야?",
  ui_story_5029_50290009_110_dialog_content = "그쪽에 뭐 있어?",
  ui_story_5029_50290009_111_dialog_content = "앗! PlayerName! 여기 피 묻은 과도가 있어!",
  ui_story_5029_50290009_112_dialog_content = "설마 절도 사건이 살인 사건으로 변한 건 아니겠지?",
  ui_story_5029_50290009_113_dialog_content = "음...",
  ui_story_5029_50290009_114_dialog_content = "크흠, 내가 좀 볼게.",
  ui_story_5029_50290009_115_dialog_content = "하하, 괜찮아. 그냥 딸기잼이야.",
  ui_story_5029_50290009_116_dialog_content = "무, 무서워한 적 없거든!",
  ui_story_5029_50290009_117_dialog_content = "으앗!",
  ui_story_5029_50290009_118_dialog_content = "PlayerName 너 손에 딸기잼이 잔뜩 묻었네.",
  ui_story_5029_50290009_119_dialog_content = "딸기잼이 아냐. 실수로 손가락을 베였어. 이번엔 진짜 피야...",
  ui_story_5029_50290009_120_dialog_content = "으아아앗?! 어떡해?",
  ui_story_5029_50290009_121_dialog_content = "아! 키아로의 침엔 소독 살균 효과가 있어!\n키아로, 얼른 PlayerName 좀 도와줘.",
  ui_story_5029_50290009_122_dialog_content = "루!",
  ui_story_5029_50290009_123_dialog_content = "괘, 괜찮아, 크게 다친 건 아니니까... 그것보다 일단 조사를 계속하자.",
  ui_story_5029_50290009_124_option_content = "(카운터)",
  ui_story_5029_50290009_125_dialog_content = "카운터 위에 놓인 책은 조사했어?",
  ui_story_5029_50290009_126_dialog_content = "어디 보자... 《아카나미 사메노스케 전기 제1권》?",
  ui_story_5029_50290009_127_dialog_content = "흥, 이런 건 그냥 지어낸 이야기잖아.",
  ui_story_5029_50290009_128_dialog_content = "이런 것보단 사부가 쓴 《신기한 작은 동물》이 더 좋아!",
  ui_story_5029_50290009_129_dialog_content = "그래?",
  ui_story_5029_50290009_130_dialog_content = "뭐, 뭔데?",
  ui_story_5029_50290009_131_dialog_content = "말로는 사부가 싫다고 하면서 사실은 역시 존경하고 있었구나!",
  ui_story_5029_50290009_132_dialog_content = "안 그러면 매번 「사부」 얘기를 꺼낼 리가 없잖아.",
  ui_story_5029_50290009_133_dialog_content = "그, 그냥 우연이야!",
  ui_story_5029_50290009_134_dialog_content = "알았어. 그럼 조사를 계속하자.",
  ui_story_5029_50290009_135_option_content = "이제 다 찾은 것 같아.",
  ui_story_5029_50290009_136_dialog_content = "그럼 이제 어떡하지...",
  ui_story_5029_50290009_137_dialog_content = "다른 방을 찾아보자!",
  ui_story_5029_50290009_138_dialog_content = "그럼 이제 어디로 갈 건데...?",
  ui_story_5029_50290009_139_option_content = "더 볼 필요는 없겠어.",
  ui_story_5029_50290009_140_dialog_content = "왠지 찾아볼 만한 곳은 전부 본 것 같아.",
  ui_story_5029_50290009_141_dialog_content = "와~ 그럼 드디어 쉴 수 있겠네...",
  ui_story_5029_50290009_142_dialog_content = "어라, 잠깐만, 키아로가 또 어디 갔지?",
  ui_story_5029_50290009_143_dialog_content = "PlayerName, 나 키아로 좀 찾으러 갈게!",
  ui_story_5029_50290009_144_dialog_content = "그래, 조심해.",
  ui_story_5029_50290010_1_dialog_content = "(이 집은 정말 크네...)",
  ui_story_5029_50290010_2_dialog_content = "(어느 방을 조사해 볼까?)",
  ui_story_5029_50290010_3_option_content = "(서재)",
  ui_story_5029_50290010_4_dialog_content = "적당히 둘러보자...",
  ui_story_5029_50290010_5_option_content = "(첫 번째 책장)",
  ui_story_5029_50290010_6_dialog_content = "이 책 왠지 어디서 본 것 같은데?",
  ui_story_5029_50290010_7_dialog_content = "《아카나미 사메노스케 전기 제1권》?",
  ui_story_5029_50290010_8_dialog_content = "왜 1권밖에 없지?",
  ui_story_5029_50290010_9_option_content = "(책상)",
  ui_story_5029_50290010_10_dialog_content = "책상 위에도 책이 있는데... 뭔가 너덜너덜하네.",
  ui_story_5029_50290010_11_dialog_content = "<color=#828282>툭!</color>",
  ui_story_5029_50290010_12_dialog_content = "으앗, 망가졌잖아?",
  ui_story_5029_50290010_13_dialog_content = "이거 큰일이네... 나중에 영주님한테 사과해야겠어.",
  ui_story_5029_50290010_14_dialog_content = "왜 오늘은 하는 일마다 잘 안 풀리는 것 같지?",
  ui_story_5029_50290010_15_option_content = "(수납장)",
  ui_story_5029_50290010_16_dialog_content = "영주님은 상자를 계속 이 수납장에 넣어 뒀었다고 했어.",
  ui_story_5029_50290010_17_dialog_content = "예쁜 수납장이네. 아쉽게도 안의 내용물은 사라졌지만 말이야.",
  ui_story_5029_50290010_18_option_content = "이제 다 둘러본 것 같아.",
  ui_story_5029_50290010_19_dialog_content = "다른 방을 둘러보자.",
  ui_story_5029_50290010_20_option_content = "(홀)",
  ui_story_5029_50290010_21_dialog_content = "홀은 텅 비어 있어.",
  ui_story_5029_50290010_22_dialog_content = "적당히 둘러보자...",
  ui_story_5029_50290010_23_option_content = "(화분)",
  ui_story_5029_50290010_24_dialog_content = "화분 안에 뭔가 장치가 숨겨져 있진 않을까?",
  ui_story_5029_50290010_25_dialog_content = "킁킁...",
  ui_story_5029_50290010_26_dialog_content = "조심하세요! 그 꽃엔 독이 있어서 접촉하면 안 됩니다!",
  ui_story_5029_50290010_27_dialog_content = "어떡하죠... 왠지 벌써 머리가 어지러운 것 같은데요...",
  ui_story_5029_50290010_28_dialog_content = "다행히 중독된 것 같진 않군요. 잠깐 쉬고 나면 괜찮아질 겁니다.",
  ui_story_5029_50290010_29_dialog_content = "고마워요. 그래도 계속할 수 있을 것 같네요...",
  ui_story_5029_50290010_30_option_content = "(소파)",
  ui_story_5029_50290010_31_dialog_content = "소파에 앉아서 다들 바쁘게 움직이는 걸 보고 있으니까 뭔가 불편하네...",
  ui_story_5029_50290010_32_dialog_content = "어라? 발에 뭐가 밟힌 느낌인데?",
  ui_story_5029_50290010_33_dialog_content = "뭔가 깨진 조각인가...?",
  ui_story_5029_50290010_34_dialog_content = "메이드가 청소한 방은 전부 깨끗할 줄 알았는데.",
  ui_story_5029_50290010_35_option_content = "(장식품)",
  ui_story_5029_50290010_36_dialog_content = "이 소라고둥 진짜 예쁘네.",
  ui_story_5029_50290010_37_dialog_content = "뭐, 사건이랑은 별 상관없겠지.",
  ui_story_5029_50290010_38_option_content = "이제 다 둘러본 것 같아.",
  ui_story_5029_50290010_39_dialog_content = "다른 방을 둘러보자.",
  ui_story_5029_50290010_40_option_content = "(카페)",
  ui_story_5029_50290010_41_dialog_content = "카페에 가실 겁니까? 이쪽으로 가시죠.",
  ui_story_5029_50290010_42_dialog_content = "영주님께서는 일하실 때 방해를 받는 것을 싫어하십니다.\n그래서 이쪽에 카페가 생긴 겁니다.",
  ui_story_5029_50290010_43_dialog_content = "때로는 영주님께서 직접 손님들에게 커피를 만들어 주실 때도 있습니다.",
  ui_story_5029_50290010_44_dialog_content = "적당히 둘러보자...",
  ui_story_5029_50290010_45_option_content = "(커피잔)",
  ui_story_5029_50290010_46_dialog_content = "영주님은 미적 감각도 좋구나. 커피잔도 전부 예쁜 것들이네.",
  ui_story_5029_50290010_47_dialog_content = "이 컵... 안에 커피가 남아 있잖아?",
  ui_story_5029_50290010_48_dialog_content = "<color=#828282>딸랑!</color>",
  ui_story_5029_50290010_49_dialog_content = "어라, 커피 안에 뭔가 있는데?",
  ui_story_5029_50290010_50_dialog_content = "...휘장?",
  ui_story_5029_50290010_51_dialog_content = "안 마시길 잘했네... 안 그랬으면 목이 막혀서 죽을 뻔했잖아...",
  ui_story_5029_50290010_52_option_content = "(바닥)",
  ui_story_5029_50290010_53_dialog_content = "저기 뭔가 있는데 잘 안 보이네...",
  ui_story_5029_50290010_54_dialog_content = "이건... 피 묻은 과도?",
  ui_story_5029_50290010_55_dialog_content = "여, 여기 좀 도와주세요!",
  ui_story_5029_50290010_56_dialog_content = "죄송합니다. 말씀드리는 걸 깜빡 잊었군요...",
  ui_story_5029_50290010_57_dialog_content = "그 과도에 묻은 건 그냥 잼입니다.",
  ui_story_5029_50290010_58_dialog_content = "괜찮으십니까? 잠시 쉬시겠습니까?",
  ui_story_5029_50290010_59_dialog_content = "괘, 괜찮아요... 혼자 좀 진정하면 될 거예요.",
  ui_story_5029_50290010_60_option_content = "(벽)",
  ui_story_5029_50290010_61_dialog_content = "벽에 예쁜 유화가 잔뜩 걸려있네.",
  ui_story_5029_50290010_62_dialog_content = "뭐, 지금은 그림 감상할 기분은 아니야.",
  ui_story_5029_50290010_63_option_content = "이제 다 둘러본 것 같아.",
  ui_story_5029_50290010_64_dialog_content = "다른 방을 둘러보자.",
  ui_story_5029_50290010_65_option_content = "그만 봐야겠어.",
  ui_story_5029_50290010_66_dialog_content = "한참을 둘러봤는데, 아무 수확도 없었어...",
  ui_story_5029_50290010_67_dialog_content = "휴, 다들 아직도 조사하고 있는 것 같네.",
  ui_story_5029_50290010_68_dialog_content = "난 일단 좀 쉬어야겠어.",
  ui_story_5029_50290011_1_dialog_content = "이 소파, 되게 편하네.",
  ui_story_5029_50290011_2_dialog_content = "나도 모르게 잠들었잖아. 너무 오래 잔 건 아니겠지?",
  ui_story_5029_50290011_3_dialog_content = "그럼 이제 어떡하지...",
  ui_story_5029_50290011_4_dialog_content = "다른 탐정분들은 용의자를 찾으러 나가신 것 같습니다.\n당신도 함께 가실 겁니까?",
  ui_story_5029_50290011_5_dialog_content = "네? 진짜요?",
  ui_story_5029_50290011_6_dialog_content = "앗, 다들 기다려! 나도 같이 가!",
  ui_story_5029_50290011_7_option_content = "(카렌에게 묻는다)",
  ui_story_5029_50290011_8_dialog_content = "카렌, 어디로 갈 거야?",
  ui_story_5029_50290011_9_dialog_content = "이 저택에 이상한 책이 한 권 있던 거 봤어?",
  ui_story_5029_50290011_10_dialog_content = "이상한 책이라... 저택에 있는 책들은 거의 다 모르는 책들이었거든.",
  ui_story_5029_50290011_11_dialog_content = "읽은 적 있는 건 <color=#793f76>《아카나미 사메노스케 전기》</color>뿐이야.",
  ui_story_5029_50290011_12_dialog_content = "그래, 바로 그 책 말이야.",
  ui_story_5029_50290011_13_dialog_content = "처음엔 통속소설을 읽다니 엘비스답지 않다고\n이상하게 생각만 하고 넘어갔어.",
  ui_story_5029_50290011_14_dialog_content = "그런데 여기저기 수색하다 보니까 저택 곳곳에\n그 소설이 있는 걸 발견했어.",
  ui_story_5029_50290011_15_dialog_content = "설마 영주님도 나처럼 《아카나미 사메노스케 전기》를 좋아한 건가?!",
  ui_story_5029_50290011_16_dialog_content = "잠깐만... 뭔가 이상해. 만약 마음에 들었다면 전권을 샀어야 맞잖아.",
  ui_story_5029_50290011_17_dialog_content = "근데 나도 아까 한참 찾아봤지만 《아카나미 사메노스케 전기》는\n1권밖에 없었어.",
  ui_story_5029_50290011_18_dialog_content = "아까 젠에게 물어봤는데, 영주는 그런 통속소설을 산 적은 없다고 했어.",
  ui_story_5029_50290011_19_dialog_content = "공교로운 건 바로 어제 저택을 찾아왔던 그 상인이\n통속소설의 출판사업 이야기를 영주에게 꺼냈다고 해.",
  ui_story_5029_50290011_20_dialog_content = "그거랑 절도 사건이 무슨 상관인데?",
  ui_story_5029_50290011_21_dialog_content = "그 상인의 이름을 들으면 너도 납득할 거야.",
  ui_story_5029_50290011_22_dialog_content = "내, 내가 아는 사람이야?",
  ui_story_5029_50290011_23_dialog_content = "젠이 말해준 그 상인의 이름은 <color=#793f76>조무이치로</color>였어.",
  ui_story_5029_50290011_24_dialog_content = "처음 듣는데? 왠지 운도 사람 같은 이름이긴 하네...",
  ui_story_5029_50290011_25_dialog_content = "앗, 잠깐만! 조무...이치로... 설마 조무?!",
  ui_story_5029_50290011_26_dialog_content = "대담한 녀석이네.\n그런 허술한 가명으로 정체를 들키지 않을 줄 알았던 건가?",
  ui_story_5029_50290011_27_dialog_content = "하지만 그 상인이 정말 조무라고 해도,\n상자를 훔친 게 조무라고 단정할 순 없잖아?",
  ui_story_5029_50290011_28_dialog_content = "애초에 레디젤 렌치는 악행을 일삼는 강도 집단이야.",
  ui_story_5029_50290011_28X1_dialog_content = "이런 절도 같은 일 정도는 그들에게 일상 같은 것이겠지.",
  ui_story_5029_50290011_29_dialog_content = "레디젤 렌치 놈들, 감히 백야성의 영지에까지 더러운 손을 뻗다니.",
  ui_story_5029_50290011_30_dialog_content = "내가 놈들을 이 창으로 친히 몰아내겠어!",
  ui_story_5029_50290011_31_dialog_content = "아니면... 차라리 조무한테 직접 물어보는 건 어떨까?",
  ui_story_5029_50290011_32_dialog_content = "나도 그럴 생각이었어.",
  ui_story_5029_50290011_33_dialog_content = "지금 조무가 머무르는 곳에 가서 탐문할 준비를 하던 중이었거든.",
  ui_story_5029_50290011_34_option_content = "나도 같이 갈게.",
  ui_story_5029_50290011_35_dialog_content = "좋아, 그럼 가자.",
  ui_story_5029_50290011_36_option_content = "행운을 빌게.",
  ui_story_5029_50290011_37_dialog_content = "고마워.",
  ui_story_5029_50290011_38_option_content = "(바이스에게 묻는다)",
  ui_story_5029_50290011_39_dialog_content = "바이스, 어디로 갈 거야?",
  ui_story_5029_50290011_40_dialog_content = "그거 알아? 원래라면 여기 있을 리가 없는 물건이 카페에 있었다는 거.",
  ui_story_5029_50290011_41_dialog_content = "여기 있을 리가 없는 물건?",
  ui_story_5029_50290011_42_dialog_content = "커피잔 안에 들어 있던 <color=#793f76>백야성 기사 휘장</color> 말이지?",
  ui_story_5029_50290011_43_dialog_content = "맞아, 그 휘장.",
  ui_story_5029_50290011_44_dialog_content = "처음엔 영주님이 수집하는 물건인 줄 알았어.",
  ui_story_5029_50290011_45_dialog_content = "응, 그럴 가능성도 있겠지. 하버 시티도 백야성 영토의 일부니까,\n영주님이 기사 휘장을 가지고 있어도 이상할 건 없어.",
  ui_story_5029_50290011_46_dialog_content = "근데 수집품이라면 잘 간직하고 있어야 맞는 거잖아.",
  ui_story_5029_50290011_47_dialog_content = "손님한테 주는 커피 안에 그런 게 들어 있는 건 아무리 봐도 말이 안 돼...",
  ui_story_5029_50290011_48_dialog_content = "그렇다면 가능성은 하나뿐이야.",
  ui_story_5029_50290011_49_dialog_content = "그 휘장은 손님 중 누군가의 것이겠지.",
  ui_story_5029_50290011_50_dialog_content = "그리고 어제 방문한 손님 중에는 마침 백야성 사람이 있었어.",
  ui_story_5029_50290011_51_dialog_content = "백야성에서 왔다는 공작 말이야?",
  ui_story_5029_50290011_52_dialog_content = "아까 영주님은 그 공작을 뭐라고 불렀더라...\n「이스크 공작」이라고 했었나?",
  ui_story_5029_50290011_53_dialog_content = "그럼 그 이스크 공작의 풀네임이 뭔지 알아?",
  ui_story_5029_50290011_54_dialog_content = "<color=#793f76>베벌리 이스크</color>야!",
  ui_story_5029_50290011_55_dialog_content = "어라... 그 베벌리?",
  ui_story_5029_50290011_56_dialog_content = "근데 만약 그게 정말 베벌리의 휘장이라고 해도,\n베벌리가 절도 사건과 관계가 있다는 증거가 되는 건 아니잖아.",
  ui_story_5029_50290011_57_dialog_content = "아까 젠 씨한테 들었어.\n베벌리 씨는 어제 영주님이랑 조금 트러블이 있었다던 것 같아.",
  ui_story_5029_50290011_58_dialog_content = "네 말은 그럼 베벌리가 화가 나서 일부러 영주님의 상자를 훔쳤다는 거야?",
  ui_story_5029_50290011_59_dialog_content = "난 베벌리가 그런 짓까지 할 사람은 아니라고 생각해.",
  ui_story_5029_50290011_60_dialog_content = "난 백야성에 유학을 갔을 때 깨달은 점이 있어.",
  ui_story_5029_50290011_61_dialog_content = "자신이 고귀한 신분이라고 자부하는 귀족일수록,\n뒤에서는 상상도 할 수 없는 일을 벌이곤 했어.",
  ui_story_5029_50290011_62_dialog_content = "그리고 그 베벌리 씨는 항상 「귀족」이라는 말을 입에 달고 살아...",
  ui_story_5029_50290011_63_dialog_content = "휴, 나도 베벌리 씨를 의심하는 게 마음이 편하진 않아.\n그래서 가서 제대로 해명을 듣고 싶은 거야.",
  ui_story_5029_50290011_64_option_content = "나도 같이 갈게.",
  ui_story_5029_50290011_65_dialog_content = "그렇게 말할 줄 알았어! 그럼 가자!",
  ui_story_5029_50290011_66_option_content = "행운을 빌게.",
  ui_story_5029_50290011_67_dialog_content = "그 말은 다른 사람한테 해주는 게 좋을걸.",
  ui_story_5029_50290011_68_option_content = "(피아에게 묻는다)",
  ui_story_5029_50290011_69_dialog_content = "피아, 뭐 하러 가는 거야?",
  ui_story_5029_50290011_70_dialog_content = "PlayerName, 쉿... 조용히 해.",
  ui_story_5029_50290011_71_dialog_content = "나 지금 중요한 단서를 발견했어. 다른 사람이 알게 하면 안 돼!",
  ui_story_5029_50290011_72_dialog_content = "중요한 단서? 소파 밑에 있던 <color=#793f76>조각</color> 말하는 거야?",
  ui_story_5029_50290011_73_dialog_content = "조각이라고 무시하면 안 돼! 내가 저 젠이라는 아저씨한테 물어봤다구.",
  ui_story_5029_50290011_74_dialog_content = "원래대로라면 소파 아래도 메이드가 청소해야 할 장소 중 하나래.",
  ui_story_5029_50290011_75_dialog_content = "그냥 그 메이드의 일 처리가 깔끔하지 않았을 뿐일지도 모르잖아?",
  ui_story_5029_50290011_76_dialog_content = "흥, 그게 다라면 피아도 의심하거나 하지 않았어.",
  ui_story_5029_50290011_77_dialog_content = "중요한 건... 그 메이드의 경력이 수상하다는 거야!",
  ui_story_5029_50290011_78_dialog_content = "경력이 수상해?\n영주님 말로는 움브라톤 상회한테 소개받은 거라고 하지 않았어?",
  ui_story_5029_50290011_79_dialog_content = "내가 아는 움브라톤 상회라면 나름대로 믿을 만한 곳인데 말이야.",
  ui_story_5029_50290011_80_dialog_content = "하아, PlayerName 넌 이제 어린애가 아냐! 왜 아직도 그렇게 순진해?",
  ui_story_5029_50290011_81_dialog_content = "환상동물 마스터, 움브라톤 주민, 아이테르의 주인이자 신인 탐정인\n이 피아가 가르쳐 줄게.",
  ui_story_5029_50290011_82_dialog_content = "움브라톤이나 하버 시티나 모두 무역을 통해서 발전한 도시야.",
  ui_story_5029_50290011_83_dialog_content = "원래는 움브라톤이 가장 크고 번영한 자유 무역의 중심지였어.",
  ui_story_5029_50290011_84_dialog_content = "근데 내가 보기엔 하버 시티의 최근 성장세라면\n금방 움브라톤을 추월할 거야!",
  ui_story_5029_50290011_85_dialog_content = "그럴 때 움브라톤의 상회가 왜 메이드를 추천해 줬겠어?",
  ui_story_5029_50290011_86_dialog_content = "왜?",
  ui_story_5029_50290011_87_dialog_content = "답은 하나야. 메이드를 가지고 비즈니스 기밀을 훔치기 위해서지.",
  ui_story_5029_50290011_88_dialog_content = "그리고 그 기밀은 분명히 은 상자 속에 숨겨져 있었을 거야!",
  ui_story_5029_50290011_89_dialog_content = "왠지 믿기는 어렵지만, 그렇다고 반박할 근거도 딱히 없을 것 같네...",
  ui_story_5029_50290011_90_dialog_content = "그 마나에라는 메이드는 지금 다른 저택에서 일하고 있다고 해.\n난 지금 바로 그 녀석을 잡으러 갈 거야!",
  ui_story_5029_50290011_91_dialog_content = "잠깐만... 지금 그 메이드 이름이 뭐라고?",
  ui_story_5029_50290011_92_dialog_content = "<color=#793f76>마나에</color>, 왜 그래?",
  ui_story_5029_50290011_93_dialog_content = "음... 어째 어디서 많이 들은 이름인데...",
  ui_story_5029_50290011_94_option_content = "나도 같이 갈게.",
  ui_story_5029_50290011_95_dialog_content = "쉿, 몰래 나가자. 다른 두 사람한테 들키면 안 돼!",
  ui_story_5029_50290011_96_option_content = "아무튼 행운을 빌게.",
  ui_story_5029_50290011_97_dialog_content = "내가 찾은 단서는 절대 다른 사람들한테 말하지 마.",
  ui_story_5029_50290011_98_dialog_content = "안 그러면 키아로를 풀어서 널 찾을 테니까!",
  ui_story_5029_50290011_99_dialog_content = "루!",
  ui_story_5029_50290011_100_option_content = "(혼자 남는다)",
  ui_story_5029_50290011_101_dialog_content = "어떻게 된 거지?",
  ui_story_5029_50290011_102_dialog_content = "왜 나 혼자만 남은 건데...",
  ui_story_5029_50290012_1_dialog_content = "조무 녀석, 이런 고급 호텔에 묵을 돈이 있단 말이야?",
  ui_story_5029_50290012_2_dialog_content = "이제 나도 조무가 의심스러워지기 시작했어...\n역시 확실하게 해명을 들어야겠어!",
  ui_story_5029_50290012_3_dialog_content = "근데 지금 우린 문제가 하나 있어.",
  ui_story_5029_50290012_4_dialog_content = "엘비스는 비밀리에 조사해 달라고 했어.\n그러니까 우린 조무의 방을 직접 물어볼 순 없어.",
  ui_story_5029_50290012_5_dialog_content = "그럼 우리도... 투숙객인 척하면 되지.",
  ui_story_5029_50290012_6_dialog_content = "그리고 떳떳하게 들어가서, 룸 컨디션을 보고 싶다고 하자.",
  ui_story_5029_50290012_7_dialog_content = "들어간 뒤에는 천천히 조무를 찾으면 돼.",
  ui_story_5029_50290012_8_dialog_content = "좋은 방법이긴 하지만... 무관한 사람들을 속이는 건 내키지 않아.",
  ui_story_5029_50290012_9_dialog_content = "우린 그냥 사건 조사만 하는 거잖아.\n누구한테도 해를 끼치거나 하진 않을 거야.",
  ui_story_5029_50290012_10_dialog_content = "이런 건 선의의 거짓말이라고 할 수 있지 않을까?",
  ui_story_5029_50290012_11_dialog_content = "직원한테는 내가 말할게. 카렌 넌 옆에 서 있기만 하면 돼.",
  ui_story_5029_50290012_12_dialog_content = "그럴 순 없어. 책임을 전부 동료에게 떠넘기는 사람이 되고 싶진 않아.\n나도 최선을 다할게.",
  ui_story_5029_50290012_13_dialog_content = "환영합니다, 고객님. 예약하셨습니까?",
  ui_story_5029_50290012_14_dialog_content = "크흠... 예, 예약은 안 했어요.",
  ui_story_5029_50290012_15_dialog_content = "(카렌은 정말로 거짓말을 잘 못하는구나...)",
  ui_story_5029_50290012_16_dialog_content = "맞아요, 사실...",
  ui_story_5029_50290012_17_option_content = "제가 좀 까다로운 편이거든요.",
  ui_story_5029_50290012_18_dialog_content = "음?",
  ui_story_5029_50290012_19_option_content = "여기 좀 까다로운 사람이 있어서요.",
  ui_story_5029_50290012_20_dialog_content = "음?",
  ui_story_5029_50290012_21_dialog_content = "그래서 일단 좀 살펴보고 결정하고 싶네요.",
  ui_story_5029_50290012_22_dialog_content = "네, 알겠습니다. 실례지만 성함이 어떻게 되시죠?",
  ui_story_5029_50290012_23_dialog_content = "PlayerName입니다.",
  ui_story_5029_50290012_24_dialog_content = "PlayerName 님, 그리고 신부님, 이쪽으로 모시겠습니다.",
  ui_story_5029_50290012_25_dialog_content = "저희 호텔 최고의 프리미어 스위트룸으로 안내해 드리겠습니다.\n두 분께 가장 낭만적인 허니문을 만들어 드릴 것을 약속드립니다.",
  ui_story_5029_50290012_26_dialog_content = "...?!",
  ui_story_5029_50290012_27_dialog_content = "저기, 우린...",
  ui_story_5029_50290012_28_dialog_content = "아, 두 분 신혼부부 아니신가요?",
  ui_story_5029_50290012_29_dialog_content = "맞아요!",
  ui_story_5029_50290012_30_dialog_content = "아니에요!",
  ui_story_5029_50290012_31_dialog_content = "어머? 왜 두 분 말씀이 다를까요?",
  ui_story_5029_50290012_32_dialog_content = "(이런, 우릴 의심하기 시작했어! 어떡하지?)",
  ui_story_5029_50290012_33_dialog_content = "(근데 방금 카렌은 분명히 과감하게 인정했어...)",
  ui_story_5029_50290012_34_dialog_content = "(으아아... 지금은 이상한 생각이나 할 때가 아냐. 얼른 방법을 떠올려...)",
  ui_story_5029_50290012_35_dialog_content = "손님, 저희 호텔에 숙박하러 오신 게 맞으신가요?",
  ui_story_5029_50290012_36_dialog_content = "당연하죠...",
  ui_story_5029_50290012_37_dialog_content = "미안해요. 우, 우린 이제 막 약혼했거든요.",
  ui_story_5029_50290012_38_dialog_content = "저한테는 약혼도 신혼이나 다름없지만...",
  ui_story_5029_50290012_39_dialog_content = "이이는 성대한 결혼식을 올리기 전까진 아직 신혼이 아니라고\n생각했던 모양이에요.",
  ui_story_5029_50290012_40_dialog_content = "아, 물론 이해할 수 있죠!\n누구나 세상 단 하나뿐인 결혼식을 올리고 싶어 하는 법이니까요~",
  ui_story_5029_50290012_41_dialog_content = "지금 제가 잘못 본 거 아니겠죠?",
  ui_story_5029_50290012_42_dialog_content = "조무... 하하하... 이, 이것 참 신기하네.",
  ui_story_5029_50290012_43_dialog_content = "보스, 정말 보스인가요?!\n근데 왜 백야성의... 우우웁, 왜 제 입을... 우웁!",
  ui_story_5029_50290012_44_dialog_content = "아, 여기서 친구를 만날 줄은 몰랐네요. 저흰 나중에 다시 올게요.",
  ui_story_5029_50290012_45_dialog_content = "네, 언제든지 편하게 방문해 주세요!",
  ui_story_5029_50290012_46_dialog_content = "비밀 조사를 하고 있다고요?\n그랬군요. 그래서 아까는 신분을 숨겼던 거군요.",
  ui_story_5029_50290012_47_dialog_content = "하하, 만약 정말 아이테르와 백야성이 혼인 관계를 맺는다면,\n우리 대장이 무슨 일을 저지를지 모른다고요.",
  ui_story_5029_50290012_48_dialog_content = "우리 대장은 매일같이 PlayerName 님이 레디젤 렌치에\n가입하는 날만 기다리고 있으니까요.",
  ui_story_5029_50290012_49_dialog_content = "호오? 그래서 그자가 뭘 할 수 있지?",
  ui_story_5029_50290012_50_dialog_content = "크흠, 그 얘기는 일단 됐어. 조무, 넌 왜 하버 시티에 있는 거야?",
  ui_story_5029_50290012_51_dialog_content = "물론 비즈니스 때문이죠.",
  ui_story_5029_50290012_52_dialog_content = "또 남을 속이는 수작 같은 걸 꾸미고 있나?",
  ui_story_5029_50290012_53_dialog_content = "아이고, 억울합니다요!",
  ui_story_5029_50290012_54_dialog_content = "아무리 백야성의 공주님이라 해도 남을 함부로 모함하면 안 되죠.",
  ui_story_5029_50290012_55_dialog_content = "전 제대로 된 사업을 하러 온 거란 말입니다.\n어젠 하버 시티의 영주와 사업 협의까지 했다니까요.",
  ui_story_5029_50290012_56_dialog_content = "그래? 그럼 왜 내가 듣기론 어제 영주를 만난 상인이\n운도에서 왔다고 했을까?",
  ui_story_5029_50290012_57_dialog_content = "조무이치로는 대대로 운도에서 출판업에 종사하는 가문으로,\n사업 파트너를 찾기 위해 아스트라 대륙에 왔습니다.",
  ui_story_5029_50290012_58_dialog_content = "최근에는 극동 스타일 전기소설의 유행을 위해 최선을 다하고 있죠...",
  ui_story_5029_50290012_59_dialog_content = "그럼 네가 정말 그 「조무이치로」야?",
  ui_story_5029_50290012_60_dialog_content = "보스, 이런 건 비즈니스에서 매우 중요한 마케팅 수단이라고요.\n제가 이렇게 안 하면 영주님이 절 만나 주기나 하시겠어요?",
  ui_story_5029_50290012_61_dialog_content = "그리고 제가 책을 만들 자금이나 토지, 인력을 투자할 리도 없잖아요?",
  ui_story_5029_50290012_62_dialog_content = "하지만 내가 알기로는 당신 요구가 너무 불합리해서\n영주가 협력을 거절했다던데.",
  ui_story_5029_50290012_63_dialog_content = "그것도 지금뿐이죠. 영주님은 틀림없이 마음이 변하실 겁니다...",
  ui_story_5029_50290012_64_dialog_content = "음? 근데 이상하군요. 둘 다 왜 계속 저한테 질문을 하시는 거죠?",
  ui_story_5029_50290012_65_dialog_content = "설마 조사하려는 게 저였던 건 아니겠죠?",
  ui_story_5029_50290012_66_option_content = "아니야.",
  ui_story_5029_50290012_67_dialog_content = "오해하지 마. 난 그저 친구를 걱정해주는 것뿐이니까.",
  ui_story_5029_50290012_68_dialog_content = "보스가 절 걱정해 준다니... 정말 감동했습니다!",
  ui_story_5029_50290012_69_dialog_content = "이번 사업 계약이 성사되면 두 사람한테 한턱 쏠게요!",
  ui_story_5029_50290012_70_dialog_content = "호의는 고맙지만...",
  ui_story_5029_50290012_71_option_content = "맞아.",
  ui_story_5029_50290012_72_dialog_content = "쉿... 잊었어? 우린 지금 비밀 조사 중이야.",
  ui_story_5029_50290012_73_dialog_content = "크흠, 맞아.",
  ui_story_5029_50290012_74_dialog_content = "우린 그저 영주를 대신해서 어떤 허풍이 심한 상인의\n내력을 조사하던 중이야.",
  ui_story_5029_50290012_75_dialog_content = "당신 설명을 듣고 나니까 어느 정도는 이해했어.",
  ui_story_5029_50290012_76_dialog_content = "영주는 확실히 이 사업에 손을 대지 않는 게 좋겠어.",
  ui_story_5029_50290012_77_dialog_content = "...그래요. 확실히 전 제 신분을 적당히 속였어요.",
  ui_story_5029_50290012_78_dialog_content = "하지만 사업에 대해서라면 정말 진심이라구요.",
  ui_story_5029_50290012_79_dialog_content = "《아카나미 사메노스케 전기》는 더 넓은 시장에\n선보일 가치가 있는 책이에요.",
  ui_story_5029_50290012_80_dialog_content = "그 확신을 얻은 뒤로 제 인생은 빛나기 시작했어요!",
  ui_story_5029_50290012_81_dialog_content = "그래서 저는 먼 길도 마다하지 않고 이 문화의 항구 도시에 왔습니다.",
  ui_story_5029_50290012_81X1_dialog_content = "대규모 출판을 위한 협력 파트너를 찾기 위해서 말이죠!",
  ui_story_5029_50290012_82_dialog_content = "이 조무는 더는 당신들이 알고 있는 악덕 상인이 아니라구요.",
  ui_story_5029_50290012_83_dialog_content = "그러니까 색안경을 끼고 절 대하지 않으셨으면 좋겠네요.",
  ui_story_5029_50290012_84_dialog_content = "PlayerName, 넌 어떻게 생각해?",
  ui_story_5029_50290012_85_dialog_content = "조무가 지금 한 말이 거짓말은 아닌 것 같아.",
  ui_story_5029_50290012_86_dialog_content = "만약 정말로 그저 사업 파트너를 구하기 위해 온 거라면,\n조무는 물건을 훔칠 생각은 없었을 거야.",
  ui_story_5029_50290012_87_dialog_content = "방금 조무의 말을 듣고 나니까 나도 조금은 미안한 마음이 들었어.",
  ui_story_5029_50290012_88_dialog_content = "이유 없이 그의 동기를 의심하지 말았어야 했어. 다만...",
  ui_story_5029_50290012_89_dialog_content = "그래도 역시 아직 제대로 확인하지 못한 문제들이 있는 것 같아.",
  ui_story_5029_50290012_90_dialog_content = "예를 들면, 왜 엘비스의 저택에 《아카나미 사메노스케 전기》가\n그렇게 잔뜩 있었을까?",
  ui_story_5029_50290012_91_dialog_content = "조무가 어제 자기도 모르게 방에 두고 간 건 아닐까...?",
  ui_story_5029_50290012_92_dialog_content = "두 분께서도 영주님의 가족분들이신가요? 안녕하세요!",
  ui_story_5029_50290012_93_dialog_content = "넌...?",
  ui_story_5029_50290012_94_dialog_content = "전 사니라고 해요. 이 호텔에서 정원의 잡초를 관리하는 정원사랍니다.\n어젠 영주님의 저택에 방문해서 잔디를 깎았거든요~",
  ui_story_5029_50290012_95_dialog_content = "왜 우리가 영주의 가족이라고 생각하는 거지?",
  ui_story_5029_50290012_96_dialog_content = "앗, 제가 틀린 건가요? 죄송해요!",
  ui_story_5029_50290012_97_dialog_content = "방금 전 녹색 머리의 남자분이 영주님 가문 사람이라서...\n두 분도 당연히 그럴 거라 생각했어요...",
  ui_story_5029_50290012_98_dialog_content = "영주의 집에서 저 사람을 만났니?",
  ui_story_5029_50290012_99_dialog_content = "네! 어제 저녁에요. 확실해요.",
  ui_story_5029_50290012_100_dialog_content = "어제 잔디를 다 베고 앉아서 쉬고 있을 때,\n영주님과 저분이 방에서 나오시는 걸 봤어요.",
  ui_story_5029_50290012_101_dialog_content = "그러다 얼마 뒤에 저분이 뭔가 놔두고 온 게 있는지 다시 돌아오셨고,\n문을 열고 안에 들어갔다가 얼마 뒤에 나오셨어요.",
  ui_story_5029_50290012_102_dialog_content = "......",
  ui_story_5029_50290012_103_dialog_content = "PlayerName, 지금도 조무를 믿어?",
  ui_story_5029_50290012_104_dialog_content = "정말 조무가...?",
  ui_story_5029_50290012_105_dialog_content = "저, 저 설마 뭔가 잘못 말한 건가요?",
  ui_story_5029_50290012_106_dialog_content = "사니, 넌 우리한테 큰 도움이 됐어.",
  ui_story_5029_50290012_107_dialog_content = "네가 깎은 잔디도 정말 예뻤어.",
  ui_story_5029_50290012_108_dialog_content = "체크아웃 완료했습니다. 감사합니다.\n다음에도 저희 호텔을 찾아 주시기 바랍니다!",
  ui_story_5029_50290012_109_dialog_content = "다시 오길 원하신다면...\n여기 《아카나미 사메노스케 전기》를 몇 권 사시지 않겠습니까?",
  ui_story_5029_50290012_110_dialog_content = "그건...",
  ui_story_5029_50290012_111_dialog_content = "조무.",
  ui_story_5029_50290012_112_dialog_content = "...두 분이셨군요. 왜 아직도 절 놓아주지 않으시는 거죠?\n전 지금 비즈니스 중인데요.",
  ui_story_5029_50290012_113_dialog_content = "너한테 몇 가지 더 묻고 싶은 게 있어.",
  ui_story_5029_50290012_114_dialog_content = "어제 저녁에 영주를 만나고 난 뒤에, 몰래 영주의 서재로 돌아갔지?",
  ui_story_5029_50290012_115_dialog_content = "아~ 혹시 영주님이 여러분께 몰래 절 찾아오라고 한 건가요?",
  ui_story_5029_50290012_116_dialog_content = "어떻습니까? 영주님도 1권을 읽고 나니 이 책에 푹 빠지신 거겠죠?",
  ui_story_5029_50290012_117_dialog_content = "지금 당장 2권을 읽고 싶으신 거겠죠?",
  ui_story_5029_50290012_118_dialog_content = "그리고 출판 사업의 협력에 대해 저와 이야기를 나누고 싶으신 거겠죠.\n그렇죠?",
  ui_story_5029_50290012_119_dialog_content = "그러니까 당신이 영주의 서재에 침입했다는 사실을 인정하는 건가?",
  ui_story_5029_50290012_120_dialog_content = "영주님도 이 책에 매료된 이상 저도 더는 숨길 이유가 없겠죠.",
  ui_story_5029_50290012_121_dialog_content = "어제 영주님께선 사업 협력에 동의하지 않으셨죠.",
  ui_story_5029_50290012_122_dialog_content = "전 분명히 영주님께서 아직 이 책의 훌륭함을\n모르기 때문이라고 생각했어요.",
  ui_story_5029_50290012_123_dialog_content = "딱 1권만 읽어봐도 이 책이 얼마나 투자 가치가 있는지\n분명히 알 수 있을 텐데 말이에요!",
  ui_story_5029_50290012_124_dialog_content = "그렇게 생각한 저는 서재로 돌아갔고,\n영주님의 눈에 띄는 곳에 1권을 일부러 놓아뒀어요.",
  ui_story_5029_50290012_125_dialog_content = "다섯 권이나 말이죠!\n그래도 큰일을 하려면 작은 걸 아끼면 안 되는 법이니까요.",
  ui_story_5029_50290012_126_dialog_content = "이제야 영주님의 마음이 바뀌다니, 정말 다행이네요. 하하하하.",
  ui_story_5029_50290012_127_dialog_content = "아무래도 우리가 더 꼼꼼하게 못 찾은 것 같아. 다섯 권이나 있었다니.",
  ui_story_5029_50290012_128_dialog_content = "정말 그 이유만으로 영주의 서재에 몰래 돌아간 거야?",
  ui_story_5029_50290012_129_dialog_content = "그렇다니까요. 영주님은 어디 계시죠? 지금 바로 2권을 드릴게요!",
  ui_story_5029_50290012_130_dialog_content = "영주는 지금 공무 때문에 바빠.\n당신이 며칠 더 머물 수 있다면 내가 영주와의 접견을 주선해 줄게.",
  ui_story_5029_50290012_131_dialog_content = "휴, 그럼 전 가진 돈을 다 써버렸으니 더 저렴한 숙소를\n찾을 수밖에 없겠군요.",
  ui_story_5029_50290012_132_dialog_content = "역시 정상적인 비즈니스는 힘들다니까요...",
  ui_story_5029_50290013_1_dialog_content = "역시 늦었나... 연극이 벌써 시작됐어.",
  ui_story_5029_50290013_2_dialog_content = "베벌리가 정말 이 극장에 있을까?",
  ui_story_5029_50290013_3_dialog_content = "확실해.",
  ui_story_5029_50290013_4_dialog_content = "베벌리 씨가 이번에 하버 시티에 온 가장 큰 목적은\n바로 이 연극을 감상하기 위해서였거든.",
  ui_story_5029_50290013_5_dialog_content = "오늘만 해도 공연이 몇 개나 있는데, 이 공연인지는 어떻게 알아?",
  ui_story_5029_50290013_6_dialog_content = "젠 씨도 베벌리가 어떤 연극을 보려는 건지는 몰랐을 거잖아?",
  ui_story_5029_50290013_7_dialog_content = "근데 젠 씨가 말했어.\n베벌리 씨는 이번에 어떤 연극의 초연을 보러 온 거래!",
  ui_story_5029_50290013_8_dialog_content = "그래서 오늘 상연되는 연극을 다 알아봤는데...",
  ui_story_5029_50290013_9_dialog_content = "오늘 초연인 연극은 세 종류뿐이었어.",
  ui_story_5029_50290013_10_dialog_content = "그중 하나는 현대극이라서 베벌리 씨의 취향이 아냐.",
  ui_story_5029_50290013_11_dialog_content = "또 하나는 백야성에서도 자주 상연되는 공연이야.\n그런 걸 베벌리 씨가 굳이 이렇게 먼 곳까지 와서 볼 필요는 없어.",
  ui_story_5029_50290013_12_dialog_content = "그럼 남은 하나가 바로 이 《로미와 줄리》야.",
  ui_story_5029_50290013_13_dialog_content = "바이스, 너...",
  ui_story_5029_50290013_14_option_content = "진짜 탐정 같아!",
  ui_story_5029_50290013_15_dialog_content = "탐정 사무소를 차려도 될 정도야!",
  ui_story_5029_50290013_16_dialog_content = "헤헤...",
  ui_story_5029_50290013_17_option_content = "조금 무섭네...",
  ui_story_5029_50290013_18_dialog_content = "왠지 너한텐 아무것도 숨길 수 없을 것 같아...",
  ui_story_5029_50290013_19_dialog_content = "크흠...",
  ui_story_5029_50290013_20_dialog_content = "그 정도는 아니야.",
  ui_story_5029_50290013_21_dialog_content = "우리가 안 지도 이제 꽤 오래됐는데, 아직도 나를 잘 모르겠어?",
  ui_story_5029_50290013_22_dialog_content = "그냥 행동력이 좀 강할 뿐이야.",
  ui_story_5029_50290013_23_dialog_content = "근데 우리도 지금 곧바로 들어가서 베벌리 씨를 찾을 순 없어.\n공연이 끝날 때까지 기다려야 해.",
  ui_story_5029_50290013_24_dialog_content = "사전 공연이 벌써 시작됐는데요. 두 분은 안 들어가시나요?",
  ui_story_5029_50290013_25_dialog_content = "아, 말해줘서 고마워요. 근데 저흰 티켓이 없어서요...",
  ui_story_5029_50290013_26_dialog_content = "어머? 손님, 오늘 연극에 특별 행사가 있는 거 모르셨나요?",
  ui_story_5029_50290013_27_dialog_content = "「로미와 줄리」 초연 프로모션으로 2인 관람 시\n티켓을 반값 특가로 제공하고 있답니다!",
  ui_story_5029_50290013_28_dialog_content = "정말 흔치 않은 기회거든요.",
  ui_story_5029_50290013_29_dialog_content = "2인 관람 특가라... 그거 좋은데?",
  ui_story_5029_50290013_30_dialog_content = "근데 티켓은 이미 매진 아닌가요?",
  ui_story_5029_50290013_31_dialog_content = "네. 그런데 방금 어느 커플이 헤어지겠다고 싸우면서 가셔서...\n마침 티켓 두 장이 취소됐어요.",
  ui_story_5029_50290013_32_dialog_content = "헤어져요?",
  ui_story_5029_50290013_33_dialog_content = "헤어진 커플이 남긴 티켓이라면 조금 찝찝하게\n생각하실지도 모르겠네요...",
  ui_story_5029_50290013_34_dialog_content = "그래도 두 분은 사이가 정말 좋아 보이시네요.\n절대 쉽게 헤어지거나 하진 않을 것 같아요!",
  ui_story_5029_50290013_35_dialog_content = "우린 커플이...",
  ui_story_5029_50290013_36_dialog_content = "혹시 두 분만 괜찮으시다고 하면, 제가 특별히 10% 더 깎아드릴게요.",
  ui_story_5029_50290013_37_dialog_content = "네?!",
  ui_story_5029_50290013_38_dialog_content = "바이스, 혹시 연극 보고 싶어?",
  ui_story_5029_50290013_39_dialog_content = "어차피 연극이 끝날 때까지는 기다려야 되잖아.\n그럼 안에 들어가서 연극 보면서 기다리는 것도 좋을 것 같아.",
  ui_story_5029_50290013_40_dialog_content = "고마워, PlayerName. 난 네가 티켓값 아까워할 줄 알고 걱정했거든.",
  ui_story_5029_50290013_41_dialog_content = "감사합니다! 그럼 두 분 오래오래 예쁜 사랑 하세요!",
  ui_story_5029_50290013_42_dialog_content = "......",
  ui_story_5029_50290013_43_dialog_content = "으아...음... 네!",
  ui_story_5029_50290013_44_dialog_content = "(이 매표원, 나랑 바이스 사이를 오해한 모양이네...)",
  ui_story_5029_50290013_45_dialog_content = "(근데 저렇게 열심인데... 아니라고 정정하는 것도 왠지 미안하잖아.)",
  ui_story_5029_50290013_46_dialog_content = "(바이스도... 같은 생각이겠지?)",
  ui_story_5029_50290013_47_dialog_content = "그, 그럼 얼른 들어가자.",
  ui_story_5029_50290013_48_dialog_content = "응!",
  ui_story_5029_50290013_49_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5029_50290013_50_dialog_content = "훌쩍...",
  ui_story_5029_50290013_51_dialog_content = "이렇게 감동적인 연극일 줄은 몰랐어!",
  ui_story_5029_50290013_52_dialog_content = "초반에 남주인공이랑 여주인공이 꽃밭에서 만나는 장면도\n진짜 낭만적이었어!",
  ui_story_5029_50290013_53_dialog_content = "그러게.",
  ui_story_5029_50290013_54_dialog_content = "베벌리?!",
  ui_story_5029_50290013_55_dialog_content = "(연극에 빠져서 정작 용건을 잊고 있었잖아!)",
  ui_story_5029_50290013_56_dialog_content = "다만 안타깝게도 전반부가 아름다울수록 후반부의 비참함이 더 강해졌지.",
  ui_story_5029_50290013_57_dialog_content = "결국 두 사람은 갖가지 장벽과 오해 때문에,\n처음 만났던 그 꽃밭에서 죽고 말았으니까.",
  ui_story_5029_50290013_58_dialog_content = "그 수미상관의 구조는 비극적 미학의 정점에 달했다고 할 수 있겠어.",
  ui_story_5029_50290013_59_dialog_content = "비극이 이렇게나 아름답다니... 훌쩍...",
  ui_story_5029_50290013_60_dialog_content = "PlayerName, 바이스 씨, 두 사람도 이 연극을 보러 오다니 의외네.",
  ui_story_5029_50290013_61_dialog_content = "크흠, 그러게... 엄청난 우연이야!",
  ui_story_5029_50290013_62_dialog_content = "이 연극, 표현 자체는 전통적인 형식을 취하고 있지만,\n이야기의 핵심은 매우 선진적인 생각이었어.",
  ui_story_5029_50290013_63_dialog_content = "맞아. 이 연극은 확실히 최근에 만들어진 유일한 신작이야.",
  ui_story_5029_50290013_64_dialog_content = "하지만 두 주인공의 비극은 결국 신분의 격차 때문에 발생한 거야.",
  ui_story_5029_50290013_65_dialog_content = "두 사람이 만났을 때 서로의 신분을 밝히고, 제대로 선을 그었다면...",
  ui_story_5029_50290013_65X1_dialog_content = "결말은 달랐을 거야.",
  ui_story_5029_50290013_66_dialog_content = "난... 그렇게 생각하지 않아.",
  ui_story_5029_50290013_67_dialog_content = "주인공들의 죽음은 세상에 대한 경종이라고 생각해.",
  ui_story_5029_50290013_68_dialog_content = "이 연극은 사실 사람들에게 자아의 해방을 격려하고 있어.\n신분의 굴레를 깨고, 자유로운 연애를 하라고 말이야.",
  ui_story_5029_50290013_69_dialog_content = "호오? 그런 깊은 뜻이 담겨 있었던 건가...",
  ui_story_5029_50290013_70_dialog_content = "엘비스가 이런 종류의 연극을 하버 시티에서 상연하도록 승낙할 줄이야.",
  ui_story_5029_50290013_71_dialog_content = "베벌리도 여기 영주님이랑 아는 사이야?",
  ui_story_5029_50290013_72_dialog_content = "맞아. 어제도 특별히 그를 찾아갔던 참이었어.\n유감스럽게도 불쾌하게 헤어졌지만 말이야.",
  ui_story_5029_50290013_73_dialog_content = "왜? 영주님은 좋은 사람 같았는데.",
  ui_story_5029_50290013_74_dialog_content = "안타깝지만 그의 조상은 백야성에 귀순했기 때문에\n귀족이 될 수 있었을 뿐이야.",
  ui_story_5029_50290013_75_dialog_content = "비록 백야성의 귀족 칭호를 갖고 있지만,\n사실 그에겐 귀족 혈통은 전혀 없어.",
  ui_story_5029_50290013_76_dialog_content = "내가 무심코 이 사실을 말해버린 것 때문에\n엘비스는 불쾌한 기색을 보였어.",
  ui_story_5029_50290013_77_dialog_content = "그러더니 우리 이스크 가문의 영지가 이미 쇠퇴했고,\n이 광대한 하버 시티에는 미치지 못한다고 은연중에 조롱했지.",
  ui_story_5029_50290013_78_dialog_content = "나도 일시적으로 화가 나서 그대로 저택을 떠났어.",
  ui_story_5029_50290013_79_dialog_content = "지금 생각하면 나도 어젠 조금 실례했던 것 같아.\n귀족의 품격에 맞지 않는 행동이었어.",
  ui_story_5029_50290013_80_dialog_content = "당신이 그런 식으로 자기비판을 하다니, 그것만으로도 이미 큰 진전이네.",
  ui_story_5029_50290013_81_dialog_content = "《로미와 줄리》 속 주인공의 가족들도 그런 생각을 가지고\n서로 양보했다면...",
  ui_story_5029_50290013_82_dialog_content = "두 사람의 비극은 일어나지 않았을 거야.",
  ui_story_5029_50290013_83_dialog_content = "고마워, 바이스 양.",
  ui_story_5029_50290013_84_dialog_content = "당신이 아까 말했던 깊은 의미를 이해하려면\n아무래도 다시 한번 이 연극을 봐야 할 것 같아.",
  ui_story_5029_50290013_85_dialog_content = "그럼 다음 회차 티켓을 사러 가야겠어.",
  ui_story_5029_50290013_86_dialog_content = "오늘 보니까 베벌리 씨는 그래도 꽤 정직한 것 같아.\n생각을 그대로 말해주는 걸 보면... 물건을 훔칠 사람 같지는 않아.",
  ui_story_5029_50290013_87_dialog_content = "맞아. 오만한 귀족이라면 보통 자기 행실을 반성하지 않으니까.",
  ui_story_5029_50290013_88_dialog_content = "그래도 베벌리 씨는 계속 백야성에서 살았으니까,\n그 뿌리 깊은 귀족의 사고방식에 세뇌돼 버린 거겠지.",
  ui_story_5029_50290013_89_dialog_content = "그러니까 「귀족 혈통」 같은 데 집착하는 거고 말이야.",
  ui_story_5029_50290013_90_dialog_content = "《로미와 줄리》를 몇 번 더 본다면 베벌리 씨도 분명히\n그 안에 담긴 뜻을 깨달을 수 있을 거야.",
  ui_story_5029_50290013_90X1_dialog_content = "그럼 귀족 사상의 영향에서도 벗어날 수 있겠지!",
  ui_story_5029_50290013_91_dialog_content = "근데 우리 왠지 베벌리한테 뭔가 물어보는 걸 잊은 것 같은데...?",
  ui_story_5029_50290013_92_dialog_content = "실례합니다. 두 분은 영주님과 아는 사이신가요?",
  ui_story_5029_50290013_93_dialog_content = "무슨 일이죠?",
  ui_story_5029_50290013_94_dialog_content = "저는 완다라고 해요.\n혹시 괜찮으시다면 영주님께 감사의 말씀을 좀 전해주실 수 있을까요?",
  ui_story_5029_50290013_95_dialog_content = "어젯밤 원래 전 영주님 저택의 요리사 자리에 지원하려고 했어요.",
  ui_story_5029_50290013_96_dialog_content = "그런데 영주님은 제가 만든 요리를 시식하고 칭찬해 주셨지만,\n절 요리사로 저택에 받아들여 주진 않으셨어요.",
  ui_story_5029_50290013_97_dialog_content = "그래서 전 가망이 없다고 생각하고 있었는데,\n오늘 아침에 영주님이 보내 주신 「창업 자금」을 받았지 뭐예요.",
  ui_story_5029_50290013_98_dialog_content = "영주님은 제가 하버 시티에서 레스토랑을 열어 더 많은 사람들이\n제 음식을 맛볼 수 있길 바라셨던 거였어요...",
  ui_story_5029_50290013_99_dialog_content = "아아... 저만의 가게를 가지는 건 그동안 꿈도 꿔본 적 없었는걸요.\n그래서 감사의 말씀을 드리고 싶었는데,\n저택의 경비병이 들어갈 수 없다고 하더군요.",
  ui_story_5029_50290013_100_dialog_content = "그러다 마침 여기서 두 분을 발견했어요.\n그래서 말인데 저 대신 감사 인사를 좀 전해 주셨으면 해요!",
  ui_story_5029_50290013_101_dialog_content = "영주님은 정말 백성들을 많이 생각하는구나...\n물론이죠! 기회가 되면 우리가 전해 줄게요.",
  ui_story_5029_50290013_102_dialog_content = "근데... 우리가 영주님과 아는 사이라는 걸 어떻게 안 거죠?",
  ui_story_5029_50290013_103_dialog_content = "어젯밤 영주님 저택에서 아까 두 분과 이야기를 나누었던\n귀족분을 봤거든요.",
  ui_story_5029_50290013_104_dialog_content = "게다가 여러분도 마침 영주님에 대한 이야기를 하고 계시길래...\n그래서 실례인 줄 알면서도 말을 걸게 됐네요.",
  ui_story_5029_50290013_105_dialog_content = "어젯밤에 아까 그 귀족을 봤다구요?",
  ui_story_5029_50290013_106_dialog_content = "맞아요. 전 그때 저택 마당에서 채용 심사 결과를 기다리던 중이었어요...",
  ui_story_5029_50290013_107_dialog_content = "그러다가 저 아름다운 귀족분이 방에서 나오는 걸 봤어요.",
  ui_story_5029_50290013_107X1_dialog_content = "책장이 잔뜩 있는 방이었어요. 아마 서재였을 것 같아요.",
  ui_story_5029_50290013_108_dialog_content = "아무튼... 꼭 좀 부탁드릴게요!\n그리고 제 레스토랑이 문을 열면 한번 찾아와 주세요!",
  ui_story_5029_50290013_109_dialog_content = "......",
  ui_story_5029_50290013_110_dialog_content = "내 기억에 영주님이 베벌리 씨랑 만난 건 오후였어.\n근데 왜 밤에 또 나타난 걸까?",
  ui_story_5029_50290013_111_dialog_content = "베벌리는 아직 표를 사고 있을 거야, 다시 가서 물어보자!",
  ui_story_5029_50290013_112_dialog_content = "어젯밤에 어딜 갔냐고?",
  ui_story_5029_50290013_113_dialog_content = "흥, 그냥 본론부터 말해. 엘비스가 내 조사를 하라고 보낸 거지?",
  ui_story_5029_50290013_114_option_content = "아니야.",
  ui_story_5029_50290013_115_dialog_content = "네가 어떤 곳을 둘러봤는지 묻고 싶을 뿐이야.\n관광에 참고하려고. 하하하...",
  ui_story_5029_50290013_116_dialog_content = "아니라고?",
  ui_story_5029_50290013_117_dialog_content = "난 내가 왜 어젯밤에 엘비스의 서재에 들어갔는지\n그가 당신들한테 조사하라고 시킨 줄 알았어.",
  ui_story_5029_50290013_118_option_content = "맞아.",
  ui_story_5029_50290013_119_dialog_content = "쉿... PlayerName, 우린 비밀 조사 중이잖아!",
  ui_story_5029_50290013_120_dialog_content = "숨길 거 없어. 다 들었거든.",
  ui_story_5029_50290013_121_dialog_content = "당신들은 내가 어제 왜 엘비스의 서재에 들어갔는지 조사하고 있는 거지?",
  ui_story_5029_50290013_122_dialog_content = "뭐?!",
  ui_story_5029_50290013_123_dialog_content = "그럼 어젯밤에 진짜로 영주님 서재에 들어간 거야?",
  ui_story_5029_50290013_124_dialog_content = "그래, 딱히 숨길 일도 아니야.",
  ui_story_5029_50290013_125_dialog_content = "어제 그와 불쾌하게 헤어진 뒤로,\n난 내 기사 휘장을 잃어버린 걸 깨달았어.",
  ui_story_5029_50290013_126_dialog_content = "그 휘장은 내게 무척 중요한 의미가 있거든...",
  ui_story_5029_50290013_127_dialog_content = "하지만 아직 화가 난 상태라서, 그에게 찾아달라고 부탁하긴 좀 불편했어.",
  ui_story_5029_50290013_128_dialog_content = "그래서 내가 직접 서재로 가서 찾을 수밖에 없었던 거야.\n유감스럽게도 결국 찾지 못했지만 말이야.",
  ui_story_5029_50290013_129_dialog_content = "거기 간 이유가 정말 휘장뿐이었어?",
  ui_story_5029_50290013_130_dialog_content = "잘 들어. 엘비스가 당신들을 보냈든 아니든 상관없어.",
  ui_story_5029_50290013_130X1_dialog_content = "내가 서재에 갔던 걸 그 사람이 알고 말고도 내가 알 바 아냐...",
  ui_story_5029_50290013_131_dialog_content = "그저 날 대신해서 말을 전해줬으면 좋겠어.\n난 엘비스나 그의 서재에도 전혀 관심 없다고.",
  ui_story_5029_50290013_132_dialog_content = "난 내 기사 휘장을 되찾고 싶을 뿐이야.",
  ui_story_5029_50290014_1_dialog_content = "PlayerName, 어디 가?",
  ui_story_5029_50290014_2_dialog_content = "메이드 휴게실은 이쪽이야!",
  ui_story_5029_50290014_3_dialog_content = "알았어, 지금 갈게.",
  ui_story_5029_50290014_4_dialog_content = "대체 누가 큰 소리를 내는 거죠?",
  ui_story_5029_50290014_5_dialog_content = "여긴 휴게실이에요. 규칙을 모르는 건가요?",
  ui_story_5029_50290014_6_dialog_content = "어, 이 아줌마는 누구래?",
  ui_story_5029_50290014_7_dialog_content = "아줌마?!",
  ui_story_5029_50290014_8_dialog_content = "이, 이런 예의 없는 계집애는 대체 어디서 들어온 거죠?",
  ui_story_5029_50290014_9_dialog_content = "메이드장님이라고 부르세요!",
  ui_story_5029_50290014_10_dialog_content = "흥, 뭐 그리 대단한 사람이라고.",
  ui_story_5029_50290014_11_dialog_content = "당신...!",
  ui_story_5029_50290014_12_dialog_content = "메이드장님, 화내지 마세요.",
  ui_story_5029_50290014_13_option_content = "얜 아직 철없는 어린애잖아요.",
  ui_story_5029_50290014_14_dialog_content = "너무 엄격하게 대하지 말아 주세요.",
  ui_story_5029_50290014_15_dialog_content = "뭐야?!",
  ui_story_5029_50290014_16_option_content = "얜 착한 아이예요.",
  ui_story_5029_50290014_17_dialog_content = "그저 가끔 조금 직설적이어서 그런 거니까, 너그럽게 이해해 주세요.",
  ui_story_5029_50290014_18_dialog_content = "흥.",
  ui_story_5029_50290014_19_dialog_content = "그래서 무슨 용건이죠?",
  ui_story_5029_50290014_20_dialog_content = "젠 씨한테 들었어요. 여기로 오면...",
  ui_story_5029_50290014_21_dialog_content = "어머, 젠의 소개로 온 거였군요?",
  ui_story_5029_50290014_22_dialog_content = "젠은 영주님이 가장 신뢰하는 사람 중 하나죠.",
  ui_story_5029_50290014_23_dialog_content = "그의 추천으로 온 거라면 당신들에게 기회를 줄 수 있어요.",
  ui_story_5029_50290014_24_dialog_content = "소개... 추천?",
  ui_story_5029_50290014_25_dialog_content = "뭐야 그게...",
  ui_story_5029_50290014_26_dialog_content = "자, 이름이 뭐죠?",
  ui_story_5029_50290014_27_dialog_content = "PlayerName입니다. 우린...",
  ui_story_5029_50290014_28_dialog_content = "동생은 말을 못 하나요? 왜 오빠가 대신 말을 하죠?",
  ui_story_5029_50290014_29_dialog_content = "오빠 아니거든.",
  ui_story_5029_50290014_29X1_dialog_content = "난 오빠 없어. 아빠랑 엄마, 그리고 사부랑 선배뿐이야!",
  ui_story_5029_50290014_30_dialog_content = "됐어요. 그런 건 관심 없으니까요.",
  ui_story_5029_50290014_31_dialog_content = "당신은 뭘 할 수 있죠?",
  ui_story_5029_50290014_32_dialog_content = "하, 할 수 있는 거 많지!",
  ui_story_5029_50290014_33_dialog_content = "난 환상동물 마스터야. 환상동물의 성장과 진화, 번식을 도울 수 있어!",
  ui_story_5029_50290014_34_dialog_content = "동물 사육은 훌륭한 기술이죠. 하지만 여긴 목장이 아니에요.",
  ui_story_5029_50290014_35_dialog_content = "그래도 주방일 정도는 맡길 수 있겠군요.",
  ui_story_5029_50290014_36_dialog_content = "날 주방에 보내겠다고?",
  ui_story_5029_50290014_37_dialog_content = "뭐죠? 만족하지 못하는 건가요?",
  ui_story_5029_50290014_38_dialog_content = "그 모습으로 보자면 당신은 아직 메이드 경험이 없어 보이는데요.",
  ui_story_5029_50290014_39_dialog_content = "영주님의 저택에서 메이드가 될 수 있다는 것만으로도,\n당신에겐 이미 충분히 사치스러운 기회예요.",
  ui_story_5029_50290014_40_dialog_content = "메이드장님, 뭔가 오해하신 것 같은데요...",
  ui_story_5029_50290014_41_dialog_content = "메, 메이드장님.",
  ui_story_5029_50290014_42_dialog_content = "오늘 메이드 면접 참가자가 밖에서 기다리고 있어요...",
  ui_story_5029_50290014_43_dialog_content = "밖에? 그럼 이 두 사람은...?",
  ui_story_5029_50290014_44_dialog_content = "PlayerName 님?",
  ui_story_5029_50290014_45_dialog_content = "사나에? 네가 왜 여기 있어?",
  ui_story_5029_50290014_46_dialog_content = "그건... 말하자면 긴데요...\nPlayerName 님이야말로 왜 하버 시티에 계시는 거죠?",
  ui_story_5029_50290014_47_dialog_content = "PlayerName하고 난 마나에라는 메이드를 찾으러 왔어. 너 마나에 알아?",
  ui_story_5029_50290014_48_dialog_content = "그, 그건...",
  ui_story_5029_50290014_49_dialog_content = "그럼 젠이 마나에를 찾으라고 두 사람을 보냈던 건가요?",
  ui_story_5029_50290014_50_dialog_content = "방금 전 두 사람이 메이드 면접에 지원한 줄 알았지 뭐예요...\n정말 미안해요!",
  ui_story_5029_50290014_51_dialog_content = "마나에.",
  ui_story_5029_50290014_52_dialog_content = "아, 네!",
  ui_story_5029_50290014_53_dialog_content = "전 메이드 면접을 보러 가야 하니 두 손님을 잘 모시세요.",
  ui_story_5029_50290014_54_dialog_content = "네!",
  ui_story_5029_50290014_55_dialog_content = "네가 마나에였어?!",
  ui_story_5029_50290014_56_dialog_content = "솔직하게 말해! 너 무슨 나쁜 짓한 거 아냐?!",
  ui_story_5029_50290014_57_dialog_content = "저, 저저저저전...",
  ui_story_5029_50290014_58_dialog_content = "사나에... 기억났어. 마나에는 네 「언니」 이름이었지?",
  ui_story_5029_50290014_59_dialog_content = "뭐야? 그럼 이름까지 가짜였단 말이야?",
  ui_story_5029_50290014_60_dialog_content = "역시 피아가 잘못 본 게 아니었어. 너 아주 수상해!",
  ui_story_5029_50290014_61_dialog_content = "피아, 내가 아는 사나에는 네 생각처럼 수상한 사람이 아냐.",
  ui_story_5029_50290014_62_dialog_content = "일단 제대로 얘기를 들어보는 게 어떨까?",
  ui_story_5029_50290014_63_dialog_content = "고, 고마워요... PlayerName 님...",
  ui_story_5029_50290014_64_dialog_content = "왜 움브라톤에서 니나 곁에 안 있고 하버 시티까지 온 거야?",
  ui_story_5029_50290014_65_dialog_content = "저... 안데르센 가문에서 잘렸거든요...",
  ui_story_5029_50290014_66_dialog_content = "그래서 상회에 부탁해서 하버 시티의 메이드 일을 소개받은 거예요...",
  ui_story_5029_50290014_67_dialog_content = "...니나가 널 잘랐단 말이야?",
  ui_story_5029_50290014_68_dialog_content = "니나 아가씨는... 애초에 저와는 다른 신분의 사람이니까요.",
  ui_story_5029_50290014_69_dialog_content = "전 그저 메이드일 뿐이고,\n아가씨가 마음에 담아 두실 만한 존재가 아니에요...",
  ui_story_5029_50290014_70_dialog_content = "저도 이미 새로운 생활에 익숙해졌고, 그래서...",
  ui_story_5029_50290014_71_dialog_content = "그래도 앞뒤가 안 맞잖아. 이름은 왜 바꾼 건데?",
  ui_story_5029_50290014_72_dialog_content = "아, 그건... 잘렸다는 걸 밝히고 싶지 않아서요...",
  ui_story_5029_50290014_73_dialog_content = "으아아아... 참... 정원 청소하러 가야 해요!",
  ui_story_5029_50290014_74_dialog_content = "이제 시간이 없어요... 계속 안 가면 또 잘릴 거예요...",
  ui_story_5029_50290014_75_dialog_content = "키아로, 이 초록 머리 여자애가 도망치지 못하게 막아.",
  ui_story_5029_50290014_76_dialog_content = "루!",
  ui_story_5029_50290014_77_dialog_content = "으아아... 마나에 언니...",
  ui_story_5029_50290014_78_dialog_content = "어디서 들개가 설치고 있어? 저리 안 꺼져?!",
  ui_story_5029_50290014_79_dialog_content = "루...",
  ui_story_5029_50290014_80_dialog_content = "지금 사나에 일하러 가야 되는 거 안 보여? 너넨 눈도 없어?",
  ui_story_5029_50290014_81_dialog_content = "너네 때문에 사나에가 잘리면 책임질 수 있어?",
  ui_story_5029_50290014_82_dialog_content = "사나에, 가자. 신경 쓰지 마.",
  ui_story_5029_50290014_83_dialog_content = "루...",
  ui_story_5029_50290014_84_dialog_content = "자, 키아로, 괜찮아. 무서워할 거 없어. 벌써 가버렸어.",
  ui_story_5029_50290014_85_dialog_content = "루!",
  ui_story_5029_50290014_86_dialog_content = "PlayerName, 저게 네가 믿을 수 있는 친구가 맞아?",
  ui_story_5029_50290014_87_dialog_content = "방금 누가 봐도 계속 말을 돌리고 있었잖아!",
  ui_story_5029_50290014_88_dialog_content = "확실히... 방금 모습은 의심스러웠어.",
  ui_story_5029_50290014_89_dialog_content = "내가 아는 사나에는 저렇게 뭘 숨길 사람이 아냐.",
  ui_story_5029_50290014_90_dialog_content = "혹시 손님 여러분께서도 저 메이드를 조사하고 계신 겁니까?\n사실 저도 줄곧 저 메이드가 수상하다고 생각했습니다만.",
  ui_story_5029_50290014_91_dialog_content = "이 지팡이 짚은 아저씨는 또 누구야?",
  ui_story_5029_50290014_92_dialog_content = "아, 죄송합니다. 제 소개를 잊었군요.",
  ui_story_5029_50290014_93_dialog_content = "저는 쿠크라고 합니다. 할아버지 대로부터 쭉 영주님의 가문을 섬겨 왔지요.",
  ui_story_5029_50290014_94_dialog_content = "작년에 다리를 다친 뒤로는 메이드장님을 도와 심부름을 하고 있습니다.\n그래서 메이드들과도 조금 교류가 있습니다.",
  ui_story_5029_50290014_95_dialog_content = "하지만 제 생각에 저 마나에라는 메이드는 매우 수상합니다.",
  ui_story_5029_50290014_96_dialog_content = "왜 그렇게 생각하는 거죠?",
  ui_story_5029_50290014_97_dialog_content = "마나에는 움브라톤 상회의 소개로 왔다고 들었습니다.\n그래서 영주님도 차마 거절할 수 없어서 고용하셨지요.",
  ui_story_5029_50290014_98_dialog_content = "그런데 그 뒤로 뭘 하든 계속 사고만 치고 있습니다.\n그래서 벌써 몇 개월 분의 월급이 깎였죠.",
  ui_story_5029_50290014_99_dialog_content = "그런데도 마나에 본인은 전혀 신경 쓰는 기색도 없고,\n오히려 계속 틈만 나면 영주님 곁을 서성이고 있습니다.",
  ui_story_5029_50290014_100_dialog_content = "아무리 봐도 뭔가 다른 목적이 있어 보입니다.",
  ui_story_5029_50290014_101_dialog_content = "심지어 어젯밤에는 마나에가 몰래 영주님의 서재로\n들어가는 것도 봤다니까요.",
  ui_story_5029_50290014_102_dialog_content = "어제 저녁?!",
  ui_story_5029_50290014_103_dialog_content = "서재 청소는 점심 때 끝냈을 거잖아?",
  ui_story_5029_50290014_104_dialog_content = "저도 그 점이 이상하다고 생각했습니다...\n하지만 마나에는 움브라톤 상회의 소개를 받아서 왔기 때문에,\n저도 섣불리 개입할 순 없었습니다.",
  ui_story_5029_50290014_105_dialog_content = "다만 마나에가 영주님께 혹시라도 해가 되는 일을 할까\n무척 걱정이 됩니다.",
  ui_story_5029_50290014_106_dialog_content = "...그러니 두 분께서 관심을 갖고 이 일을 확인해 주셨으면 합니다.",
  ui_story_5029_50290014_107_dialog_content = "PlayerName, 이제 너도 네 친구를 그냥 놔둘 순 없겠지?",
  ui_story_5029_50290014_108_dialog_content = "일단 본인한테 직접 들어 보고 나서 생각하자.",
  ui_story_5029_50290014_109_dialog_content = "네? ...영주님이 절 조사하라고 하신 건가요?",
  ui_story_5029_50290014_110_option_content = "아니야.",
  ui_story_5029_50290014_111_dialog_content = "영주님은 이 사실을 몰라.",
  ui_story_5029_50290014_112_dialog_content = "우린 쿠크 씨한테 얘길 들었어...",
  ui_story_5029_50290014_113_option_content = "그래.",
  ui_story_5029_50290014_114_dialog_content = "(이런! 비밀 조사 중인 걸 잊어버렸잖아!)",
  ui_story_5029_50290014_115_dialog_content = "크흠, 아무튼 쿠크 씨 말로는...",
  ui_story_5029_50290014_116_dialog_content = "넌 어젯밤에 허락도 없이 영주님의 서재로 들어갔어.",
  ui_story_5029_50290014_117_dialog_content = "쿠크 씨가 그걸 얘기한 건가요?",
  ui_story_5029_50290014_118_dialog_content = "쿠크 씨... 부, 분명히 다른 사람한테는 말하지 않겠다고 약속하셨는데...",
  ui_story_5029_50290014_119_dialog_content = "너 쿠크 아저씨 입막음하려고 했어?",
  ui_story_5029_50290014_120_dialog_content = "아, 아니에요... 그런 건 아무한테도 안 했어요!",
  ui_story_5029_50290014_121_dialog_content = "그럼 넌 왜 어젯밤에 하필 아무도 없을 때 영주님의 서재로 들어간 건데?",
  ui_story_5029_50290014_122_dialog_content = "그...그게... 낮에 청소하다가 홀의 테이블에 있던 꽃병을 깨트렸거든요...",
  ui_story_5029_50290014_123_dialog_content = "근데 그때 손님이 곧 올 테니 빨리 자리를 비우라고\n젠 씨가 재촉하셨어요...",
  ui_story_5029_50290014_124_dialog_content = "전 꽃병을 깨트린 걸 들키면 또 잘릴까 걱정이 됐어요...",
  ui_story_5029_50290014_125_dialog_content = "그래서 밤에 아무도 없을 때 돌아와서 정리하려고...\n꽃병 조각을 소파 밑에 숨긴 거예요...",
  ui_story_5029_50290014_126_dialog_content = "하하, 그 조각은 이 피아가 찾아냈다구! 이건 몰랐지?",
  ui_story_5029_50290014_127_dialog_content = "역시 제가 청소를 제대로 못 한 거군요... 으아아...",
  ui_story_5029_50290014_128_dialog_content = "근데 홀의 테이블에는 꽃병이 그대로 있었어.",
  ui_story_5029_50290014_129_dialog_content = "그, 그건 제가 똑같은 걸 사서 갖다 놨으니까요...",
  ui_story_5029_50290014_130_dialog_content = "근데 넌 이미 몇 달 치 월급을 깎였다고 들었어.\n그런 비싼 꽃병을 살 돈이 어딨어?",
  ui_story_5029_50290014_131_dialog_content = "...으아아아앙!",
  ui_story_5029_50290014_132_dialog_content = "그 돈, 어디서 났어?",
  ui_story_5029_50290014_133_dialog_content = "니...니나 아가씨가 주신 거예요.",
  ui_story_5029_50290014_134_dialog_content = "PlayerName 님...\n저도 제가 이런 일에는 어울리지 않는다는 건 알아요...",
  ui_story_5029_50290014_135_dialog_content = "하지만 니나 아가씨가 절 보낸 이상...\n아가씨를 실망시키고 싶지 않았어요...",
  ui_story_5029_50290014_136_dialog_content = "그러니까 니나는 널 해고하지 않았던 거지?",
  ui_story_5029_50290014_137_dialog_content = "으으... 맞아요.",
  ui_story_5029_50290014_138_dialog_content = "그럼 니나가 너한테 도둑질을 시켰어?",
  ui_story_5029_50290014_139_dialog_content = "도둑질이라니... 뭐, 뭘 훔치는데요?",
  ui_story_5029_50290014_140_dialog_content = "전 그저 니나 아가씨 대신 영주님의 인품과 취향을\n조사하러 왔을 뿐이에요...",
  ui_story_5029_50290014_141_dialog_content = "상대에 대해 알게 되면 하버 시티와의 무역 협상에도 유리할 테니까요...",
  ui_story_5029_50290014_142_dialog_content = "저라면 금방 드러날 거라고 생각하긴 했지만...\n역시 PlayerName 님한테 들키고 말았네요...",
  ui_story_5029_50290014_143_dialog_content = "이제 니나 아가씨께 뭐라고 말씀드려야 할까요... 힝...",
  ui_story_5029_50290015_1_dialog_content = "오늘은 다들 왠지 다가가기 힘든 느낌이네.",
  ui_story_5029_50290015_2_dialog_content = "결국 다들 저렇게 경쟁하게 두는 수밖에 없는 건가?",
  ui_story_5029_50290015_3_dialog_content = "아니지, 잠깐만. 나도 멀쩡한 머리랑 다리가 있잖아.\n나도 직접 조사하면 되지.",
  ui_story_5029_50290015_4_dialog_content = "내가 제일 먼저 진범을 찾는다면 다들 저렇게 경쟁하지 않아도 되잖아?",
  ui_story_5029_50290015_5_dialog_content = "좋아, 나도 한다면 한다고!",
  ui_story_5029_50290015_6_dialog_content = "이 방은 거의 다 조사했어...",
  ui_story_5029_50290015_7_dialog_content = "방 밖에 뭔가 단서가 있으려나?",
  ui_story_5029_50290015_8_dialog_content = "영주님의 저택은 정말 대단하다니까.",
  ui_story_5029_50290015_9_dialog_content = "한쪽은 바다, 다른 한쪽은 숲이 보이잖아.",
  ui_story_5029_50290015_10_dialog_content = "젠 씨는 이 숲이 영주님 저택의 뒤뜰일 뿐이라고 했지만...",
  ui_story_5029_50290015_11_dialog_content = "<color=#828282>부스럭부스럭...</color>",
  ui_story_5029_50290015_12_dialog_content = "응?",
  ui_story_5029_50290015_13_dialog_content = "지금 누가 지나간 것 같은데...",
  ui_story_5029_50290015_14_dialog_content = "역시 누군가 있어... 착각이 아니었어!",
  ui_story_5029_50290015_15_dialog_content = "거기 당신! 여기서 뭐 하는 거지?",
  ui_story_5029_50290015_16_dialog_content = "왜, 왜 말이 없어?",
  ui_story_5029_50290015_17_dialog_content = "지금 뭐 하는 거야?!",
  ui_story_5029_50290015_18_dialog_content = "마, 말로 하자고... 삽 같은 걸 들고 있으면 위험하잖아...",
  ui_story_5029_50290015_19_dialog_content = "<color=#828282>쿵!</color>",
  ui_story_5029_50290015_20_dialog_content = "너...",
  ui_story_5029_50290015_21_dialog_content = "넌 대체...",
  ui_story_5029_50290015_22_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290015_23_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290015_24_dialog_content = "죄송하지만 점술이 도중에 끝나버렸군요...",
  ui_story_5029_50290015_25_dialog_content = "적절하지 못한 선택은 이처럼 곤란한 결말을 불러올 뿐입니다.",
  ui_story_5029_50290015_26_dialog_content = "그럼 조금 관점을 바꿔서, 이렇게 생각해 보시지요.",
  ui_story_5029_50290015_27_dialog_content = "방금 그건 그저... 그리 아름답지 못한 꿈에 불과했던 것입니다.",
  ui_story_5029_50290015_28_dialog_content = "당신의 현실 세계 속 안위에는 아무런 영향도 없는 것이지요.",
  ui_story_5029_50290015_29_dialog_content = "왜 그러시는지요. 그래도 그 아쉬운 표정을 거두실 순 없는 겁니까?",
  ui_story_5029_50290015_30_dialog_content = "다행히... 우리에겐 아직 시간이 있습니다.",
  ui_story_5029_50290015_31_dialog_content = "다시 시작하시면 됩니다.",
  ui_story_5029_50290015_32_dialog_content = "이것이 바로 꿈의 장점이죠. 안 그런가요?",
  ui_story_5029_50290016_1_dialog_content = "조무 녀석, 아무래도 정말 마음을 고쳐먹고\n제대로 된 사업을 시작한 모양이네.",
  ui_story_5029_50290016_2_dialog_content = "근데 조무가 숙박비를 낼 돈도 없을 줄은 생각도 못 했어.",
  ui_story_5029_50290016_3_dialog_content = "그저 고급 호텔에 묵을 돈이 없었을 뿐이겠지.\n평범한 여관 정도는 충분히 갈 수 있었을 거야.",
  ui_story_5029_50290016_4_dialog_content = "그럼 왜 공짜로 머물 수 있는 곳을 소개해 준 건데?",
  ui_story_5029_50290016_5_dialog_content = "내가 저자에게 말해준 곳은 영주의 사유지야.\n근처에는 사병들이 감시하고 있어.",
  ui_story_5029_50290016_6_dialog_content = "조무가 뭔가 수상한 움직임을 보이면 우린 곧바로 알 수 있을 거야.",
  ui_story_5029_50290016_7_dialog_content = "넌 역시 조무의 말을 전혀 안 믿었구나?",
  ui_story_5029_50290016_8_dialog_content = "하지만 저 모습으로 봤을 때 조무는 은 상자에 대해 정말 모르는 것 같아.",
  ui_story_5029_50290016_9_dialog_content = "그래, 나도 그렇게 생각해.\n하버 시티에 계속 머무르는 건 찔릴 게 없다는 뜻일 테니까.",
  ui_story_5029_50290016_10_dialog_content = "나도 그저 만약을 대비했을 뿐이야.",
  ui_story_5029_50290016_11_dialog_content = "게다가 나도 영주와의 접견을 주선해 주겠다고 저자에게 약속을 했어.",
  ui_story_5029_50290016_12_dialog_content = "난 그냥 조무가 의심하지 말라고 네가 그냥 한 말인 줄 알았는데.",
  ui_story_5029_50290016_13_dialog_content = "그건 맞아. 하지만 내가 꺼낸 말이라면 역시 해내고 싶어.",
  ui_story_5029_50290016_14_dialog_content = "그렇지 않으면 기사로서의 명예에도 흠이 되고,\n날 존중하고 신뢰해 주는 사람들에게도 올바른 처사가 아냐.",
  ui_story_5029_50290016_15_dialog_content = "(그럼... 아까 호텔에서 말한 약혼 얘기도... 그렇게 생각하는 거야...?)",
  ui_story_5029_50290016_16_dialog_content = "오호~ 방금 그 말 내가 다 들었어!",
  ui_story_5029_50290016_17_dialog_content = "하아? 방금 나 말로 안 했는데?!",
  ui_story_5029_50290016_18_dialog_content = "너흰 이미 조무를 용의선상에서 제외시킨 거야?",
  ui_story_5029_50290016_19_dialog_content = "(뭐야... 그거 얘기였어?)",
  ui_story_5029_50290016_20_dialog_content = "바이스, 피아, 너희 언제...",
  ui_story_5029_50290016_21_dialog_content = "역시 안 되겠어. 조사를 더 서둘러야겠어!",
  ui_story_5029_50290016_22_dialog_content = "그럼 피아가 쫓고 있는 용의자가 진범일 가능성이 있겠네?",
  ui_story_5029_50290016_23_dialog_content = "키아로, 가자!",
  ui_story_5029_50290016_24_dialog_content = "루!",
  ui_story_5029_50290016_25_dialog_content = "잠깐만... 아직 얘기도 다 안 했잖아...",
  ui_story_5029_50290016_26_dialog_content = "후우, 후우... 둘 다 대체 어디로 간 거야?",
  ui_story_5029_50290016_27_dialog_content = "PlayerName, 쫓아갈 거 없어.",
  ui_story_5029_50290016_28_dialog_content = "차라리 방으로 돌아가서 다른 단서는 없는지 한 번 더 찾아보자.",
  ui_story_5029_50290016_29_dialog_content = "그래...",
  ui_story_5029_50290016_30_dialog_content = "휴, 그냥 지금 바로 범인이 눈앞에 나타나서 잡혔으면 좋겠네.",
  ui_story_5029_50290016_31_dialog_content = "<color=#828282>쿵!</color>",
  ui_story_5029_50290016_32_dialog_content = "어이! 눈 똑바로 안 뜨고 다녀?!",
  ui_story_5029_50290016_33_dialog_content = "......",
  ui_story_5029_50290016_34_dialog_content = "어이! 거기 안 서?\n남의 가게 물건을 엎어놓고 사과 한마디도 안 하고 어딜 가?!",
  ui_story_5029_50290016_35_dialog_content = "쳇, 재수 없게!",
  ui_story_5029_50290016_36_dialog_content = "저 로브 입은 사람, 뭔가 수상해.\n이렇게 더운 날씨에 저렇게 꽁꽁 싸매고 있잖아.",
  ui_story_5029_50290016_37_dialog_content = "얼굴을 가리고 분주하게 가는 사람은 뭔가 일을 저지르고\n도망치는 경우가 많아.",
  ui_story_5029_50290016_38_dialog_content = "일을 저질러...?",
  ui_story_5029_50290016_39_dialog_content = "방금 얼핏 봤는데, 저 사람 로브 안에 뭔가 큰 물건을 안고 있었어...",
  ui_story_5029_50290016_40_dialog_content = "......",
  ui_story_5029_50290016_41_dialog_content = "은 상자?!",
  ui_story_5029_50290016_42_dialog_content = "거기 당신! 거기 서!",
  ui_story_5029_50290016_43_dialog_content = "이런, 우리 말을 듣자마자 달리기 시작했어!",
  ui_story_5029_50290016_44_dialog_content = "역시 뭔가 있어, 쫓아가자!",
  ui_story_5029_50290017_1_dialog_content = "우리가 베벌리한테 안 물어봤으면 베벌리도 휘장을 잃어버린 걸\n계속 마음에 담아 두고 있었을 거야.",
  ui_story_5029_50290017_2_dialog_content = "베벌리 씨랑 영주님 얘기도 거의 들어맞아. 그저...",
  ui_story_5029_50290017_3_dialog_content = "영주님은 베벌리 씨 일족 영지의 발전을 돕고 싶어서\n얘길 꺼냈을 뿐이었어.",
  ui_story_5029_50290017_4_dialog_content = "베벌리는 분명히 그 뜻을 오해해서 그렇게 화를 냈던 거겠지.",
  ui_story_5029_50290017_5_dialog_content = "가끔 난 백야성의 귀족과 내가 다른 종이 아닐까 하는\n생각이 들 때가 있어...",
  ui_story_5029_50290017_6_dialog_content = "그냥 제대로 이야기하고 악수하면 될 일을\n왜 꼭 그렇게 복잡하게 만드는 거야?",
  ui_story_5029_50290017_7_dialog_content = "근데 나도 이해가 안 돼. 우린 베벌리의 휘장이 어디 있는지 알고 있잖아.",
  ui_story_5029_50290017_8_dialog_content = "근데 넌 왜 그걸 베벌리한테 알려주지 말라는 거야?",
  ui_story_5029_50290017_9_dialog_content = "생각해 봐. 휘장이 영주님 저택의 카페에 있다는 걸 알면...",
  ui_story_5029_50290017_10_dialog_content = "베벌리 씨는 휘장을 찾아서 바로 떠날 거잖아?",
  ui_story_5029_50290017_11_dialog_content = "응, 그렇겠지.",
  ui_story_5029_50290017_12_dialog_content = "그럼 베벌리 씨는 앞으로 영주님과 다시는 어떤 교류도 하지 않을 거야.",
  ui_story_5029_50290017_13_dialog_content = "그러니까... 베벌리가 잃어버린 휘장이 카페에 있다는 걸\n영주님이 발견하게 만들어서...",
  ui_story_5029_50290017_14_dialog_content = "영주님이 베벌리한테 돌려주게 만들겠다는 거야?",
  ui_story_5029_50290017_15_dialog_content = "그럼 둘 다 화해할 계기가 생길 거잖아?",
  ui_story_5029_50290017_16_dialog_content = "바이스, 넌 정말 모두를 생각하는구나...",
  ui_story_5029_50290017_17_dialog_content = "휴, 나도 괜한 참견인 건 알아.",
  ui_story_5029_50290017_18_dialog_content = "베벌리 씨나 영주님이나 비록 귀족 티를 좀 내긴 해도,\n둘 다 사실은 좋은 사람들이야.",
  ui_story_5029_50290017_19_dialog_content = "둘 사이에 오해가 있다는 걸 알면서 보고만 있을 순 없잖아.",
  ui_story_5029_50290017_20_dialog_content = "내 주변에도 《로미와 줄리》 같은 비극이 벌어지는 건\n정말 보고 싶지 않아.",
  ui_story_5029_50290017_21_dialog_content = "그럼 너도 이젠 베벌리를 의심하지 않는 거구나?",
  ui_story_5029_50290017_22_dialog_content = "응!",
  ui_story_5029_50290017_23_dialog_content = "그치만... 결국 단서는 또 처음부터 다시 찾아야겠네.",
  ui_story_5029_50290017_24_dialog_content = "오호, 지금 피아가 뭔가 좋은 소식을 들은 것 같은데?",
  ui_story_5029_50290017_25_dialog_content = "베벌리를 이미 용의선상에서 제외시킨 거야?",
  ui_story_5029_50290017_26_dialog_content = "카렌, 피아? 너희 언제...",
  ui_story_5029_50290017_27_dialog_content = "그럼 실례했어. 난 조사를 계속하러 갈게.",
  ui_story_5029_50290017_28_dialog_content = "그럼 피아가 쫓고 있는 용의자가 진범일 가능성이 높겠어!",
  ui_story_5029_50290017_29_dialog_content = "키아로, 가자!",
  ui_story_5029_50290017_30_dialog_content = "너흰 뭔가 발견한 거 있... 잠깐만! 가지 마!",
  ui_story_5029_50290017_31_dialog_content = "후우, 후우... 둘 다 대체 어디로 간 거야?",
  ui_story_5029_50290017_32_dialog_content = "PlayerName, 됐어.",
  ui_story_5029_50290017_33_dialog_content = "차라리 돌아가서 다른 수상한 점이 없는지 다시 조사해 보자.",
  ui_story_5029_50290017_34_dialog_content = "나도 같은 생각이야. 근데...",
  ui_story_5029_50290017_35_dialog_content = "돌아가는 길 알아?",
  ui_story_5029_50290017_36_dialog_content = "어?",
  ui_story_5029_50290017_37_dialog_content = "방금 피아랑 카렌만 쫓아가느라 길을 못 봤어.",
  ui_story_5029_50290017_38_dialog_content = "정신 차리고 보니까 이미 이런 구석진 골목까지 왔지 뭐야...",
  ui_story_5029_50290017_39_dialog_content = "괜찮아, 저기 마침 사람도 있네. 가서 물어보면 되지~",
  ui_story_5029_50290017_40_dialog_content = "실례합니다, 혹시...",
  ui_story_5029_50290017_41_dialog_content = "......",
  ui_story_5029_50290017_42_dialog_content = "잠깐만요, 저흰 수상한 사람이 아니에요.\n영주님의 저택으로 가는 길을 물으려던 거예요!",
  ui_story_5029_50290017_43_dialog_content = "......!",
  ui_story_5029_50290017_44_dialog_content = "저 사람 이상하네. 왜 말을 듣다 말고 도망가는 거야?",
  ui_story_5029_50290017_45_dialog_content = "게다가 이렇게 더운데 로브 같은 걸 입고 얼굴까지 가리고...\n덥지도 않나?",
  ui_story_5029_50290017_46_dialog_content = "방금 내가 잘못 본 게 아니라면...",
  ui_story_5029_50290017_47_dialog_content = "저 사람 로브 밑에 뭔가 은빛으로 빛나는 걸 안고 있었어.",
  ui_story_5029_50290017_48_dialog_content = "......",
  ui_story_5029_50290017_49_dialog_content = "은 상자?!",
  ui_story_5029_50290017_50_dialog_content = "가자! 얼른 쫓아가야지!",
  ui_story_5029_50290018_1_dialog_content = "PlayerName, 정말 영주 아저씨한테 이 얘기 안 할 거야?",
  ui_story_5029_50290018_2_dialog_content = "사나에도 약속했잖아. 며칠 안에 알아서 그만두겠다고.",
  ui_story_5029_50290018_3_dialog_content = "니나가 무역 협상을 할 때 알아서 영주님한테 사과하게 하면 돼.",
  ui_story_5029_50290018_4_dialog_content = "니나는 아마 영주님과의 협상을 무척 중요하게 생각하고 있을 거야...",
  ui_story_5029_50290018_5_dialog_content = "그래서 어떻게든 영주님의 취향을 알고 미리 준비해 두려고 한 거겠지.",
  ui_story_5029_50290018_6_dialog_content = "안데르센 가문의 니나 아가씨라면 움브라톤에 가게도 많이 갖고 있잖아.\n근데 아직도 만족을 못 하는 거야?",
  ui_story_5029_50290018_7_dialog_content = "피아도 그렇지 않아?",
  ui_story_5029_50290018_8_dialog_content = "이미 대단한 환상동물 마스터면서, 계속해서 노력하고 있잖아.",
  ui_story_5029_50290018_9_dialog_content = "흥, 그거야 당연하지.",
  ui_story_5029_50290018_10_dialog_content = "피아는 사부보다 더 대단한 환상동물 마스터가 돼서\n가장 대단한 환상동물 책을 쓸 거라구!",
  ui_story_5029_50290018_11_dialog_content = "...그렇게 말하니까 왠지 니나 아가씨의 생각을\n조금은 이해할 수 있을 것 같아.",
  ui_story_5029_50290018_12_dialog_content = "근데 너 정말 사나에는 확실하게 혐의가 없다고 말할 수 있어?",
  ui_story_5029_50290018_13_dialog_content = "어쩌면 걔도 잠깐 홀려서 영주 아저씨의 보물을 훔쳤을지도\n모르는 거 아냐?",
  ui_story_5029_50290018_14_dialog_content = "내가 아는 사나에라면 그럴 마음도... 그럴 용기도 없어.",
  ui_story_5029_50290018_15_dialog_content = "적어도 우린 중요한 단서를 얻었잖아?",
  ui_story_5029_50290018_16_dialog_content = "응, 만약 사나에의 말을 정말로 믿을 수 있다면...",
  ui_story_5029_50290018_17_dialog_content = "사나에가 서재에 들어가기 전에도 방문은 잠겨 있지 않았어.",
  ui_story_5029_50290018_18_dialog_content = "상회에서 소개해 준 메이드가 그 니나 아가씨를 모시는 사나에였던 거야?",
  ui_story_5029_50290018_19_dialog_content = "그럼 너흰 이미 사나에를 용의선상에서 제외시킨 거야?",
  ui_story_5029_50290018_20_dialog_content = "으아아아앗!",
  ui_story_5029_50290018_21_dialog_content = "우리가 발견한 중요한 단서를 엿듣다니!",
  ui_story_5029_50290018_22_dialog_content = "미안, 돌아와서 새로운 단서를 찾으려던 참이었는데,\n우연히 너희 대화가 들렸어.",
  ui_story_5029_50290018_23_dialog_content = "비밀 이야기라면 난 방해하지 않을게.",
  ui_story_5029_50290018_24_dialog_content = "역시 안 되겠어. 나도 조사를 더 서둘러야겠어!",
  ui_story_5029_50290018_25_dialog_content = "너흰 뭔가 발견한 거 있...",
  ui_story_5029_50290018_26_dialog_content = "잠깐만! 가지 마!",
  ui_story_5029_50290018_27_dialog_content = "이런, 방심했어! 이러다간 피아의 현상금을 빼앗겨 버린다구!",
  ui_story_5029_50290018_28_dialog_content = "키아로, 서둘러!",
  ui_story_5029_50290018_29_dialog_content = "루우우...",
  ui_story_5029_50290018_30_dialog_content = "어? 키아로? 창가에서 뭘 보는 거야? 얼른 오라구.",
  ui_story_5029_50290018_31_dialog_content = "밖엔 나무밖에 없잖아...",
  ui_story_5029_50290018_32_dialog_content = "영주님의 뒤뜰은 정말 조용하다니까.",
  ui_story_5029_50290018_33_dialog_content = "어라? 숲속에... 누가 있는데?",
  ui_story_5029_50290018_34_dialog_content = "PlayerName, 밖에 저 사람 좀 봐! 뭔가 수상해!",
  ui_story_5029_50290018_35_dialog_content = "이렇게 더운 날씨에 저렇게 껴입고 있잖아.",
  ui_story_5029_50290018_36_dialog_content = "내가 시력이 좋아서 다행이지.\n아니면 암귀나 처음 보는 환상동물인 줄 알 뻔했잖아.",
  ui_story_5029_50290018_37_dialog_content = "저 사람, 뭐 하는 거지?",
  ui_story_5029_50290018_38_dialog_content = "뭔가 품에 숨기는 것 같은데?",
  ui_story_5029_50290018_39_dialog_content = "커다랗고, 은빛으로 빛나고 있어.",
  ui_story_5029_50290018_40_dialog_content = "......",
  ui_story_5029_50290018_41_dialog_content = "은 상자?!",
  ui_story_5029_50290018_42_dialog_content = "말도 안 돼! 범인이 영주 아저씨네 뒤뜰에 있다고?!",
  ui_story_5029_50290018_43_dialog_content = "......",
  ui_story_5029_50290018_44_dialog_content = "이런! 우릴 발견한 것 같아!",
  ui_story_5029_50290018_45_dialog_content = "키아로, 어서 쫓아가자!",
  ui_story_5029_50290018_46_dialog_content = "루!",
  ui_story_5029_50290019_1_dialog_content = "멈춰!",
  ui_story_5029_50290019_2_dialog_content = "......",
  ui_story_5029_50290019_3_dialog_content = "잘 들어. 지금이라도 자수하면 늦지 않았어.",
  ui_story_5029_50290019_4_dialog_content = "내 손에 잡힌다면 결과는 전혀 다를 거야!",
  ui_story_5029_50290019_5_dialog_content = "후우... 후우...",
  ui_story_5029_50290019_6_dialog_content = "우리 충고를 들을 생각이 전혀 없어. 더 빨리 산으로 도망치고 있잖아.",
  ui_story_5029_50290019_7_dialog_content = "백성에게 창을 겨누는 일은 하고 싶지 않았지만...",
  ui_story_5029_50290019_8_dialog_content = "충고에 귀를 기울이지 않는 악당이라면, 나도 용서하지 않아!",
  ui_story_5029_50290019_9_dialog_content = "카렌, 우리 나올 때 무기는 안 챙긴 것 같은데...",
  ui_story_5029_50290019_10_dialog_content = "쉿, 이건 작전이야.",
  ui_story_5029_50290019_11_dialog_content = "(뭐? 호텔에선 그렇게 거짓말을 못 했으면서...)",
  ui_story_5029_50290019_12_dialog_content = "(싸울 때는 「거짓말」의 병법을 사용할 수 있는 거야?)",
  ui_story_5029_50290019_13_dialog_content = "(어? 뭔가 카렌을 향해 날아오고 있어...?!)",
  ui_story_5029_50290019_14_dialog_content = "카렌! 위험해──!",
  ui_story_5029_50290019_15_dialog_content = "<color=#828282>쿵!</color>",
  ui_story_5029_50290019_16_dialog_content = "PlayerName, 내 목소리 들려?",
  ui_story_5029_50290019_17_dialog_content = "응...",
  ui_story_5029_50290019_18_dialog_content = "카, 카렌... 괜찮아?",
  ui_story_5029_50290019_19_dialog_content = "PlayerName, 너 정말 바보구나.",
  ui_story_5029_50290019_20_dialog_content = "네가 대신 공격을 받아줬으면서, 나한테 괜찮냐고 묻는 거야?",
  ui_story_5029_50290019_21_dialog_content = "모처럼... 새 드레스를 입었는데, 망가지면 큰일이잖아.",
  ui_story_5029_50290019_22_dialog_content = "이럴 때 무슨 드레스 걱정을 하고 있어?",
  ui_story_5029_50290019_23_dialog_content = "어디 다친 곳 없어? 얼른 보여줘!",
  ui_story_5029_50290019_24_dialog_content = "난 괜찮아. 잠깐만 쉬면 될 것 같아.",
  ui_story_5029_50290019_25_dialog_content = "너 방금 의식을 잃을 뻔했어. 근데 뭐가 괜찮다는 거야?",
  ui_story_5029_50290019_26_dialog_content = "네가 그럴수록 내가 더 자책하게 되잖아...",
  ui_story_5029_50290019_27_dialog_content = "난 동료가 나 때문에 다치는 건 원치 않아. 그런 일은 영원히 바라지 않아!",
  ui_story_5029_50290019_28_dialog_content = "카렌, 지금까지 난 계속 모두의 도움만 받아 왔어.",
  ui_story_5029_50290019_29_dialog_content = "그리고 마침내 기사가 될 수 있는 기회가 왔어.\n게다가 진짜 공주를 구했잖아.",
  ui_story_5029_50290019_30_dialog_content = "그래서 난 정말 영광이라고 생각해.",
  ui_story_5029_50290019_31_dialog_content = "...아무래도 넌 정말 하나도 안 아픈 모양이네.",
  ui_story_5029_50290019_32_dialog_content = "그것보다 이거 좀 봐.",
  ui_story_5029_50290019_33_dialog_content = "은 상자? 이게 바로 영주가 찾던 물건일까?",
  ui_story_5029_50290019_34_dialog_content = "범인은 아마 잡힐까 무서워서 은 상자를 우리한테 던지고 도망간 거겠지.",
  ui_story_5029_50290019_35_dialog_content = "아마 그렇게 멀리 가지 못했을 거야. 이대로 쫓아가면... 으윽, 아파...",
  ui_story_5029_50290019_36_dialog_content = "이래가지고 어떻게 쫓아가려고 그래?",
  ui_story_5029_50290019_37_dialog_content = "지금 네가 아무렇지 않은 것 같아도,\n만약 몸 안에 상한 곳이 있다면 큰일이야.",
  ui_story_5029_50290019_38_dialog_content = "세상 하나뿐인 아이테르가 나 때문에 무슨 일이 생기는 건 곤란해.",
  ui_story_5029_50290019_39_dialog_content = "그렇게 된다면 난 역사의 대죄인이 돼버릴지도 몰라.",
  ui_story_5029_50290019_40_dialog_content = "안 되겠어... 얼른 산을 내려가서 의사한테 가자.",
  ui_story_5029_50290019_41_dialog_content = "난...",
  ui_story_5029_50290019_42_option_content = "(산을 내려간다)",
  ui_story_5029_50290019_43_dialog_content = "그래. 영주님은 은 상자만 찾으면 된다고 했으니까.",
  ui_story_5029_50290019_44_dialog_content = "누가 범인인지는 모르겠지만, 이번엔 잠깐 눈이 멀어서 훔쳤을 뿐이고,\n앞으로 이런 일은 하지 않길 빌어야겠지...",
  ui_story_5029_50290019_45_dialog_content = "한번 나쁜 마음을 품은 사람은 두 번, 세 번도 품을 수 있는 법이야.",
  ui_story_5029_50290019_46_dialog_content = "그럼 왜 넌 산을 내려가자고 한 건데?",
  ui_story_5029_50290019_47_dialog_content = "악과 맞서 싸우는 길이라 해도 동료의 목숨을 바칠 순 없어.",
  ui_story_5029_50290019_48_dialog_content = "난 네가 무사했으면 좋겠어. 그게 다야.",
  ui_story_5029_50290019_49_dialog_content = "그저 「동료」인 거구나...",
  ui_story_5029_50290019_50_dialog_content = "뭐라고?",
  ui_story_5029_50290019_51_dialog_content = "아, 아무것도 아니야!",
  ui_story_5029_50290019_52_dialog_content = "카렌 전하, PlayerName 님, 정말 감사합니다!",
  ui_story_5029_50290019_53_dialog_content = "이렇게 빨리 잃어버린 물건을 찾아주실 줄이야...",
  ui_story_5029_50290019_54_dialog_content = "역시 우리 백야성의 공주 전하, 호위대장님이십니다!",
  ui_story_5029_50290019_55_dialog_content = "백야성은 공주 전하의 다스림으로 더 큰 평화와 번영을 얻을 것입니다!",
  ui_story_5029_50290019_56_dialog_content = "감사는 됐습니다. 그리 대단한 일도 아닌걸요.",
  ui_story_5029_50290019_57_dialog_content = "영주님은 좋은 사람 같았는데 저렇게 아부도 잘하는 줄은 몰랐네...",
  ui_story_5029_50290019_58_dialog_content = "PlayerName도 다쳤는데 말이야.",
  ui_story_5029_50290019_59_dialog_content = "의사도 괜찮다고 했으니까 걱정할 거 없어.",
  ui_story_5029_50290019_60_dialog_content = "어? 영주 아저씨 옆에 있는 게 그 잃어버린 은 상자인가요?",
  ui_story_5029_50290019_61_dialog_content = "흥, 별로 특별해 보이지도 않잖아.",
  ui_story_5029_50290019_62_dialog_content = "나도 운 좋게 거리에서 범인을 만났으면 좋았을 텐데 말이야.",
  ui_story_5029_50290019_63_dialog_content = "바이스 양, 피아 양, 두 분도 수고가 많으셨습니다.",
  ui_story_5029_50290019_64_dialog_content = "여러분께 소정의 수고비를 준비했습니다.\n또한 하버 시티의 특별한 디너 파티도 준비되어 있습니다.",
  ui_story_5029_50290019_65_dialog_content = "이쪽으로 오시죠.",
  ui_story_5029_50290019_66_option_content = "(계속 쫓아간다)",
  ui_story_5029_50290019_67_dialog_content = "영주님은 은 상자만 찾으면 된다고 했지만...",
  ui_story_5029_50290019_68_dialog_content = "역시 난 범인을 잡고 싶어.",
  ui_story_5029_50290019_69_dialog_content = "카렌, 네가 누구보다 백야성과 그 영토를 사랑하는 건 나도 잘 알고 있어.",
  ui_story_5029_50290019_70_dialog_content = "너도 범인이 또 악행을 벌이는 건 원하지 않잖아.",
  ui_story_5029_50290019_71_dialog_content = "하지만...",
  ui_story_5029_50290019_72_dialog_content = "난 아이테르야. 암귀와의 치열한 싸움도 이겨냈어.\n이 정도 작은 일이 뭐가 무섭겠어?",
  ui_story_5029_50290019_73_dialog_content = "안심해, 내 목숨은 질기니까.",
  ui_story_5029_50290019_74_dialog_content = "PlayerName... 알겠어.",
  ui_story_5029_50290019_75_dialog_content = "범인이 도망친 방향을 감지할 수 있어?",
  ui_story_5029_50290019_76_dialog_content = "응!",
  ui_story_5029_50290020_1_dialog_content = "휴, 휴우... 벌써 하버 시티 밖의 황야까지 와 버렸잖아.",
  ui_story_5029_50290020_2_dialog_content = "이렇게 한참 달렸는데 범인은 힘들지도 않은 건가?",
  ui_story_5029_50290020_3_dialog_content = "저 앞에 있어! 이제 뒷모습이 보여!",
  ui_story_5029_50290020_4_dialog_content = "근데 이 거리는... 여전히 한참 멀잖아.",
  ui_story_5029_50290020_5_dialog_content = "진작 이럴 줄 알았으면 활을 챙겼을 텐데.",
  ui_story_5029_50290020_6_dialog_content = "나도 비밀 조사 도중에 범인과 마주칠 줄은 전혀 몰랐어...",
  ui_story_5029_50290020_7_dialog_content = "휴, 휴우... 근데 저 녀석 정말 엄청난 체력이잖아.\n우린 따라잡기 힘들 것 같아...",
  ui_story_5029_50290020_8_dialog_content = "......",
  ui_story_5029_50290020_9_dialog_content = "바이스? 왜 멈춰?",
  ui_story_5029_50290020_10_dialog_content = "이렇게 된 이상... 시도해 보는 수밖에 없어.",
  ui_story_5029_50290020_11_dialog_content = "왜 갑자기 돌을 들고 날 보는데?",
  ui_story_5029_50290020_12_dialog_content = "나, 날 위협해 봤자 지금보다 더 빠르게 달리는 건 무리야...",
  ui_story_5029_50290020_13_dialog_content = "네 머리띠, 신축성이 있었던 걸로 기억하는데, 잠깐 빌려줄래?",
  ui_story_5029_50290020_14_dialog_content = "설마 머리띠로 활을 만들려고?",
  ui_story_5029_50290020_15_dialog_content = "그럴 리가 없잖아... 머리띠를 투석구로 써서 돌을 던질 거야.",
  ui_story_5029_50290020_16_dialog_content = "그렇구나... 자!",
  ui_story_5029_50290020_17_dialog_content = "고마워. 승부가 이 한 방에 달렸어.",
  ui_story_5029_50290020_18_dialog_content = "타깃 추적!",
  ui_story_5029_50290020_19_dialog_content = "...명중했어! 녀석이 쓰러졌어!",
  ui_story_5029_50290020_20_dialog_content = "학교 다닐 때 수업에서 배운 기술을 진짜로 쓰게 될 줄은 몰랐네.",
  ui_story_5029_50290020_21_dialog_content = "바이스 너 진짜 대단하잖아!",
  ui_story_5029_50290020_22_dialog_content = "그래도 위력엔 한계가 있어. 얼른 쫓아가야 돼!",
  ui_story_5029_50290020_23_dialog_content = "응!",
  ui_story_5029_50290020_24_dialog_content = "서둘러, 거의 다 왔어!",
  ui_story_5029_50290020_25_dialog_content = "......",
  ui_story_5029_50290020_26_dialog_content = "이런! 범인이 일어섰어!",
  ui_story_5029_50290020_27_dialog_content = "뭔가 던져버린 것 같은데?",
  ui_story_5029_50290020_28_dialog_content = "저건... 은 상자?!",
  ui_story_5029_50290020_29_dialog_content = "상자가 골짜기로 굴러떨어질 것 같아!",
  ui_story_5029_50290020_30_dialog_content = "계곡 깊은 곳에 떨어지면 다시 찾긴 힘들 거야...",
  ui_story_5029_50290020_31_dialog_content = "내가 주워올게!",
  ui_story_5029_50290020_32_dialog_content = "바이스? 조심해──!",
  ui_story_5029_50290020_33_dialog_content = "크흠...",
  ui_story_5029_50290020_34_dialog_content = "바이스? 바이스! 괜찮아?",
  ui_story_5029_50290020_35_dialog_content = "난... 괜찮아.",
  ui_story_5029_50290020_36_dialog_content = "왜 나랑 말도 안 하고 골짜기로 달려간 거야?",
  ui_story_5029_50290020_37_dialog_content = "너무 위험하잖아!",
  ui_story_5029_50290020_38_dialog_content = "PlayerName, 날 너무 얕본 거 아냐?",
  ui_story_5029_50290020_39_dialog_content = "크흠... 보다시피 무사히 올라왔잖아.",
  ui_story_5029_50290020_40_dialog_content = "나, 난 네가 골짜기에서 못 돌아올까 걱정했다고...",
  ui_story_5029_50290020_41_dialog_content = "안심해.",
  ui_story_5029_50290020_42_dialog_content = "일루미나에서 오랜 시간 훈련을 받은 내가 이렇게 작은 산에서\n조난당할 리가 없잖아?",
  ui_story_5029_50290020_43_dialog_content = "그리고... 봐!",
  ui_story_5029_50290020_44_dialog_content = "드디어 상자를 찾았잖아... 크흠...",
  ui_story_5029_50290020_45_dialog_content = "너 계속 헛기침하는 거... 어디 다친 거지?",
  ui_story_5029_50290020_46_dialog_content = "진짜로 괜찮다니까.",
  ui_story_5029_50290020_47_dialog_content = "지금 그게 중요한 게 아니잖아. 범인은 아직 멀리 못 갔을 거야.",
  ui_story_5029_50290020_48_dialog_content = "빨리 쫓아가자!",
  ui_story_5029_50290020_49_dialog_content = "으윽...",
  ui_story_5029_50290020_50_dialog_content = "바이스...?",
  ui_story_5029_50290020_51_dialog_content = "너 발목이 빨갛잖아... 부은 거 아니야?",
  ui_story_5029_50290020_52_dialog_content = "역시 무리하지 말자. 얼른 돌아가서 의사한테 가 보자.",
  ui_story_5029_50290020_53_dialog_content = "거의 다 왔잖아! 조금만 더 쫓으면 범인을 잡을 수 있어!",
  ui_story_5029_50290020_54_dialog_content = "PlayerName, 이대로는 너무 분해.",
  ui_story_5029_50290020_55_dialog_content = "너도 나처럼 범인을 잡고 싶잖아. 안 그래?",
  ui_story_5029_50290020_56_option_content = "(돌아가자고 설득한다)",
  ui_story_5029_50290020_57_dialog_content = "넌 아까부터 계속 괜찮다고 하지만, 나도 세 살짜리 어린애가 아냐.",
  ui_story_5029_50290020_58_dialog_content = "네가 다쳤다는 것 정도는 알 수 있다고.",
  ui_story_5029_50290020_59_dialog_content = "나도 범인을 잡고 싶은 건 맞아.\n하지만 네가 더 다치게 만들고 싶진 않아...",
  ui_story_5029_50290020_60_dialog_content = "PlayerName...",
  ui_story_5029_50290020_61_dialog_content = "영주님도 말했잖아. 은 상자만 찾으면 된다고.",
  ui_story_5029_50290020_62_dialog_content = "우린 임무를 마쳤어. 그러니까 무리하지 말자. 알았지?",
  ui_story_5029_50290020_63_dialog_content = "...응, 알겠어.",
  ui_story_5029_50290020_64_dialog_content = "PlayerName 님, 바이스 님, 정말 감사합니다!",
  ui_story_5029_50290020_65_dialog_content = "이렇게 빨리 잃어버린 물건을 찾아주실 줄이야...",
  ui_story_5029_50290020_66_dialog_content = "바이스 씨는 일루미나 탐색대의 대장이셨다고 들었습니다.",
  ui_story_5029_50290020_67_dialog_content = "역시 뛰어난 조사 능력을 가지고 계실 만했군요.\n두 분의 도움을 받을 수 있어서 정말 영광입니다!",
  ui_story_5029_50290020_68_dialog_content = "천만에요. 저도 영주님 덕분에 명의의 치료를 받을 수 있어서 감사드려요.",
  ui_story_5029_50290020_69_dialog_content = "그래도 상자를 찾는 일 때문에 몸까지 다치면 어떡해...",
  ui_story_5029_50290020_70_dialog_content = "어? 영주 아저씨 옆에 있는 게 그 잃어버린 은 상자인가요?",
  ui_story_5029_50290020_71_dialog_content = "흥, 별로 특별해 보이지도 않잖아.",
  ui_story_5029_50290020_72_dialog_content = "카렌 전하께서도 도움을 주셔서 정말 감사드립니다.",
  ui_story_5029_50290020_73_dialog_content = "부디 남은 시간에는 하버 시티에서의 여정을 마음껏 즐겨 주시지요!",
  ui_story_5029_50290020_74_dialog_content = "피아도 있다구요!",
  ui_story_5029_50290020_75_dialog_content = "오, 물론 피아 탐정님도 수고가 많으셨습니다.",
  ui_story_5029_50290020_76_dialog_content = "여러분께 소정의 수고비를 준비했습니다.\n또한 하버 시티의 특별한 디너 파티도 준비되어 있습니다.",
  ui_story_5029_50290020_77_dialog_content = "이쪽으로 오시죠.",
  ui_story_5029_50290020_78_option_content = "(바이스의 말에 동의한다)",
  ui_story_5029_50290020_79_dialog_content = "그래, 범인을 잡고 싶은 건 맞아.",
  ui_story_5029_50290020_80_dialog_content = "하지만 네가 다쳤는데 내버려 둘 수는 없어.",
  ui_story_5029_50290020_81_dialog_content = "너 오늘따라 왜 그래~",
  ui_story_5029_50290020_82_dialog_content = "우린 수많은 난관을 같이 겪어 왔잖아.\n그동안 내가 한 번이라도 움츠러든 적 있었어?",
  ui_story_5029_50290020_83_dialog_content = "...아니, 넌 항상 용감했어.",
  ui_story_5029_50290020_84_dialog_content = "PlayerName, 그러니까 날 믿어!",
  ui_story_5029_50290020_85_dialog_content = "이 정도 찰과상은 정말 아무렇지도 않으니까.",
  ui_story_5029_50290020_86_dialog_content = "게다가 범인은 앞으로도 다른 나쁜 짓을 할지도 몰라...",
  ui_story_5029_50290020_87_dialog_content = "범인이 법의 심판을 받도록 할 수 있는 건 지금 우리뿐이야.",
  ui_story_5029_50290020_88_dialog_content = "알겠어!",
  ui_story_5029_50290021_1_dialog_content = "키아로, 잘했어!",
  ui_story_5029_50290021_2_dialog_content = "키아로가 뒷산으로 통하는 길을 막아줘서 다행이야.",
  ui_story_5029_50290021_3_dialog_content = "아니었으면 저 범인이 산을 타는 속도는\n내가 도저히 따라잡을 수 없었을 거야...",
  ui_story_5029_50290021_4_dialog_content = "근데 도시의 거리에서도 녀석은 우리보다 더 빨라.",
  ui_story_5029_50290021_5_dialog_content = "대신 우린 키아로가 있잖아?",
  ui_story_5029_50290021_6_dialog_content = "루...",
  ui_story_5029_50290021_7_dialog_content = "키아로, 그럼 너만 믿을게.",
  ui_story_5029_50290021_8_dialog_content = "가서 아까 그 범인을 붙잡아!",
  ui_story_5029_50290021_9_dialog_content = "루우우?",
  ui_story_5029_50290021_10_dialog_content = "키아로, 왜 그래? 왜 멈추는 거야?",
  ui_story_5029_50290021_11_dialog_content = "저 악당이 바로 앞에 있잖아!",
  ui_story_5029_50290021_12_dialog_content = "루...",
  ui_story_5029_50290021_13_dialog_content = "거리에 사람이 많아졌어... 키아로는 벌써 누가 범인인지 모르게 된 거야.",
  ui_story_5029_50290021_14_dialog_content = "음, 괜찮아! 내가 신호총을 가져왔으니까.",
  ui_story_5029_50290021_15_dialog_content = "내가 신호탄으로 범인한테 마킹을 할게.\n넌 녀석이 은 상자를 못 가져가게 막아.",
  ui_story_5029_50290021_16_dialog_content = "키아로, 알았지?",
  ui_story_5029_50290021_17_dialog_content = "루!",
  ui_story_5029_50290021_18_dialog_content = "피아의 치명적 마킹 공격── 빵야!",
  ui_story_5029_50290021_19_dialog_content = "......?",
  ui_story_5029_50290021_20_dialog_content = "루...우!",
  ui_story_5029_50290021_21_dialog_content = "그래, 바로 그거야, 키아로! 쫓아가서 손을 확 물어버려!",
  ui_story_5029_50290021_22_dialog_content = "루우우!",
  ui_story_5029_50290021_23_dialog_content = "!!!",
  ui_story_5029_50290021_24_dialog_content = "피아, 네가 그렇게 사격 솜씨가 좋은 줄은 몰랐어!",
  ui_story_5029_50290021_25_dialog_content = "사실 나도 몰랐어.",
  ui_story_5029_50290021_26_dialog_content = "<color=#828282>빵야!</color>",
  ui_story_5029_50290021_27_dialog_content = "어? 왜 또 쐈어?",
  ui_story_5029_50290021_28_dialog_content = "으아앗... 어디다 쏜 거지?",
  ui_story_5029_50290021_29_dialog_content = "키아로, 두 번째는 신경 안 써도 돼!",
  ui_story_5029_50290021_30_dialog_content = "녀석이 은 상자를 못 가져가게 물고만 있어!",
  ui_story_5029_50290021_31_dialog_content = "......!",
  ui_story_5029_50290021_32_dialog_content = "범인이 쓰러졌어!",
  ui_story_5029_50290021_33_dialog_content = "키아로도 은 상자랑 같이 땅에 쓰러졌어...!",
  ui_story_5029_50290021_34_dialog_content = "키아로, 괜찮아?",
  ui_story_5029_50290021_35_dialog_content = "루!",
  ui_story_5029_50290021_36_dialog_content = "덕분에 은 상자는 멀쩡해!",
  ui_story_5029_50290021_37_dialog_content = "오늘 넌 정말 큰 활약을 했어!",
  ui_story_5029_50290021_38_dialog_content = "이제 은 상자를 가지고 돌아가면 현상금을 받을 수 있다구~",
  ui_story_5029_50290021_39_dialog_content = "이런, 범인이 항구 쪽으로 도망친다!",
  ui_story_5029_50290021_40_dialog_content = "흥, 이 피아 님한테서 도망칠 수 있을 줄 알고?",
  ui_story_5029_50290021_41_dialog_content = "쫓아가자!",
  ui_story_5029_50290021_42_dialog_content = "잠깐!",
  ui_story_5029_50290021_43_dialog_content = "어? 나?",
  ui_story_5029_50290021_44_dialog_content = "방금 거리에서 총을 쏜 게 너냐? 배짱도 좋군!",
  ui_story_5029_50290021_45_dialog_content = "말해! 누가 날 습격하라고 시켰지?",
  ui_story_5029_50290021_46_dialog_content = "아, 두 번째는 군인 아저씨한테 맞았구나...",
  ui_story_5029_50290021_47_dialog_content = "그럼 넌 여기서 총을 몇 발이나 쐈다는 거냐?",
  ui_story_5029_50290021_48_dialog_content = "하버 시티의 치안을 위협하려는 의도로 보이는군.\n조사가 필요하니 같이 동행해 줘야겠어!",
  ui_story_5029_50290021_49_dialog_content = "피아는 지금 아주 중요한 일을 하고 있다구. 따라갈 수 없어.",
  ui_story_5029_50290021_50_dialog_content = "지금 현행범이 체포에 저항하는 거냐?!",
  ui_story_5029_50290021_51_dialog_content = "잠깐만요. 뭔가 오해가 있는 것 같은데요.",
  ui_story_5029_50290021_52_dialog_content = "그쪽은 이 아가씨의 오빠인가?",
  ui_story_5029_50290021_53_dialog_content = "아니거든! 피아는 오빠 없어! 얘는 피아가 잡은 환상동물이야!",
  ui_story_5029_50290021_54_dialog_content = "...그러니까 동료라는 말이냐? 그럼 그쪽도 따라와라!",
  ui_story_5029_50290021_55_dialog_content = "저기, 방금 전엔 우리가 좀 급해서 그랬어요... 크흠, 피아...",
  ui_story_5029_50290021_56_dialog_content = "두 번째 신호탄을 다른 사람한테 쏜 건 우리 잘못이 맞아.\n얼른 사과해야지.",
  ui_story_5029_50290021_57_dialog_content = "흥.",
  ui_story_5029_50290021_58_dialog_content = "피아!",
  ui_story_5029_50290021_59_dialog_content = "흥... 알았어. 방금 그건 내 실수였어, 미안해.",
  ui_story_5029_50290021_60_dialog_content = "정말 미안해요.",
  ui_story_5029_50290021_61_dialog_content = "사과로 끝날 일이면 경비병이 왜 필요해?",
  ui_story_5029_50290021_62_dialog_content = "순순히 같이 가서 조사나 받아!",
  ui_story_5029_50290021_63_option_content = "(병사를 따라간다)",
  ui_story_5029_50290021_64_dialog_content = "알았어요, 같이 갈게요.",
  ui_story_5029_50290021_65_dialog_content = "PlayerName, 무슨 소리야? 그럼 범인은 어쩌려고...",
  ui_story_5029_50290021_66_dialog_content = "영주님도 말했잖아. 은 상자만 찾으면 된다고.",
  ui_story_5029_50290021_67_dialog_content = "나도 범인은 잡고 싶지만, 당장 저 병사를 설득하는 건 무리야.",
  ui_story_5029_50290021_68_dialog_content = "괜한 문제를 더 만들지 않는 게 좋을 것 같아.",
  ui_story_5029_50290021_69_dialog_content = "알았어... 뭐, 현상금을 받을 수 있다면 그걸로 됐어...",
  ui_story_5029_50290021_70_dialog_content = "뭘 속닥거리고 있는 거냐?",
  ui_story_5029_50290021_71_dialog_content = "당신을 따라갈게요. 대신 우릴 영주님한테 데려다주세요.",
  ui_story_5029_50290021_72_dialog_content = "영주님은 이런 사소한 일을 신경 쓰실 만큼 한가하지 않으시다.",
  ui_story_5029_50290021_73_dialog_content = "아무튼... 영주님을 만나면 당신도 사정을 알 수 있을 거예요.",
  ui_story_5029_50290021_74_dialog_content = "이 두 분은 제 손님이에요. 이 일에 대해서는 제가 대신 책임지도록 하죠.",
  ui_story_5029_50290021_75_dialog_content = "이 정도면 신호탄 자국을 지우는 비용으로 충분합니까?",
  ui_story_5029_50290021_76_dialog_content = "충분합니다! 아주 충분합니다! 감사합니다! 영주님!",
  ui_story_5029_50290021_77_dialog_content = "PlayerName 님, 피아 님, 정말 감사합니다!",
  ui_story_5029_50290021_78_dialog_content = "이렇게 빨리 잃어버린 물건을 찾아주실 줄이야...",
  ui_story_5029_50290021_79_dialog_content = "피아 씨는 환상동물 마스터라고 들었습니다만.",
  ui_story_5029_50290021_80_dialog_content = "저도 환상동물에 대한 책을 조금 읽은 적이 있습니다.\n다음에 기회가 되면 꼭 이야기를 나눠 보았으면 좋겠습니다!",
  ui_story_5029_50290021_81_dialog_content = "앗, 피아는 아직 제자를 거둘 생각까진 안 해봤는데...",
  ui_story_5029_50290021_82_dialog_content = "피아, 영주님은 그런 뜻으로 하신 말씀이 아닐 거야.",
  ui_story_5029_50290021_83_dialog_content = "아무튼 두 분의 도움을 받을 수 있어서 정말 영광입니다!",
  ui_story_5029_50290021_84_dialog_content = "에이, 영주 아저씨, 뭘 그렇게까지~",
  ui_story_5029_50290021_85_dialog_content = "그치만 그 병사가 방해하지만 않았으면\n우린 분명히 범인도 잡았을 거라구!",
  ui_story_5029_50290021_86_dialog_content = "피아, 설마 이 정보를 온 거리에 퍼트린 건 아니지...?",
  ui_story_5029_50290021_87_dialog_content = "그럼 전혀 비밀 조사가 아니잖아?",
  ui_story_5029_50290021_88_dialog_content = "괜찮아. 범인을 쫓고 있는 건 사람들도 봤겠지만,\n자세한 사연까진 모를 테니까.",
  ui_story_5029_50290021_89_dialog_content = "카렌 전하와 바이스 양께서도 도움을 주셔서 정말 감사드립니다.",
  ui_story_5029_50290021_90_dialog_content = "부디 남은 시간에는 하버 시티에서의 여정을 마음껏 즐겨 주시지요!",
  ui_story_5029_50290021_91_dialog_content = "여러분께 소정의 수고비를 준비했습니다.\n또한 하버 시티의 특별한 디너 파티도 준비되어 있습니다.",
  ui_story_5029_50290021_92_dialog_content = "이쪽으로 오시죠.",
  ui_story_5029_50290021_93_option_content = "(병사를 따라가지 않는다)",
  ui_story_5029_50290021_94_dialog_content = "미안하지만 우린 지금 정말 중요한 일이 있어요.\n게다가 이 일은 당신들 영주님이 직접 우리한테 맡긴 거예요.",
  ui_story_5029_50290021_95_dialog_content = "잘 생각해 보세요. 만약 계속 우릴 방해해서...",
  ui_story_5029_50290021_96_dialog_content = "우리가 임무를 완수하지 못하게 된다면, 당신도 책임을 피할 순 없어요.",
  ui_story_5029_50290021_97_dialog_content = "그런...",
  ui_story_5029_50290021_98_dialog_content = "증거는 있나? 그렇게 말만 하면 내가 뭘 보고 믿어야 하지?",
  ui_story_5029_50290021_99_dialog_content = "믿을 수 없다면 지금 당장 우릴 데리고 영주님께 가 보세요.",
  ui_story_5029_50290021_100_dialog_content = "그때 가서 영주님이 당신한테 뭐라고 할지 들어 보시죠.",
  ui_story_5029_50290022_1_dialog_content = "우와~!",
  ui_story_5029_50290022_2_dialog_content = "이렇게 맛있는 것들은 하버 시티에 온 뒤로 처음 봐!",
  ui_story_5029_50290022_3_dialog_content = "흐응~ 영주 아저씨도 양심은 있었구나.",
  ui_story_5029_50290022_4_dialog_content = "오늘 이리저리 다니느라 뱃가죽이 등에 붙을 것 같다구!\n그럼 사양하지 않겠어~",
  ui_story_5029_50290022_5_dialog_content = "...천천히 먹어. 아무도 안 뺏어가니까.",
  ui_story_5029_50290022_6_dialog_content = "이 상자에 든 나이티움이 전부 우리 수고비야?",
  ui_story_5029_50290022_7_dialog_content = "영주님 정말 통이 크시네!",
  ui_story_5029_50290022_8_dialog_content = "그럼 각자 자기 몫이 있을 텐데, 어떻게 나눠야 하지?",
  ui_story_5029_50290022_9_dialog_content = "이번 일에 공이 제일 큰 사람은...",
  ui_story_5029_50290022_10_dialog_content = "넌 학창 시절엔 그렇게 돈을 좋아하진 않았던 것 같은데.",
  ui_story_5029_50290022_11_dialog_content = "크흠, 나, 나도 다 먹고살려고 이러는 거라구.",
  ui_story_5029_50290022_12_dialog_content = "난 백야성의 아가씨나 귀공자처럼 어딜 가도 누가 돌봐 주진 않잖아.",
  ui_story_5029_50290022_13_dialog_content = "...그럼 그 돈은 너희끼리 나눠. 내 몫은 안 따져도 돼.",
  ui_story_5029_50290022_14_dialog_content = "뭐어? 돈 필요 없어? 그럼 피아한테 줘!",
  ui_story_5029_50290022_15_dialog_content = "그걸로 시라 선배에게 선물 사 줄 거야.\n그럼 나한테 싫은 소리도 덜 할 테니까.",
  ui_story_5029_50290022_16_dialog_content = "그냥 카렌 몫도 똑같이 나누는 게 공평하지 않을까?",
  ui_story_5029_50290022_17_dialog_content = "키아로, 키아로, 너도 한입 먹어!",
  ui_story_5029_50290022_18_dialog_content = "피아, 애완동물을 식탁에 올리면 안 돼.",
  ui_story_5029_50290022_19_dialog_content = "...키아로는 내 동료야. 애완동물 아니거든!",
  ui_story_5029_50290022_20_dialog_content = "(이 세 사람 사이의 분위기... 뭔가 이상해.)",
  ui_story_5029_50290022_21_dialog_content = "(그나저나 영주님, 잠깐 자리를 비우더니 왜 아직도 안 오는 거지?\n영주님이 돌아오면 이 어색한 분위기도 풀릴 것 같은데...)",
  ui_story_5029_50290022_22_dialog_content = "(휴, 이럴 줄 알았으면 처음에 그냥...)",
  ui_story_5029_50290022_23_dialog_content = "영주님...",
  ui_story_5029_50290022_24_dialog_content = "뭐라고요?!",
  ui_story_5029_50290022_25_dialog_content = "(휴, 영주님이 드디어 돌아왔네.)",
  ui_story_5029_50290022_26_dialog_content = "(어라? 젠 씨가 영주님 귀에 뭐라고 속삭이는데?)",
  ui_story_5029_50290022_27_dialog_content = "(왜 영주님의 안색이 갑자기 변한 거지?)",
  ui_story_5029_50290022_28_dialog_content = "(...숨이... 갑자기 가빠져...)",
  ui_story_5029_50290022_29_dialog_content = "(왜 뭔가 불길한 예감이 드는 거지?)",
  ui_story_5029_50290022_30_dialog_content = "(대체 뭐가 어떻게 된 거야?)",
  ui_story_5029_50290022_31_dialog_content = "(...범인?!)",
  ui_story_5029_50290022_32_dialog_content = "(범인이 또 돌아온 건가?)",
  ui_story_5029_50290022_33_dialog_content = "(이번엔 대체 또 무슨 짓을 저지르려는 거지...)",
  ui_story_5029_50290022_34_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290022_35_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290022_36_dialog_content = "제 얼굴을 보고 실망하셨습니까?",
  ui_story_5029_50290022_37_dialog_content = "이제 아셨겠지요. 운명을 지배한다는 것은 그리 쉬운 일이 아닙니다.",
  ui_story_5029_50290022_38_dialog_content = "게다가 당신은 직접 써 내려간 결말에\n그다지 만족하지 않으시는 듯하군요.",
  ui_story_5029_50290022_39_dialog_content = "가슴속에 의문과 곤혹이 가득합니까? 하하하...",
  ui_story_5029_50290022_40_dialog_content = "꿈의 세계에서만이 아니라, 현실의 세계에서도 다를 바가 없겠죠.",
  ui_story_5029_50290022_41_dialog_content = "우린 명확한 답을 얻어내지 못했습니다.",
  ui_story_5029_50290022_42_dialog_content = "하지만 줄곧 선택을 다른 사람에게 맡기기만 해서는,\n어떻게 자신만의 이야기를 가질 수가 있겠는지요.",
  ui_story_5029_50290022_43_dialog_content = "휴... 다행히 우리에겐 아직 시간이 있습니다.",
  ui_story_5029_50290022_44_dialog_content = "당신이 아직 꿈속의 결말을 다시 쓰고 싶어 한다는\n전제가 붙겠지만 말입니다.",
  ui_story_5029_50290023_1_dialog_content = "카렌, 어때?",
  ui_story_5029_50290023_2_dialog_content = "......",
  ui_story_5029_50290023_3_dialog_content = "범인은 아주 교활해. 전혀 흔적을 남기지 않았어.",
  ui_story_5029_50290023_4_dialog_content = "나도 도망간 방향을 감지할 수가 없어...",
  ui_story_5029_50290023_5_dialog_content = "백야성의 호위대장이면서 범인을 놓치다니...",
  ui_story_5029_50290023_6_dialog_content = "내 탓이야. 내가 아까 정신을 잃지만 않았어도 진작 범인을 잡았을 거야.",
  ui_story_5029_50290023_7_dialog_content = "그런 말 하지 마. 넌 날 감싸다가 다친 거잖아.",
  ui_story_5029_50290023_8_dialog_content = "아무튼... 그때 내가 더 좋은 방법을 생각해 냈어야 했어!",
  ui_story_5029_50290023_9_dialog_content = "게다가 저 범인은 내가 지금까지 봤던 녀석들 중에\n가장 빨리 도망친 녀석이었어.",
  ui_story_5029_50290023_10_dialog_content = "오르막길인데도 숨도 하나 안 차고 달려갔잖아.\n암귀라도 저렇게는 못 할걸.",
  ui_story_5029_50290023_11_dialog_content = "위로할 필요는 없어, PlayerName.",
  ui_story_5029_50290023_12_dialog_content = "날 달래려고 그러는 거 알고 있어.",
  ui_story_5029_50290023_13_dialog_content = "근데 그거 알아?",
  ui_story_5029_50290023_14_dialog_content = "기사의 자격은 거느린 병사의 수나 경험한 싸움의 수로\n결정되는 게 아냐...",
  ui_story_5029_50290023_15_dialog_content = "자신의 행위, 그리고 자신의 실패까지 책임지는 자세가 중요한 거야.",
  ui_story_5029_50290023_16_dialog_content = "카렌...",
  ui_story_5029_50290023_17_dialog_content = "왜 그래? 왜 갑자기 그런 표정을 짓는 건데?",
  ui_story_5029_50290023_18_dialog_content = "네가 동갑내기인 우리보다 훨씬 침착하고 굳센 사람이라는 건\n이미 진작부터 알고 있었지만...",
  ui_story_5029_50290023_19_dialog_content = "왠지 요즘 넌 전보다 더 성숙해진 것 같은 느낌이 들어.",
  ui_story_5029_50290023_20_dialog_content = "칭찬으로 받아 둘게. 고마워.",
  ui_story_5029_50290023_21_dialog_content = "...넌 항상 자신을 억누르고 있는 것 같아.",
  ui_story_5029_50290023_22_dialog_content = "음?",
  ui_story_5029_50290023_23_dialog_content = "내 착각일 수도 있겠지만...",
  ui_story_5029_50290023_24_dialog_content = "넌 계속 전지전능하고 약점이 없는 성인이 되려고\n자신을 몰아붙이고 있는 것 같아.",
  ui_story_5029_50290023_25_dialog_content = "......",
  ui_story_5029_50290023_26_dialog_content = "그래서 그런 건지는 모르겠지만...\n네가 더 강하고 과감한 모습을 보일수록 난 왠지 마음이 아파.",
  ui_story_5029_50290023_27_dialog_content = "네가 나처럼 데면데면할 수도 없고...",
  ui_story_5029_50290023_28_dialog_content = "자기 희로애락을 토해낼 수도 없고...",
  ui_story_5029_50290023_29_dialog_content = "네가 이미 충분히 많은 것들을 짊어지고 있는데도...\n여전히 많은 사람이 널 온실 속 화초라고 비웃는 게 마음 아파.",
  ui_story_5029_50290023_30_dialog_content = "......",
  ui_story_5029_50290023_31_dialog_content = "푸훕, 아하하하하.",
  ui_story_5029_50290023_32_dialog_content = "왜, 왜 웃는 건데?",
  ui_story_5029_50290023_33_dialog_content = "미안해, 나도 왜 웃었는지 모르겠어.",
  ui_story_5029_50290023_34_dialog_content = "다만 지금까지 아무도 나한테 그런 말을 한 적이 없어서,\n나도 어떻게 대답하면 좋을지 잘 모르겠다는 생각이 들었거든.",
  ui_story_5029_50290023_35_dialog_content = "그, 그래. 내가 이상한 말한 건 신경 쓰지 마.",
  ui_story_5029_50290023_36_dialog_content = "어쩌면 아까 부딪혀서 머리가 좀 이상해진 모양이야...",
  ui_story_5029_50290023_37_dialog_content = "그것보다 돌아가서 영주님한테 뭐라고 설명할지 생각해 보자.",
  ui_story_5029_50290023_38_dialog_content = "아무 수확이 없었던 건 아니잖아. 적어도 은 상자는 되찾았으니까.",
  ui_story_5029_50290023_39_dialog_content = "게다가 우연이지만 다른 보물도 찾았고 말이야.",
  ui_story_5029_50290023_40_dialog_content = "다른 보물?",
  ui_story_5029_50290023_41_dialog_content = "PlayerName, 고개를 들어 봐.",
  ui_story_5029_50290023_42_dialog_content = "응?",
  ui_story_5029_50290023_43_dialog_content = "봐, 이 산꼭대기에 오래된 전망대가 있었어.",
  ui_story_5029_50290023_44_dialog_content = "여기선 하버 시티의 야경을 한눈에 볼 수 있어.",
  ui_story_5029_50290023_45_dialog_content = "우린 지금 하버 시티의 뒷산에 있는 거잖아?",
  ui_story_5029_50290023_46_dialog_content = "그래서 이렇게 전망이 좋았던 거구나.",
  ui_story_5029_50290023_47_dialog_content = "지금까지 아무도 나한테 하버 시티에 이런 멋진 곳이 있다고\n말해준 적 없었어!",
  ui_story_5029_50290023_48_dialog_content = "(카렌... 갑자기 엄청 신난 것 같은데?)",
  ui_story_5029_50290023_49_dialog_content = "PlayerName, 뭘 멍하니 있어?",
  ui_story_5029_50290023_50_dialog_content = "여기 풍경, 정말 멋진 것 같아!",
  ui_story_5029_50290023_51_dialog_content = "바다는 마치 깊은 잠에 빠진 검은 짐승 같고,\n하버 시티는 꺼지지 않는 등불 같아.",
  ui_story_5029_50290023_52_dialog_content = "도시 전체가 마치 아스트라 대륙에 새겨진 진주처럼 빛나고 있어...",
  ui_story_5029_50290023_53_dialog_content = "정말... 예쁘네.",
  ui_story_5029_50290023_54_option_content = "고마워, 카렌.",
  ui_story_5029_50290023_55_dialog_content = "나야말로 고마워.",
  ui_story_5029_50290023_56_dialog_content = "나 아직 뭐가 고마운지도 말 안 했는데...",
  ui_story_5029_50290023_57_dialog_content = "마찬가지야. 나도 아직 뭐가 고마운지 말 안 했어.",
  ui_story_5029_50290023_58_dialog_content = "너... 갑자기 왜 그렇게 유치해졌어?",
  ui_story_5029_50290023_59_dialog_content = "아까 내가 너무 성숙해져서 싫다고 그랬잖아.",
  ui_story_5029_50290023_60_option_content = "나한테 하고 싶은 말 있지?",
  ui_story_5029_50290023_61_dialog_content = "응...",
  ui_story_5029_50290023_62_dialog_content = "그거 알아? 백야성의 야경도 하버 시티 못지않다는 거.",
  ui_story_5029_50290023_63_dialog_content = "다만 그때마다 난 항상 둘 중 하나였어.\n임무를 수행하고 있거나, 임무를 수행하러 가는 길이거나.",
  ui_story_5029_50290023_64_dialog_content = "난 내가 없다면 백야성이 돌아가지 않을 거라고 생각했어.",
  ui_story_5029_50290023_65_dialog_content = "그렇게 생각할수록 열심히 일했어...",
  ui_story_5029_50290023_66_dialog_content = "한순간도 발길을 멈추지 않았고, 밤의 아름다움을 감상하지도 못했어.",
  ui_story_5029_50290023_67_dialog_content = "그때의 난 아마 절대 상상할 수 없었을 거야. 몇 년 뒤 어느 날...",
  ui_story_5029_50290023_68_dialog_content = "내가 임무를 훌륭하게 마치고, 심지어 이런 곳에서 여유롭게\n풍경을 감상할 거라고 말이야.",
  ui_story_5029_50290023_69_dialog_content = "하하하, 그렇겠네.\n예전의 카렌이었다면 분명히 이런 날이 올 줄은 생각도 못 했을걸.",
  ui_story_5029_50290023_70_dialog_content = "이런 순간 곁에 아이테르 한 명이 곁에 있을 거라는 것도 분명히 몰랐겠지.",
  ui_story_5029_50290023_71_dialog_content = "그렇게 말하니까 왠지 내가 널 나쁜 쪽으로 이끈 것 같잖아...",
  ui_story_5029_50290023_72_dialog_content = "하지만 널 만나서 정말 기뻐.",
  ui_story_5029_50290023_73_dialog_content = "이 말은 너한테 주는 내 답이라고 해 둘게.",
  ui_story_5029_50290023_74_dialog_content = "어? 무, 무슨 답?",
  ui_story_5029_50290023_75_dialog_content = "방금 나한테 계속 장황하게 마음이 아프다던 건 다른 아이테르였어?",
  ui_story_5029_50290023_76_dialog_content = "난...",
  ui_story_5029_50290023_77_dialog_content = "봐, 저건 서커스단 아냐?",
  ui_story_5029_50290023_78_dialog_content = "그리고 저기, 우리가 오늘 조사하러 갔던 고급 호텔이지?",
  ui_story_5029_50290023_79_dialog_content = "(지금 이 순간, 카렌은 모든 경계심을 내려놓은 것만 같았다.)",
  ui_story_5029_50290023_80_dialog_content = "(이렇게 즐겁게 웃고 떠드는 카렌의 모습은 지금까지\n한 번도 본 적이 없었다...)",
  ui_story_5029_50290023_81_dialog_content = "(어쩌면 그녀의 이런 어린아이 같은 일면은 비밀로 남을지도 모른다.)",
  ui_story_5029_50290023_82_dialog_content = "(우리 두 사람만의 비밀 말이다.)",
  ui_story_5029_50290023_83_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290023_84_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290023_85_dialog_content = "제 얼굴을 보고 실망하셨습니까?",
  ui_story_5029_50290023_86_dialog_content = "죄송합니다. 무심코 두 분만의 비밀을 보고 말았군요.",
  ui_story_5029_50290023_87_dialog_content = "이런, 하지만 그렇게 실망할 필요는 없습니다.",
  ui_story_5029_50290023_88_dialog_content = "꿈은 현실의 바탕이 있어야만 만들어질 수 있는 것이니까요.",
  ui_story_5029_50290023_89_dialog_content = "다시 말해서 당신과 그녀는 현실에서도 같은 일을\n겪을 가능성이 있습니다.",
  ui_story_5029_50290023_90_dialog_content = "다만 꿈의 세계와 다른 점이라면,\n현실에는 이런 트릭은 결코 없을 것입니다.",
  ui_story_5029_50290023_91_dialog_content = "제가 만들어낸 이 허구 속에서만 살아간다는 것은...\n역시 조금은 어려운 일이겠지요.",
  ui_story_5029_50290023_92_dialog_content = "그나저나 스스로 쓰신 이 결말에는 만족하셨는지요.",
  ui_story_5029_50290023_93_dialog_content = "아쉬운 점은 없으셨나요?",
  ui_story_5029_50290023_94_dialog_content = "제가 말씀드리고 싶은 건... 우리에겐 아직 시간이 있다는 것입니다.",
  ui_story_5029_50290023_95_dialog_content = "당신이 아직 꿈속 수수께끼의 답을 찾고 싶어 한다는\n전제가 붙겠지만 말입니다.",
  ui_story_5029_50290024_1_dialog_content = "찾았어!",
  ui_story_5029_50290024_2_dialog_content = "저기 풀숲에 숨어 있어...",
  ui_story_5029_50290024_3_dialog_content = "어?",
  ui_story_5029_50290024_4_dialog_content = "잘 봐, 옷자락이 보여! 내가 가서 잡아 올게.",
  ui_story_5029_50290024_5_dialog_content = "잠깐만...",
  ui_story_5029_50290024_6_dialog_content = "이번엔 절대로 놓치지 않겠어.",
  ui_story_5029_50290024_7_dialog_content = "타깃 추적!",
  ui_story_5029_50290024_8_dialog_content = "<color=#828282>콰르릉!</color>",
  ui_story_5029_50290024_9_dialog_content = "아...",
  ui_story_5029_50290024_10_dialog_content = "바이스!!!",
  ui_story_5029_50290024_11_dialog_content = "PlayerName, 미안해...",
  ui_story_5029_50290024_12_dialog_content = "휴... 갑자기 뭐가 미안한데?",
  ui_story_5029_50290024_13_dialog_content = "계속 생각하고 있었어. 난 가끔 정말 충동적인 것 같아.\n항상 임무를 완수하려고 속전속결만 생각하니까...",
  ui_story_5029_50290024_14_dialog_content = "그래서 가까운 위험을 깨닫지 못하는 경우도 많아.",
  ui_story_5029_50290024_15_dialog_content = "지금도... 그랬고.",
  ui_story_5029_50290024_16_dialog_content = "범인과 마주치자 난 아무 생각도 없이 널 데리고\n이 벌판까지 쫓아와 버렸어.",
  ui_story_5029_50290024_17_dialog_content = "결국 범인의 함정에 빠지기까지 했고 말이야.",
  ui_story_5029_50290024_18_dialog_content = "발목을 삐어서 걸을 수 없는 것도 모자라서...\n너한테 업혀서 힘들게 만들어 버렸어.",
  ui_story_5029_50290024_19_dialog_content = "그러니까... 미안해!",
  ui_story_5029_50290024_20_dialog_content = "휴우... 바이스, 그런 말 안 해도 돼.",
  ui_story_5029_50290024_21_dialog_content = "범인을 쫓은 건 우리 둘이서 결정한 거잖아. 네 탓이 아니야.",
  ui_story_5029_50290024_22_dialog_content = "그리고 아까는 내가 앞서서 가고 있었고,\n내가 널 함정 근처로 데려간 거잖아...",
  ui_story_5029_50290024_23_dialog_content = "굳이 따진다면 사과해야 할 사람은 나야.",
  ui_story_5029_50290024_24_dialog_content = "PlayerName, 그런 식으로 위로 안 해도 돼.",
  ui_story_5029_50290024_25_dialog_content = "오늘 범인을 잡지 못한 건 내 탓이니까.",
  ui_story_5029_50290024_26_dialog_content = "기억해?",
  ui_story_5029_50290024_27_dialog_content = "그때 네가 멋모르고 스카이워커에 구멍을 뚫지 않았으면...",
  ui_story_5029_50290024_28_dialog_content = "난 너와 만날 일도 없었을 거고, 지하에서 나오지도 못했을 거야.",
  ui_story_5029_50290024_29_dialog_content = "그건 다른 얘기잖아.",
  ui_story_5029_50290024_30_dialog_content = "난 그때 정말로 확실하게 조사하고...",
  ui_story_5029_50290024_31_dialog_content = "아니, 잠깐만.\n너 그럼 지금까지 계속 내가 그때 「멋모르고」 그런 줄 알았어?",
  ui_story_5029_50290024_32_dialog_content = "아니었어? 하하하...",
  ui_story_5029_50290024_33_dialog_content = "너... 그럼 속으로 계속 날 놀리고 있었던 거야?",
  ui_story_5029_50290024_34_dialog_content = "야, 야, 살살 쳐.",
  ui_story_5029_50290024_35_dialog_content = "앗, 미안해. 아팠어?",
  ui_story_5029_50290024_36_dialog_content = "아프진 않아. 근데 힘들어서 더는... 업고 못 걷겠어.",
  ui_story_5029_50290024_37_dialog_content = "저쪽에 잔디밭이 있으니까 저기 내려줘!",
  ui_story_5029_50290024_38_dialog_content = "응, 또 다리 안 다치게 조심하고.",
  ui_story_5029_50290024_39_dialog_content = "휴우... 하루 종일 힘들었는데 드디어 누웠네.",
  ui_story_5029_50290024_40_dialog_content = "내가 너무 무거웠어?",
  ui_story_5029_50290024_41_dialog_content = "하나도 안 무거웠어. 그저...",
  ui_story_5029_50290024_42_dialog_content = "그저...?",
  ui_story_5029_50290024_43_dialog_content = "돌아오는 길이 꽤 멀었네.",
  ui_story_5029_50290024_44_dialog_content = "...또 나 놀리려는 줄 알았잖아.",
  ui_story_5029_50290024_45_dialog_content = "바이스.",
  ui_story_5029_50290024_46_dialog_content = "응?",
  ui_story_5029_50290024_47_dialog_content = "난 절대로 널 놀리지 않을 거야.",
  ui_story_5029_50290024_48_dialog_content = "......",
  ui_story_5029_50290024_49_dialog_content = "넌 나를 지하에서 꺼내준 사람이고,\n내가 앞으로 나아가도록 격려해 준 사람이야.",
  ui_story_5029_50290024_50_dialog_content = "네가 없었으면 난 저렇게 많은 사람들을 알지도 못했을 거고,\n그렇게 많은 곳들을 볼 수도 없었을 거야.",
  ui_story_5029_50290024_51_dialog_content = "에이, 에이, 알고 있어.",
  ui_story_5029_50290024_52_dialog_content = "그 얘긴 벌써 몇 번이나 했잖아. 뭘 또 꺼내고 그래.",
  ui_story_5029_50290024_53_dialog_content = "다른 사람들은 오늘 네가 이렇게 열심히 조사를 하는 게\n전부 거액의 현상금을 노리는 거라고 생각할지도 모르지만...",
  ui_story_5029_50290024_54_dialog_content = "다들 잊고 있는 거야. 네가 일루미나의 일원이라는 걸.\n현상금 같은 건 너한테는 아무 의미도 없잖아.",
  ui_story_5029_50290024_55_dialog_content = "네가 현상금을 원하는 건 전부 콜로서스의 유지비를 위해서잖아.",
  ui_story_5029_50290024_56_dialog_content = "헤헤, 알아챘구나... 괜찮아, 우린 동료잖아!",
  ui_story_5029_50290024_57_dialog_content = "이것도 모두 내가 해야 할 일인걸.",
  ui_story_5029_50290024_58_dialog_content = "아까 널 업으면서 나도 많은 생각을 했어.",
  ui_story_5029_50290024_59_dialog_content = "지금까지 넌 항상 곁에서 날 위로해 주고, 격려해 줬어.\n그리고 덕분에 난 동료한테 의지하는 법을 배웠어.",
  ui_story_5029_50290024_60_dialog_content = "근데 내가 지금까지 생각하지 못했던 게 있었어...",
  ui_story_5029_50290024_61_dialog_content = "바이스, 항상 그렇게 강한 모습만 보이려고 안 해도 돼.",
  ui_story_5029_50290024_62_dialog_content = "응?",
  ui_story_5029_50290024_63_dialog_content = "너도 오늘처럼...",
  ui_story_5029_50290024_64_dialog_content = "가끔은 네 동료, 나한테 의지해도 되잖아!",
  ui_story_5029_50290024_65_dialog_content = "PlayerName...",
  ui_story_5029_50290024_66_option_content = "언제나 항상 고마워!",
  ui_story_5029_50290024_67_dialog_content = "네가 그렇게 말한다면...",
  ui_story_5029_50290024_68_dialog_content = "사양하지 않을게!",
  ui_story_5029_50290024_69_dialog_content = "그럼... 앞으로도 잘 부탁해!",
  ui_story_5029_50290024_70_dialog_content = "나도 마찬가지야. 잘 부탁해~",
  ui_story_5029_50290024_71_dialog_content = "정말 좋네.",
  ui_story_5029_50290024_72_dialog_content = "응? 뭐가 좋은데?",
  ui_story_5029_50290024_73_dialog_content = "여기서 보는 석양, 정말 멋져.",
  ui_story_5029_50290024_74_dialog_content = "다리만 안 다쳤으면 더 좋았을 텐데.",
  ui_story_5029_50290024_75_option_content = "음... 괜찮아?",
  ui_story_5029_50290024_76_dialog_content = "괜찮아...",
  ui_story_5029_50290024_77_dialog_content = "그냥 오늘 있었던 일들을 다시 생각해 보고 있었어.",
  ui_story_5029_50290024_78_dialog_content = "서재에서 조사할 때나...",
  ui_story_5029_50290024_79_dialog_content = "극장에서 연극 보던 때나...",
  ui_story_5029_50290024_80_dialog_content = "내가 다친 뒤로 네가 계속 바쁘게 움직이는 것까지.",
  ui_story_5029_50290024_81_dialog_content = "지금까진 전혀 의식하질 못했어.\n네가 이렇게 남을 잘 보살피는 사람이었는지 말이야.",
  ui_story_5029_50290024_82_dialog_content = "넌 정말 믿을 수 있는 동료인 것 같아.",
  ui_story_5029_50290024_83_dialog_content = "그거야 당연하지!",
  ui_story_5029_50290024_84_dialog_content = "그리고... 지금 이 순간도 소중하게 간직하고 싶어.",
  ui_story_5029_50290024_85_dialog_content = "<color=#828282>휘이잉──</color>",
  ui_story_5029_50290024_86_dialog_content = "상쾌한 바람이 잔디 사이를 지나 내 머리카락을 스쳐 가는 순간.",
  ui_story_5029_50290024_87_dialog_content = "석양빛이 구름에 그림을 그리는 순간.",
  ui_story_5029_50290024_88_dialog_content = "우리 둘이서 이렇게 조용히, 멍하니 보내는 순간.",
  ui_story_5029_50290024_89_dialog_content = "이런 시간이 계속 이어졌으면 좋겠다는 생각까지 들어.",
  ui_story_5029_50290024_90_dialog_content = "그거 뭔가 멋지네. 근데...",
  ui_story_5029_50290024_91_dialog_content = "너 계속 다리 아픈 채로 나한테 업히고 싶은 건 아니지?",
  ui_story_5029_50290024_92_dialog_content = "에이, 아까 괜히 칭찬했네.",
  ui_story_5029_50290024_93_dialog_content = "넌 여전히 여자애랑 이야기하는 법을 모르는구나...",
  ui_story_5029_50290024_94_dialog_content = "그냥 석양이나 볼래.",
  ui_story_5029_50290024_95_dialog_content = "크흠... 농담이야.",
  ui_story_5029_50290024_96_dialog_content = "그럼 이렇게 하자.",
  ui_story_5029_50290024_97_dialog_content = "다리가 나으면 우리 다시 여기 와서 석양을 보자.",
  ui_story_5029_50290024_98_dialog_content = "약속이야. 무르기 없어.",
  ui_story_5029_50290024_99_dialog_content = "약속 어기면 콜로서스 한 달 청소!",
  ui_story_5029_50290024_100_dialog_content = "아하하, 안 어길 거야...",
  ui_story_5029_50290024_101_dialog_content = "(바이스는 비록 다쳤지만, 평소보다 훨씬 마음이 편하고 즐거워 보인다.)",
  ui_story_5029_50290024_102_dialog_content = "(바람이 차가워졌다. 코로 들어온 공기가 가슴에 전해진다.)",
  ui_story_5029_50290024_103_dialog_content = "(마치 온 세계가 나와 아득히 멀어진 것처럼,\n지금 이 순간 들리는 것은 내 심장 소리뿐.)",
  ui_story_5029_50290024_104_dialog_content = "(나, 왠지 기대하게 된 것 같다...)",
  ui_story_5029_50290024_105_dialog_content = "(우리 두 사람만의 비밀 약속을...)",
  ui_story_5029_50290024_106_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290024_107_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290024_108_dialog_content = "제 얼굴을 보고 실망하셨습니까?",
  ui_story_5029_50290024_109_dialog_content = "죄송합니다. 무심코 두 분만의 비밀을 보고 말았군요.",
  ui_story_5029_50290024_110_dialog_content = "이런, 하지만 그렇게 실망할 필요는 없습니다.",
  ui_story_5029_50290024_111_dialog_content = "꿈은 현실의 바탕이 있어야만 만들어질 수 있는 것이니까요.",
  ui_story_5029_50290024_112_dialog_content = "다시 말해서 당신과 그녀는 현실에서도 같은 일을\n겪을 가능성이 있습니다.",
  ui_story_5029_50290024_113_dialog_content = "다만 꿈의 세계와 다른 점이라면,\n현실에는 이런 트릭은 결코 없을 것입니다.",
  ui_story_5029_50290024_114_dialog_content = "제가 만들어낸 이 허구 속에서만 살아간다는 것은...\n역시 조금은 어려운 일이겠지요.",
  ui_story_5029_50290024_115_dialog_content = "그나저나 스스로 쓰신 이 결말에는 만족하셨는지요.",
  ui_story_5029_50290024_116_dialog_content = "아쉬운 점은 없으셨나요?",
  ui_story_5029_50290024_117_dialog_content = "제가 말씀드리고 싶은 건... 우리에겐 아직 시간이 있다는 것입니다.",
  ui_story_5029_50290024_118_dialog_content = "당신이 아직 꿈속 수수께끼의 답을 찾고 싶어 한다는\n전제가 붙겠지만 말입니다.",
  ui_story_5029_50290025_1_dialog_content = "PlayerName, 방금 너무 멋있었던 거 아냐?",
  ui_story_5029_50290025_2_dialog_content = "그 군인 아저씨, 처음에는 엄청 사나웠는데,\n네가 몇 마디 하니까 바로 쫄았잖아!",
  ui_story_5029_50290025_3_dialog_content = "아하하, 애초부터 고작 피아의 신호탄이 잘못 맞았을 뿐이었잖아.",
  ui_story_5029_50290025_4_dialog_content = "전혀 다치지도 않았는데 어떻게든 트집을 잡아서\n끌고 가려고 하고 말이야, 흥!",
  ui_story_5029_50290025_5_dialog_content = "다쳤나 안 다쳤나보다 남의 옷에 흔적을 남긴 건 우리가 잘못한 게 맞아.",
  ui_story_5029_50290025_6_dialog_content = "아까 네 사과도 너무 건성이었어.",
  ui_story_5029_50290025_7_dialog_content = "범인을 잡고 나면 그 사람한테 다시 사과하러 가자.",
  ui_story_5029_50290025_8_dialog_content = "그건 범인부터 잡고 나서 생각할래.",
  ui_story_5029_50290025_9_dialog_content = "그래서 범인이 있는 곳은 느껴져?",
  ui_story_5029_50290025_10_dialog_content = "...아니, 여긴 사람이 너무 많아.",
  ui_story_5029_50290025_11_dialog_content = "그것도 그렇네. 항구엔 온통 축제 보러 온 사람들이잖아.",
  ui_story_5029_50290025_12_dialog_content = "범인은 그걸 노리고 여기로 도망친 거겠지.",
  ui_story_5029_50290025_13_dialog_content = "아무튼 다시 시도해 볼게!",
  ui_story_5029_50290025_14_dialog_content = "응, 피아도 가만히 못 있겠어. 사람 사이에서 찾아볼게.",
  ui_story_5029_50290025_15_dialog_content = "키아로, 가자!",
  ui_story_5029_50290025_16_dialog_content = "어? 키아로?",
  ui_story_5029_50290025_17_dialog_content = "루... 냠냠.",
  ui_story_5029_50290025_18_dialog_content = "키아로, 뭐 먹는 거야?",
  ui_story_5029_50290025_19_dialog_content = "냠냠.",
  ui_story_5029_50290025_20_dialog_content = "으으... 기분 나빠.",
  ui_story_5029_50290025_21_dialog_content = "키아로, 그런 거 먹으면 안 돼. 독이라도 있으면 어떡해?",
  ui_story_5029_50290025_22_dialog_content = "하하, 너 정말 아무것도 모르는구나.",
  ui_story_5029_50290025_23_dialog_content = "이건 해초맛 아이스크림이야.\n생긴 건 좀 그렇지만 먹고 나면 갈증도 없어지고 시원해져!",
  ui_story_5029_50290025_24_dialog_content = "나, 나도 알고 있었어!",
  ui_story_5029_50290025_25_dialog_content = "앗, 내 아이스크림 어디 갔지?",
  ui_story_5029_50290025_26_dialog_content = "뭐야, 네 강아지가 내 아이스크림을 먹고 있던 거야?!",
  ui_story_5029_50290025_27_dialog_content = "그거 내가 용돈을 한참 모아서 산 아이스크림이란 말이야! 물어내!",
  ui_story_5029_50290025_28_dialog_content = "앗, 키아로가 네 걸 먹은 거야? 미안...",
  ui_story_5029_50290025_X28_dialog_content = "미안하다고 하면 다야? 아이스크림 5개 값으로 돌려주면 용서해 줄게.",
  ui_story_5029_50290025_X29_dialog_content = "근데 난 이제 돈이 없는데...",
  ui_story_5029_50290025_X30_dialog_content = "돈이 없으면 그 강아지를 팔면 되잖아?",
  ui_story_5029_50290025_X31_dialog_content = "내가 나중에 갚을게... 근데 키아로는 안 팔아.\n그리고 키아로는 강아지가 아니라구.",
  ui_story_5029_50290025_29_dialog_content = "걔가 강아지가 아니면 네가 강아지겠네!",
  ui_story_5029_50290025_30_dialog_content = "나, 나도 아냐...",
  ui_story_5029_50290025_31_dialog_content = "넌 강아지야! 남의 아이스크림을 훔쳐먹는 강아지!",
  ui_story_5029_50290025_32_dialog_content = "피아, 목걸이 줄게.",
  ui_story_5029_50290025_33_dialog_content = "너한테 잘 어울릴 것 같아!",
  ui_story_5029_50290025_34_dialog_content = "정말? 고마워~ 지금 바로 차 볼게!",
  ui_story_5029_50290025_35_dialog_content = "얘들아, 빨리 와 봐! 피아가 개 목걸이를 차고 나왔어!",
  ui_story_5029_50290025_36_dialog_content = "얼레리꼴레리! 피아는 강아지래요!",
  ui_story_5029_50290025_37_dialog_content = "강아지 아냐...",
  ui_story_5029_50290025_38_dialog_content = "피아는 강아지가 아니라고...",
  ui_story_5029_50290025_39_dialog_content = "울어 봤자 소용없거든! 빨리 내 아이스크림 물어내! 이 강아지야!",
  ui_story_5029_50290025_40_dialog_content = "야, 너 애가 왜 그렇게 심하게 구는 거야?",
  ui_story_5029_50290025_41_dialog_content = "흥, 백이 있다고 무서워할 줄 알고?",
  ui_story_5029_50290025_42_dialog_content = "내 아이스크림을 쟤 강아지가 뺏어 먹었어! 내가 피해자야!",
  ui_story_5029_50290025_X42_dialog_content = "그럼 내가 대신 사과할게. 미안해.",
  ui_story_5029_50290025_43_dialog_content = "자, 이거면 아이스크림 10개는 살 수 있지?",
  ui_story_5029_50290025_44_dialog_content = "이 정도면... 될 것 같아.",
  ui_story_5029_50290025_45_dialog_content = "아직 가지 마. 내 말 아직 안 끝났어.",
  ui_story_5029_50290025_46_dialog_content = "너도 피아가 일부러 그런 게 아니라는 걸 알면서,\n왜 아까 그렇게 괴롭힌 거야?",
  ui_story_5029_50290025_47_dialog_content = "여자애를 괴롭히고 울리기까지 하고, 그래서야 되겠어?",
  ui_story_5029_50290025_48_dialog_content = "......",
  ui_story_5029_50290025_49_dialog_content = "다음에 또 남을 괴롭히는 게 보이면, 오늘처럼 그냥 안 넘어갈 줄 알아!",
  ui_story_5029_50290025_50_dialog_content = "알았어?",
  ui_story_5029_50290025_51_dialog_content = "알았어...",
  ui_story_5029_50290025_52_dialog_content = "그럼 다시는 안 그러겠다고 약속해.",
  ui_story_5029_50290025_53_dialog_content = "다시는 안 그럴게...",
  ui_story_5029_50290025_54_dialog_content = "자, 피아. 이제 괜찮아.",
  ui_story_5029_50290025_55_dialog_content = "평소에는 겁도 없으면서,\n남자애한테 말 한두 마디 들었다고 대꾸도 못 하게 된 거야?",
  ui_story_5029_50290025_56_dialog_content = "너희 사부가 이걸 봤으면...",
  ui_story_5029_50290025_57_dialog_content = "흐아앙...!",
  ui_story_5029_50290025_58_dialog_content = "PlayerName! 왜 이렇게 늦게 왔어?!",
  ui_story_5029_50290025_59_dialog_content = "어?",
  ui_story_5029_50290025_60_dialog_content = "아... 미안, 미안, 내가 좀 늦었지?",
  ui_story_5029_50290025_61_dialog_content = "훌쩍... 키아로는 강아지 아냐. 피아도 강아지 아냐...",
  ui_story_5029_50290025_62_dialog_content = "키아로는 일부러 그런 게 아냐...\n그러게 누가 아이스크림을 아무 데나 두래... 흐아앙!",
  ui_story_5029_50290025_X62_dialog_content = "그리고 피아도 제대로 사과했어...",
  ui_story_5029_50290025_63_dialog_content = "알아, 괜찮아. 이제 다 끝났잖아.",
  ui_story_5029_50290025_64_dialog_content = "흐아아앙! 피아는 억지 부리는 어린애가 제일 싫어!",
  ui_story_5029_50290025_65_dialog_content = "너도 어린애면서...",
  ui_story_5029_50290025_66_dialog_content = "피아는 어린애 아냐, 진작에 다 컸다구.",
  ui_story_5029_50290025_67_dialog_content = "그, 그리고...",
  ui_story_5029_50290025_68_dialog_content = "피아는 다른 어린애들을 괴롭히거나 놀리지도 않는다구! 흐아앙...",
  ui_story_5029_50290025_69_dialog_content = "하하하, 나도 알아.\n대신 피아가 가끔 「큰 애들」을 괴롭히는 건 사실이잖아.",
  ui_story_5029_50290025_70_dialog_content = "아니거든!",
  ui_story_5029_50290025_71_dialog_content = "루!",
  ui_story_5029_50290025_72_dialog_content = "봐, 키아로도 걱정하고 있어.",
  ui_story_5029_50290025_73_dialog_content = "어디 좀 앉아서 얘기할까?",
  ui_story_5029_50290025_74_dialog_content = "알았어...",
  ui_story_5029_50290025_75_dialog_content = "만약... 어디까지나 만약이지만...\n혹시 피아가 정말로 널 화나게 한 적이 있다면...",
  ui_story_5029_50290025_76_dialog_content = "피아가 사과할게...",
  ui_story_5029_50290025_77_option_content = "괜찮아!",
  ui_story_5029_50290025_78_dialog_content = "피아가 착한 아이라는 건 항상 알고 있었어.",
  ui_story_5029_50290025_79_dialog_content = "말은 험하게 해도 실제로 하는 일은 언제나 사람들을 돕는 일이었고,\n항상 모두를 생각하고 있잖아.",
  ui_story_5029_50290025_80_dialog_content = "이번에도 현상금을 노린 건 너희 사부한테 선물을 사 주려고 그런 거잖아.",
  ui_story_5029_50290025_81_dialog_content = "선물은 그냥 겸사겸사 사는 거라구.",
  ui_story_5029_50290025_82_dialog_content = "사부가 경비를 적게 주지만 않았어도 피아랑 키아로가\n이렇게 고생하진 않았을 거야!",
  ui_story_5029_50290025_83_dialog_content = "길에서 어린애한테 욕먹고 울지도 않았을 거라구...",
  ui_story_5029_50290025_84_dialog_content = "아 참, PlayerName, 나한테 약속해!",
  ui_story_5029_50290025_85_option_content = "갑자기 왜 그러는데?",
  ui_story_5029_50290025_86_dialog_content = "사실... 피아는 어렸을 때 또래 친구들이랑 정말 놀고 싶었어.",
  ui_story_5029_50290025_87_dialog_content = "근데 주변 애들은 항상 피아가 괴롭히기 쉽다고 생각해서...\n결국 어느새 난 모두의 웃음거리가 되어 있었어.",
  ui_story_5029_50290025_88_dialog_content = "그때 피아는 든든한 오빠가 있었으면 정말 좋겠다고 생각했어.",
  ui_story_5029_50290025_89_dialog_content = "그래서 피아를 괴롭히는 녀석들을 혼내주는 거야.",
  ui_story_5029_50290025_90_dialog_content = "그리고 나도 언젠가는 그 애들이 부러워할 그런 사람이\n되고 싶다고 생각했어.",
  ui_story_5029_50290025_91_dialog_content = "그치만...",
  ui_story_5029_50290025_92_dialog_content = "피아는 집에 숨어있을 수밖에 없었어.",
  ui_story_5029_50290025_93_dialog_content = "그 애들이랑 마주칠 때마다 피아는 항상 아무렇지 않은\n척할 수밖에 없었어.",
  ui_story_5029_50290025_94_dialog_content = "그치만 그럴수록 그 애들의 괴롭힘은 더 심해졌어.\n그, 그래서 피아는 너무 힘들었어...",
  ui_story_5029_50290025_95_dialog_content = "근데 아까 그 남자애가 그러니까 옛날 생각이 났던 거야.",
  ui_story_5029_50290025_96_dialog_content = "그 순간엔 정말 어디에도 의지할 수 없던 어린 시절로 돌아간 것만 같았어.",
  ui_story_5029_50290025_97_dialog_content = "근데 오늘은 달랐어. 오늘은 피아를 구해주고,\n나쁜 애를 혼내주는 사람이 나타났던 거야!",
  ui_story_5029_50290025_98_dialog_content = "PlayerName, 그게 바로 너야...",
  ui_story_5029_50290025_99_dialog_content = "그래서 그런 생각이 들었어...\n만약 PlayerName 네가 정말로 피아의 오빠였으면 얼마나 좋을까...",
  ui_story_5029_50290025_100_dialog_content = "어렸을 때부터 PlayerName 네가 옆에서 피아를 지켜줬으면\n좋았을 것 같다고 말이야...",
  ui_story_5029_50290025_101_dialog_content = "괜찮아. 난 너보다 나이도 많으니까 애초에 너한텐 오빠잖아.",
  ui_story_5029_50290025_102_dialog_content = "그리고 피아 너도 이제 더는 예전의 그 힘없는 어린애가 아냐.",
  ui_story_5029_50290025_103_dialog_content = "넌 자기 힘으로 훌륭한 환상동물 마스터가 됐잖아.",
  ui_story_5029_50290025_104_dialog_content = "그건 다른 또래들은 좀처럼 할 수 없는 대단한 일이잖아?",
  ui_story_5029_50290025_105_dialog_content = "...그런 건 됐어.",
  ui_story_5029_50290025_106_dialog_content = "아무튼 앞으로도 넌 오늘처럼 피아를 지켜줘! 피아가 괴롭게 만들면 안 돼!",
  ui_story_5029_50290025_107_dialog_content = "알았어, 약속할게.",
  ui_story_5029_50290025_108_dialog_content = "진짜?",
  ui_story_5029_50290025_109_dialog_content = "응, 약속이야!",
  ui_story_5029_50290025_110_dialog_content = "PlayerName... 오, 오빠...",
  ui_story_5029_50290025_111_dialog_content = "그럼 오빠로서의 첫 번째 임무는 바로...",
  ui_story_5029_50290025_112_dialog_content = "피아가 오늘 울었다는 건 다른 사람한테 말하면 안 돼!",
  ui_story_5029_50290025_113_dialog_content = "아니면 피아 또 놀림당할 거야.",
  ui_story_5029_50290025_114_dialog_content = "약속할게. 절대 말 안 할게.",
  ui_story_5029_50290025_115_dialog_content = "휴~ 힘들었어...",
  ui_story_5029_50290025_116_dialog_content = "당연하지. 우는 것도 체력이 필요하니까.",
  ui_story_5029_50290025_117_dialog_content = "근데... 결국...",
  ui_story_5029_50290025_118_dialog_content = "범인은... 못 잡았네.",
  ui_story_5029_50290025_119_dialog_content = "괜찮아, 적어도 은 상자는 찾았으니까.",
  ui_story_5029_50290025_120_dialog_content = "휴... 휴우...",
  ui_story_5029_50290025_121_dialog_content = "얘 좀 봐. 앉자마자 잠든 거야?",
  ui_story_5029_50290025_122_dialog_content = "(시끌벅적한 인파를 앞에 두고, 피아는 기분 좋게 자고 있었다.)",
  ui_story_5029_50290025_123_dialog_content = "(눈물에 젖은 옷자락도 석양 아래 천천히 말라간다.)",
  ui_story_5029_50290025_124_dialog_content = "(만약 나한테 여동생이 있었다면, 아마 피아 정도의 나이였을까?)",
  ui_story_5029_50290025_125_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290025_126_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290025_127_dialog_content = "제 얼굴을 보고 실망하셨습니까?",
  ui_story_5029_50290025_128_dialog_content = "죄송합니다. 무심코 두 분만의 비밀을 보고 말았군요.",
  ui_story_5029_50290025_129_dialog_content = "이런, 하지만 그렇게 실망할 필요는 없습니다.",
  ui_story_5029_50290025_130_dialog_content = "꿈은 현실의 바탕이 있어야만 만들어질 수 있는 것이니까요.",
  ui_story_5029_50290025_131_dialog_content = "다시 말해서 당신과 그녀는 현실에서도 같은 일을\n겪을 가능성이 있습니다.",
  ui_story_5029_50290025_132_dialog_content = "다만 꿈의 세계와 다른 점이라면,\n현실에는 이런 트릭은 결코 없을 것입니다.",
  ui_story_5029_50290025_133_dialog_content = "제가 만들어낸 이 허구 속에서만 살아간다는 것은...\n역시 조금은 어려운 일이겠지요.",
  ui_story_5029_50290025_134_dialog_content = "그나저나 스스로 쓰신 이 결말에는 만족하셨는지요.",
  ui_story_5029_50290025_135_dialog_content = "아쉬운 점은 없으셨나요?",
  ui_story_5029_50290025_136_dialog_content = "제가 말씀드리고 싶은 건... 우리에겐 아직 시간이 있다는 것입니다.",
  ui_story_5029_50290025_137_dialog_content = "당신이 아직 꿈속 수수께끼의 답을 찾고 싶어 한다는\n전제가 붙겠지만 말입니다.",
  ui_story_5029_50290026_1_dialog_content = "(으음...)",
  ui_story_5029_50290026_2_dialog_content = "(여긴... 영주님의 서재잖아.)",
  ui_story_5029_50290026_3_dialog_content = "(왜 또 돌아와 버린 거야?)",
  ui_story_5029_50290026_4_dialog_content = "(어라, 내가 지금 왜 「또」라고 말한 거지?)",
  ui_story_5029_50290026_5_dialog_content = "이제 여러분께선 자유롭게 저택 안을 조사하셔도 됩니다.",
  ui_story_5029_50290026_6_dialog_content = "무슨 일이 있으시면 저는 홀에 있을 테니 언제든지 말씀하세요.",
  ui_story_5029_50290026_7_dialog_content = "(이 말... 왠지 몇 번이나 들은 것 같아...)",
  ui_story_5029_50290026_8_option_content = "(젠에게 말을 건다)",
  ui_story_5029_50290026_9_option_content = "(적당히 둘러본다)",
  ui_story_5029_50290026_10_dialog_content = "(아니야!)",
  ui_story_5029_50290026_11_dialog_content = "(지금은 그런 선택을 하고 있을 때가 아니야.)",
  ui_story_5029_50290026_12_dialog_content = "(이대로 계속 간다면 우린 진범을 결코 찾을 수 없어.)",
  ui_story_5029_50290026_13_dialog_content = "(범인을 찾지 못하면 영주님이 위험해질 수도 있고...\n나도 영원히 여기 갇힐지도 몰라.)",
  ui_story_5029_50290026_14_dialog_content = "(음? 「갇힌다」니? 내가 지금 무슨 소릴 하는 거지? 아무튼...)",
  ui_story_5029_50290026_15_option_content = "다들 빨리 와 봐!",
  ui_story_5029_50290026_16_option_content = "카렌, 바이스, 피아!",
  ui_story_5029_50290026_17_dialog_content = "PlayerName, 왜 그래? 갑자기 소리는 왜 질러?",
  ui_story_5029_50290026_18_dialog_content = "뭔가 단서를 찾은 거야?",
  ui_story_5029_50290026_19_dialog_content = "할 말 있으면 빨리 해! 난 지금 곧 중요한 단서를 찾을 것 같단 말이야.",
  ui_story_5029_50290026_20_dialog_content = "이 사건은 게임도 아니고, 시합도 아냐.",
  ui_story_5029_50290026_21_dialog_content = "난 우리가 모두 힘을 합쳐서 조사했으면 좋겠어!",
  ui_story_5029_50290026_22_dialog_content = "왜? 그럼 현상금도 나눠야 되잖아.",
  ui_story_5029_50290026_23_dialog_content = "PlayerName, 혹시 탐정 파트너가 없어서 곤란하면 언제든지 나한테 와.",
  ui_story_5029_50290026_24_dialog_content = "너라면 받아줄 테니까.",
  ui_story_5029_50290026_25_dialog_content = "다들 내 말 잘 들어. 이제 진짜로 시간이 없어...",
  ui_story_5029_50290026_26_dialog_content = "우리가 힘을 합쳐서 범인을 찾아내지 못한다면 더 큰 일이 벌어질 거야.",
  ui_story_5029_50290026_27_dialog_content = "그건 말하지 않아도 알고 있어.",
  ui_story_5029_50290026_28_dialog_content = "다들 날 믿어줘. 이건 내 예감이야.",
  ui_story_5029_50290026_29_dialog_content = "이제 곧 범인이 은 상자를 들고 도망칠 거야.\n한두 사람의 힘으로는 잡을 수 없어.",
  ui_story_5029_50290026_30_dialog_content = "범인이 도망치기 전에 범인이 누군지를 알아내고,\n우리가 먼저 행동해야 해!",
  ui_story_5029_50290026_31_dialog_content = "근데... 우리가 왜 네 예감을 믿어야 되는데?",
  ui_story_5029_50290026_32_dialog_content = "피아, 카페 구석의 바닥에 키아로가 못 가게 해.",
  ui_story_5029_50290026_33_dialog_content = "거긴 딸기잼이 묻은 칼이 떨어져 있어. 조심하지 않으면 다칠 거야.",
  ui_story_5029_50290026_34_dialog_content = "지, 진짜?",
  ui_story_5029_50290026_35_dialog_content = "카렌, 2층 책상엔 해진 고서가 있어.",
  ui_story_5029_50290026_36_dialog_content = "책을 건드리면 망가질지도 몰라. 그럼 영주님한테 해명하기 곤란할 거야.",
  ui_story_5029_50290026_37_dialog_content = "음?",
  ui_story_5029_50290026_38_dialog_content = "바이스, 네가 예쁘다고 생각한 저 홀에 있는 꽃은 독이 있어.\n가까이 가지 않는 게 좋을 거야.",
  ui_story_5029_50290026_39_dialog_content = "대신 먹지만 않으면 큰 문제가 생기진 않을 거야.",
  ui_story_5029_50290026_40_dialog_content = "어? 내가 그 꽃을 보러 가려던 걸 어떻게 안 거야?",
  ui_story_5029_50290026_41_dialog_content = "그러니까... 그런 예감이 들었다는 얘기야.",
  ui_story_5029_50290026_42_dialog_content = "너, 우리가 모르는 사이에 이 저택을 다 뒤진 거 아냐?",
  ui_story_5029_50290026_43_dialog_content = "그...그럴지도 모르지.",
  ui_story_5029_50290026_44_dialog_content = "그렇다면 넌 벌써 완벽한 협력 방법도 생각해 뒀겠지?",
  ui_story_5029_50290026_45_dialog_content = "완벽하다고 할 순 없겠지만, 너희가 내 말대로 움직여준다면...",
  ui_story_5029_50290026_46_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5029_50290026_47_dialog_content = "정말 PlayerName 네가 말한 대로였어.\n영주와 협상하러 온 상인은 역시 조무였어.",
  ui_story_5029_50290026_48_dialog_content = "그래서 PlayerName 네가 시킨 대로 영주와의 접견을\n주선해 주겠다고 그자한테 약속했어.",
  ui_story_5029_50290026_49_dialog_content = "그랬더니 그자도 처음부터 끝까지 전부 이야기해 줬어!",
  ui_story_5029_50290026_50_dialog_content = "전 영주님이 문을 잠그고 떠나신 뒤에 몰래 문을 따고 들어갔죠.",
  ui_story_5029_50290026_51_dialog_content = "이건 다른 얘기인데,\n제 문 따는 기술은 레디젤 렌치 중에서도 일류거든요.",
  ui_story_5029_50290026_52_dialog_content = "그리고 《아카나미 사메노스케 전기》 몇 권을\n눈에 잘 보이는 곳에 두고 나왔어요.",
  ui_story_5029_50290026_53_dialog_content = "응, 그리고 다음은 백야성 공작 베벌리 씨였어.",
  ui_story_5029_50290026_54_dialog_content = "한참을 기다렸더니, 초록머리의 키 작은 남자가 저택에서 나왔어.",
  ui_story_5029_50290026_55_dialog_content = "난 주변에 사람이 없는 걸 확인하고,\n안으로 들어가서 잃어버린 휘장을 찾아봤어.",
  ui_story_5029_50290026_56_dialog_content = "그런데 한참을 찾았지만 찾을 수 없었지.\n그 뒤엔 누가 온 것 같은 소리가 나서 자리를 떠났어.",
  ui_story_5029_50290026_57_dialog_content = "그 베벌리 씨가 말한 「누군가」가 「마나에」지?\n음, 너네가 「사나에」라고 부르는 메이드 말이야.\n아무튼 걔가 뭐라고 했냐면...",
  ui_story_5029_50290026_58_dialog_content = "저, 전 문이 안 잠겨 있길래... 슬쩍 안으로 들어갔어요.",
  ui_story_5029_50290026_59_dialog_content = "그리고 소파 밑에 숨긴 꽃병 조각을 치우고 새 꽃병을 놔뒀어요.",
  ui_story_5029_50290026_60_dialog_content = "근데 아무도 모를 줄 알았는데... 쿠크 씨한테 들켜버렸어요...",
  ui_story_5029_50290026_61_dialog_content = "쿠크 씨는 아무한테도 말하지 않겠다고 약속했어요...\n그리고 저한테 문단속을 잘하라고 했어요...",
  ui_story_5029_50290026_62_dialog_content = "그래서 영주가 돌아왔을 땐 문도 창문도 잘 잠겨 있었던 거겠지...",
  ui_story_5029_50290026_63_dialog_content = "사람들이 서재에 들어간 순서는 확실해.",
  ui_story_5029_50290026_64_dialog_content = "아까 목격자 세 사람한테 확인했어. 그 사람들이 증명해줄 거야.",
  ui_story_5029_50290026_65_dialog_content = "영주님이 문을 잠그고 얼마 뒤에 녹색머리의 남자분이 또 돌아왔어요.",
  ui_story_5029_50290026_66_dialog_content = "확실히 저녁 시간에 아름다운 귀족분을 봤었죠.",
  ui_story_5029_50290026_67_dialog_content = "「마나에」가 몰래 영주님의 서재로 들어가는 것을 봤습니다.\n정말 수상하더군요.",
  ui_story_5029_50290026_68_dialog_content = "PlayerName, 오늘 너 예감이 너무 잘 맞는 거 아냐?",
  ui_story_5029_50290026_69_dialog_content = "세 사람의 정체도 맞히고, 목격자까지 찾아냈잖아!",
  ui_story_5029_50290026_70_dialog_content = "여기까진 들을 수 있었지만, 결과적으로 우린 다시 원점으로 돌아왔어.",
  ui_story_5029_50290026_71_dialog_content = "세 사람 모두 몰래 서재에 들어갔지만, 전부 연달아서 들어갔어.",
  ui_story_5029_50290026_72_dialog_content = "그럼 범인은 역시 그 세 사람 안에 있다는 말인데...",
  ui_story_5029_50290026_73_dialog_content = "근데 PlayerName 넌 그 세 사람을 의심하고 싶진 않은 것 같네.",
  ui_story_5029_50290026_74_dialog_content = "휴, 그럼 네 번째는 없는 거야?",
  ui_story_5029_50290026_75_dialog_content = "네 번째...?",
  ui_story_5029_50290026_76_dialog_content = "가능성은 있어.",
  ui_story_5029_50290026_77_dialog_content = "예를 들면 계속 우리 곁에 있었기 때문에,\n우리가 의심하지 않았던 사람이겠지.",
  ui_story_5029_50290026_78_dialog_content = "피아, 어제 키아로가 뭔가 금속으로 된 물건을 몰래 먹진 않았어?",
  ui_story_5029_50290026_79_dialog_content = "루우우?",
  ui_story_5029_50290026_80_dialog_content = "키아로는 그런 바보가 아냐!",
  ui_story_5029_50290026_81_dialog_content = "혹시 범인은 젠 아저씨 아냐?",
  ui_story_5029_50290026_82_dialog_content = "젠? 그럴 리가 없잖아.",
  ui_story_5029_50290026_83_dialog_content = "가능성이 없는 사람일수록 가능성이 있다구!",
  ui_story_5029_50290026_84_dialog_content = "치밀하게 짜인 논리의 사슬이라도, 고리 하나가 잘못 걸려 있다면\n사슬 전체를 못 쓰게 돼버려.",
  ui_story_5029_50290026_85_dialog_content = "어딘가 허점이 있는 게 분명해.",
  ui_story_5029_50290026_86_dialog_content = "우리가 이미 봤지만, 눈치채지 못한 무언가가...",
  ui_story_5029_50290026_87_dialog_content = "에이, 그냥 젠 아저씨한테 가서 물어보면 안 돼?",
  ui_story_5029_50290026_88_dialog_content = "설마 나만 그 아저씨가 수상한 거야?",
  ui_story_5029_50290026_89_dialog_content = "「수상하다」라...",
  ui_story_5029_50290026_90_dialog_content = "...사나에?",
  ui_story_5029_50290026_91_dialog_content = "PlayerName, 역시 사나에가 수상하다고 생각하는 거야?",
  ui_story_5029_50290026_92_dialog_content = "내가 아냐...",
  ui_story_5029_50290026_93_dialog_content = "나한테 유독 그걸 강조했던 사람이 있어.",
  ui_story_5029_50290026_94_dialog_content = "루!",
  ui_story_5029_50290026_95_dialog_content = "키아로? 창가에서 뭘 보는 거야?",
  ui_story_5029_50290026_96_dialog_content = "밖엔 나무밖에 없잖아...",
  ui_story_5029_50290026_97_dialog_content = "(이런, 범인이 벌써 움직이기 시작했나?)",
  ui_story_5029_50290026_98_dialog_content = "어? 다들 밖에 저 사람 좀 봐! 뭔가 수상해!",
  ui_story_5029_50290027_1_dialog_content = "(역시 늦어버린 건가...)",
  ui_story_5029_50290027_2_dialog_content = "(아니, 아직 기회는 있어!)",
  ui_story_5029_50290027_3_dialog_content = "(모두가 힘을 합치면 이번엔 반드시 해낼 수 있을 거야!)",
  ui_story_5029_50290027_4_dialog_content = "(심호흡하고... 얼른 방법을 생각하자. 범인을 잡을 방법을...)",
  ui_story_5029_50290027_5_dialog_content = "저 사람 확실히 뭔가 수상해. 이렇게 더운 날씨에\n저렇게 꽁꽁 싸매고 있잖아.",
  ui_story_5029_50290027_6_dialog_content = "뭔가 파고 있는 것 같은데?",
  ui_story_5029_50290027_7_dialog_content = "(파고 있다...?)",
  ui_story_5029_50290027_8_dialog_content = "(그랬군... 범인은 지금까지 물건을 뒤뜰의 땅속에 숨기고 있었어.)",
  ui_story_5029_50290027_9_dialog_content = "다들 들어봐! 저 사람이 바로 은 상자를 훔친 범인이야.",
  ui_story_5029_50290027_10_dialog_content = "범인은 지금 뒤뜰에 묻어둔 은 상자를 파고 있고,\n그리고 도망칠 생각이야.",
  ui_story_5029_50290027_11_dialog_content = "그럼 뭘 꾸물대고 있어? 빨리 가서 잡아야지!",
  ui_story_5029_50290027_12_dialog_content = "피아, 잠깐만.",
  ui_story_5029_50290027_13_dialog_content = "PlayerName, 지휘는 준비됐어?",
  ui_story_5029_50290027_14_dialog_content = "너희들...",
  ui_story_5029_50290027_15_dialog_content = "우리한테 힘을 합치라고 한 건 너잖아.",
  ui_story_5029_50290027_16_dialog_content = "비록 암귀와의 싸움은 아니지만,\n팀의 지휘라면 역시 네가 가장 익숙한 거니까.",
  ui_story_5029_50290027_17_dialog_content = "응... 알겠어!",
  ui_story_5029_50290027_18_dialog_content = "피아, 넌 먼저 키아로를 데리고 가서 뒷산으로 통하는 길을 막아.",
  ui_story_5029_50290027_19_dialog_content = "범인이 산길을 따라 도망치면 우린 쫓아가기 힘들 거야.",
  ui_story_5029_50290027_20_dialog_content = "알았어!",
  ui_story_5029_50290027_21_dialog_content = "바이스, 카렌. 너흰 좌우로 나뉘어서 출발해줘.",
  ui_story_5029_50290027_22_dialog_content = "만약을 대비해서 무기도 잊지 말고 챙겨.",
  ui_story_5029_50290027_23_dialog_content = "난 녀석이 왔던 길로 돌아오지 못하게 바로 뒤를 쫓을게.",
  ui_story_5029_50290027_24_dialog_content = "알겠어!",
  ui_story_5029_50290027_25_dialog_content = "이번엔... 절대로 놓치지 않을 테니까!",
  ui_story_5029_50290027_26_dialog_content = "상황은 어때?",
  ui_story_5029_50290027_27_dialog_content = "성공이야! 범인은 항구 쪽으로 도망쳤어.",
  ui_story_5029_50290027_28_dialog_content = "휴우... 도망치는 게 너무 빨라.",
  ui_story_5029_50290027_29_dialog_content = "괜찮아! 피아는 신호탄이 있으니까!",
  ui_story_5029_50290027_30_dialog_content = "키아로, 내가 신호탄으로 범인한테 마킹을 할게.\n넌 녀석이 은 상자를 못 가져가게 막아.",
  ui_story_5029_50290027_31_dialog_content = "루!",
  ui_story_5029_50290027_32_dialog_content = "어라, 이상하네. 왜 지금 이 말을 어디서 한 것 같은 느낌이 들지?",
  ui_story_5029_50290027_33_dialog_content = "뭐, 됐어... 피아의 치명적 마킹 공격── 빵야!",
  ui_story_5029_50290027_34_dialog_content = "......?",
  ui_story_5029_50290027_35_dialog_content = "루...우!",
  ui_story_5029_50290027_36_dialog_content = "그래, 바로 그거야, 키아로! 쫓아가서 손을 확 물어버려!",
  ui_story_5029_50290027_37_dialog_content = "루우우!",
  ui_story_5029_50290027_38_dialog_content = "으앗... 범인이 은 상자를 키아로한테 던졌어!",
  ui_story_5029_50290027_39_dialog_content = "키아로, 조심해!",
  ui_story_5029_50290027_40_dialog_content = "<color=#828282>쿵!</color>",
  ui_story_5029_50290027_41_dialog_content = "으아... 이 상자, 진짜 무겁네.",
  ui_story_5029_50290027_42_dialog_content = "다행이야! 바이스 언니가 키아로 대신 은 상자를 받아줬구나!",
  ui_story_5029_50290027_43_dialog_content = "키아로, 그 상자 잘 가지고 있어. 이 뒤는 나랑 카렌한테 맡겨.",
  ui_story_5029_50290027_44_dialog_content = "바이스, 서둘러. 범인이 벌써 멀리 도망쳤어.",
  ui_story_5029_50290027_45_dialog_content = "괜찮아, 원거리 공격은 내 전문이니까~",
  ui_story_5029_50290027_46_dialog_content = "타깃 추적!",
  ui_story_5029_50290027_47_dialog_content = "으윽...",
  ui_story_5029_50290027_48_dialog_content = "우와! 바이스 언니 대단해! 한 번에 범인을 쓰러트렸어!",
  ui_story_5029_50290027_49_dialog_content = "...바이스, 범인을 다치지 않게 하려고 공격력을 약화시켰어?",
  ui_story_5029_50290027_50_dialog_content = "범인이 다시 일어나는 것 같은데?",
  ui_story_5029_50290027_51_dialog_content = "못 도망칠걸. 카렌 언니가 벌써 따라잡았으니까!",
  ui_story_5029_50290027_52_dialog_content = "이 지경이 됐는데 아직도 도망칠 생각인가?",
  ui_story_5029_50290027_53_dialog_content = "아, 아니?!",
  ui_story_5029_50290027_54_dialog_content = "나의 장창에 그림자는 없다!",
  ui_story_5029_50290027_55_dialog_content = "으윽...",
  ui_story_5029_50290027_56_dialog_content = "드디어...",
  ui_story_5029_50290027_57_dialog_content = "범인을 잡은 건가...",
  ui_story_5029_50290027_58_dialog_content = "바이스, 잘했어.",
  ui_story_5029_50290027_59_dialog_content = "하하, 너도 잘했어.",
  ui_story_5029_50290027_60_dialog_content = "그 정도 거리에서 범인을 맞히다니 정말 대단한 솜씨네.",
  ui_story_5029_50290027_61_dialog_content = "그래도 정말 엄청 빠른 녀석이었어...",
  ui_story_5029_50290027_62_dialog_content = "다행히 우리한텐 백야성의 호위대장 카렌이 있잖아?",
  ui_story_5029_50290027_63_dialog_content = "네가 있으면 어떤 범인도 절대 도망칠 수 없을 거야.",
  ui_story_5029_50290027_64_dialog_content = "자, 거기까지. 그 이상 말하면 닭살 돋을 것 같으니까.",
  ui_story_5029_50290027_65_dialog_content = "칭찬하는 건데 뭘 부끄러워하고 그래~",
  ui_story_5029_50290027_66_dialog_content = "네가 방금 나 칭찬했던 건 나도 전부 받아줬잖아.",
  ui_story_5029_50290027_67_dialog_content = "바이스 언니, 카렌 언니, 잠깐만... 나도 있다구!",
  ui_story_5029_50290027_68_dialog_content = "물론 알고 있어.",
  ui_story_5029_50290027_69_dialog_content = "뒷산으로 통하는 길을 막아준 피아도 큰 힘이 됐어.",
  ui_story_5029_50290027_70_dialog_content = "헤헤헤, 피아도 힘이 된 거구나...",
  ui_story_5029_50290027_71_dialog_content = "그래도 역시 가장 중요한 사람을 잊어선 안 돼.",
  ui_story_5029_50290027_72_dialog_content = "아니었으면 뒤뜰에 있던 수상한 인물이 범인인 건 아무도 몰랐겠지.",
  ui_story_5029_50290027_73_dialog_content = "키아로, 바이스 언니랑 카렌 언니가 너 칭찬해줬어!",
  ui_story_5029_50290027_74_dialog_content = "루?",
  ui_story_5029_50290027_75_dialog_content = "크흠... 맞아, 키아로도 있었지.",
  ui_story_5029_50290027_76_dialog_content = "키아로도 고마워. 오늘 저녁엔 맛있는 거 많이 먹게 해 줄게!",
  ui_story_5029_50290027_77_dialog_content = "루우우!",
  ui_story_5029_50290027_78_dialog_content = "어라, PlayerName 쟤 범인이랑 무슨 얘기하는 거야?",
  ui_story_5029_50290027_79_dialog_content = "정말 당신이었어요?",
  ui_story_5029_50290027_80_dialog_content = "흥.",
  ui_story_5029_50290027_81_dialog_content = "그래서 제가 남을 의심하게 만든 거였군요.",
  ui_story_5029_50290027_82_dialog_content = "당신 거짓말은 전부 은 상자를 훔치기 위해서였나요?",
  ui_story_5029_50290027_83_dialog_content = "......",
  ui_story_5029_50290027_84_dialog_content = "PlayerName, 고마워. 오늘 우리가 해낸 건 모두 네 계획 덕분이야.",
  ui_story_5029_50290027_85_dialog_content = "맞아.",
  ui_story_5029_50290027_85X1_dialog_content = "네가 중요한 순간에 모두가 힘을 합치게 만들지 않았다면,\n우린 저 교활한 범인을 절대 잡을 수 없었을 거야.",
  ui_story_5029_50290027_86_dialog_content = "그래도 역시 신경 쓰이는 게 있어.\n그때 우린 그저 뒤뜰에 있는 사람이 수상하다고 생각했을 뿐이었어...",
  ui_story_5029_50290027_87_dialog_content = "근데 넌 어떻게 저자가 은 상자를 훔친 범인인 걸 안 거야?\n설마 또 예감은 아니겠지?",
  ui_story_5029_50290027_88_dialog_content = "많은 일을 겪고 나면 그만큼 교훈을 얻는 법이거든.",
  ui_story_5029_50290027_89_dialog_content = "음?",
  ui_story_5029_50290027_90_dialog_content = "피아는 그것보다 저 범인이 대체 누구인지가 더 궁금하다구.\n젠 아저씨 아냐?!",
  ui_story_5029_50290027_91_dialog_content = "PlayerName 넌 아까 사나에를 의심한다고 했잖아.",
  ui_story_5029_50290027_92_dialog_content = "저 범인, 아직 가면을 쓰고 있긴 하지만...\n아무리 봐도 사나에는 아니잖아?",
  ui_story_5029_50290027_93_dialog_content = "일부러 내가 사나에를 의심하게 만든 사람이... 바로 이 범인이야.",
  ui_story_5029_50290027_94_dialog_content = "사나에가 서재에 들어가는 걸 본 목격자, 영주님의 하인...",
  ui_story_5029_50290027_95_dialog_content = "쿠크 씨.",
  ui_story_5029_50290027_96_dialog_content = "......",
  ui_story_5029_50290028_1_dialog_content = "쿠크?",
  ui_story_5029_50290028_2_dialog_content = "사나에도 그 이름을 말했어.",
  ui_story_5029_50290028_3_dialog_content = "쿠크 씨가 사나에한테 서재 문단속을 잘하라고 했댔어.\n그래서 난 착한 아저씨라고 생각했다구.",
  ui_story_5029_50290028_4_dialog_content = "사나에가 쿠크 씨를 어디서 만났는지는 말했어?",
  ui_story_5029_50290028_5_dialog_content = "그거야 서재겠지... 어라?",
  ui_story_5029_50290028_6_dialog_content = "그래. 쿠크씨가 바로 서재에 들어간 네 번째 사람이야.",
  ui_story_5029_50290028_7_dialog_content = "난 범하지 말아야 할 실수를 했어.\n무의식적으로 목격자를 용의선상에서 제외했던 거지.",
  ui_story_5029_50290028_8_dialog_content = "지금 그 결박된 범인이 쿠크라고 말씀하시는 겁니까?",
  ui_story_5029_50290028_9_dialog_content = "앗, 영주 아저씨도 왔어!",
  ui_story_5029_50290028_10_dialog_content = "전 그저 제 끝나지 않은 추리를 이야기하고 있을 뿐이에요.",
  ui_story_5029_50290028_11_dialog_content = "아직 범인의 가면을 벗기지 않았거든요...",
  ui_story_5029_50290028_12_dialog_content = "괜찮습니다. 저도 PlayerName 님의 추리를 듣고 싶습니다.",
  ui_story_5029_50290028_13_dialog_content = "제 예상이 틀리지 않았다면...",
  ui_story_5029_50290028_14_dialog_content = "<color=#828282>끼익──</color>",
  ui_story_5029_50290028_15_dialog_content = "(누가 왔나?)",
  ui_story_5029_50290028_16_dialog_content = "(아무래도 다음에 다시 와야겠어.)",
  ui_story_5029_50290028_17_dialog_content = "하하하하, 하늘이 날 돕는군.",
  ui_story_5029_50290028_18_dialog_content = "신문만 놓고 가려고 했는데, 마침 영주도 없고 서재도 열려있군.",
  ui_story_5029_50290028_19_dialog_content = "영주의 보물은 이제 내 거다!",
  ui_story_5029_50290028_20_dialog_content = "<color=#828282>끼익──</color>",
  ui_story_5029_50290028_21_dialog_content = "(누구지?!)",
  ui_story_5029_50290028_22_dialog_content = "(아, 저 계집애였군. 저 애라면 속이기 쉽겠지.)",
  ui_story_5029_50290028_23_dialog_content = "(하지만 내가 은 상자를 갖고 있는 걸 들킬 순 없지.)",
  ui_story_5029_50290028_24_dialog_content = "(일단 창문 밖으로 던지고, 나중에 가지러 가야겠어.)",
  ui_story_5029_50290028_25_dialog_content = "<color=#828282>쿵!</color>",
  ui_story_5029_50290028_26_dialog_content = "(쳇... 빌어먹을! 창가의 사막 식물에 부딪히다니...)",
  ui_story_5029_50290028_27_dialog_content = "어라, 무슨 소리지?",
  ui_story_5029_50290028_28_dialog_content = "이런 늦은 시간에 영주님의 서재에서 뭘 하고 있는 겁니까?",
  ui_story_5029_50290028_29_dialog_content = "아, 저, 전...",
  ui_story_5029_50290028_30_dialog_content = "또 영주님의 물건을 망가트린 겁니까?",
  ui_story_5029_50290028_31_dialog_content = "제가 새 걸로 사 왔어요...\n누구한테 어떤 폐도 끼치지 않을 거예요...",
  ui_story_5029_50290028_32_dialog_content = "그러니까 제발 영주님이랑 메이드장님한테 말하지 말아 주세요...",
  ui_story_5029_50290028_33_dialog_content = "안 그러면 전 잘릴 거예요...",
  ui_story_5029_50290028_34_dialog_content = "음... 새 걸로 사 왔다면 아무도 모르고 넘어갈 수도 있겠군요.",
  ui_story_5029_50290028_35_dialog_content = "네?",
  ui_story_5029_50290028_36_dialog_content = "못 본 걸로 해드리죠.",
  ui_story_5029_50290028_37_dialog_content = "대신 서재의 문단속을 잘하세요.",
  ui_story_5029_50290028_38_dialog_content = "그럼 베벌리 씨 다음으로 서재에 들어갔던 건\n사나에가 아니라 쿠크 씨였구나!",
  ui_story_5029_50290028_39_dialog_content = "저 바보 계집애는 바닥 청소까지 해서 내 발자국을 지워줬었지.",
  ui_story_5029_50290028_40_dialog_content = "하하하하하, 완벽한 계획이었는데 말이야!",
  ui_story_5029_50290028_41_dialog_content = "이 목소리는...",
  ui_story_5029_50290028_42_dialog_content = "......",
  ui_story_5029_50290028_43_dialog_content = "쿠크, 정말 당신이었습니까?!",
  ui_story_5029_50290028_44_dialog_content = "PlayerName 말이 맞았네! PlayerName 너 진짜 명탐정이었던 거야?",
  ui_story_5029_50290028_45_dialog_content = "오늘 내가 급하게 도망치지만 않았어도 너흰 평생\n내가 누군지 몰랐을 거다!",
  ui_story_5029_50290028_46_dialog_content = "아니, 당신은 단서를 남기고 있었어요!",
  ui_story_5029_50290028_47_dialog_content = "그럴 리가 없어!",
  ui_story_5029_50290028_48_dialog_content = "카페에 있던 신문을 잊은 건 아니겠죠?",
  ui_story_5029_50290028_49_dialog_content = "영주님은 어제 하루 종일 손님을 만나고 있었어요.\n그러니 당신이 보낸 신문을 받지 못했겠죠.",
  ui_story_5029_50290028_50_dialog_content = "그런데 어제 일자 신문이 왜 카페에 있었을까요?",
  ui_story_5029_50290028_51_dialog_content = "......",
  ui_story_5029_50290028_52_dialog_content = "처음 당신을 만났을 때부터 뭔가 이상했어요.",
  ui_story_5029_50290028_53_dialog_content = "발이 불편한 사람의 신발에 왜 진흙이 묻어 있었던 건지 말이죠.",
  ui_story_5029_50290028_54_dialog_content = "이제 보니 당신은 의심을 피하려고 밤중에 은 상자를\n뒤뜰에 묻었던 거였어요.",
  ui_story_5029_50290028_54X1_dialog_content = "그래서 신발에 진흙이 묻어 있던 거겠죠.",
  ui_story_5029_50290028_55_dialog_content = "이 증거들로 당신을 찾아내는 건 시간문제였어요.",
  ui_story_5029_50290028_56_dialog_content = "아쉬웠던 건... 더 빨리 추리를 완성했으면\n이런 소란을 피울 일도 없었을 거란 거죠.",
  ui_story_5029_50290028_57_dialog_content = "쿠크, 다리 부상은 아직 안 나은 게 아니었습니까.",
  ui_story_5029_50290028_58_dialog_content = "나한테 가장 먼저 묻고 싶은 게 그거냐?",
  ui_story_5029_50290028_59_dialog_content = "흥, 너에 대한 원망이 없었다면, 내 발도 이렇게 빨리 낫진 않았겠지.",
  ui_story_5029_50290028_60_dialog_content = "잘 들어라! 평소 다리가 아픈 척했던 건...\n네 보물을 훔친 뒤에도 의심을 받지 않기 위해서다.",
  ui_story_5029_50290028_61_dialog_content = "모르겠습니다. 어째서 이런 짓을 한 겁니까...",
  ui_story_5029_50290028_62_dialog_content = "돈이 필요했다면 제게 말했으면 되었을 것을...",
  ui_story_5029_50290028_63_dialog_content = "거짓 자비는 집어치워! 이건 돈 문제가 아니라고!",
  ui_story_5029_50290028_64_dialog_content = "난 그저 네가 가장 아끼는 것을 훔치고,\n네게 상실의 아픔을 맛보게 해주고 싶었을 뿐이다.",
  ui_story_5029_50290028_65_dialog_content = "쿠크, 영주님이 대체 당신한테 뭘 어쨌다는 겁니까?",
  ui_story_5029_50290028_66_dialog_content = "영주님은 당신이 다친 뒤에도 저택에서 요양할 수 있도록 해 주셨는데,\n대체 왜 이런 짓을 한 겁니까?",
  ui_story_5029_50290028_67_dialog_content = "하, 흐하하하하.",
  ui_story_5029_50290028_68_dialog_content = "우리 가족은 대대로 영주님 일가를 섬기며 충성을 바쳐 왔다.",
  ui_story_5029_50290028_69_dialog_content = "나도 너희들에게 뭐 하나 잘못한 게 없었지. 그런데 넌 날 어떻게 대했지?",
  ui_story_5029_50290028_70_dialog_content = "작년에 난 널 구하느라 벼랑에서 떨어져 다리를 다쳤지만...",
  ui_story_5029_50290028_71_dialog_content = "넌 얼마 안 가서 젠을 내 후임으로 앉혔다.",
  ui_story_5029_50290028_72_dialog_content = "그리고 난 고작 메이드들의 잡일이나 돕는 신세가 됐지...\n그것뿐이었다면 난 참을 수도 있었다.",
  ui_story_5029_50290028_73_dialog_content = "하지만 그것만으로는 성에 안 찼던 건지,\n날 들개처럼 쫓아내려고 하지 않았냔 말이다!",
  ui_story_5029_50290028_74_dialog_content = "그런 일은 하지 않을 겁니다.",
  ui_story_5029_50290028_75_dialog_content = "내가 직접 들었다고! 네가 메이드장한테 말했잖아!\n내가 떠나고 나면 내 방을 젠한테 주겠다고...",
  ui_story_5029_50290028_76_dialog_content = "우리 가족은 대대로 충성을 다했는데,\n그 결과는 고작 이런 대우란 말이냐?",
  ui_story_5029_50290028_77_dialog_content = "당신은 영주님의 호의를 오해한 겁니다...",
  ui_story_5029_50290028_78_dialog_content = "젠, 보챌 거 없어! 어차피 너도 곧 나처럼 버려질 테니까! 흐하하하!",
  ui_story_5029_50290028_79_dialog_content = "휴.",
  ui_story_5029_50290028_80_dialog_content = "영주님, 저 말이 사실인가요...?",
  ui_story_5029_50290028_81_dialog_content = "사실이면서, 사실이 아닙니다.",
  ui_story_5029_50290028_82_dialog_content = "쿠크, 당신은 예전부터 달리기에 재능이 있었죠.\n하지만 다친 뒤에는 아마 평생 불편함을 겪어야 하겠지요.",
  ui_story_5029_50290028_83_dialog_content = "그래서 줄곧 미안하게 생각하고 있었습니다.",
  ui_story_5029_50290028_84_dialog_content = "당신은 충성스럽고 용맹한 사람입니다.\n하지만 그에 못지않게 영리하고 추진력이 있지요.",
  ui_story_5029_50290028_85_dialog_content = "아마 이 좁은 집을 떠나 사업을 하면 큰 성공을 거둘 수도 있겠지요.",
  ui_story_5029_50290028_86_dialog_content = "그래서 저는 당신이 창업할 자금을 준비해서,\n당신이 새로운 세계로 나아가게 해야겠다고 생각했습니다.",
  ui_story_5029_50290028_87_dialog_content = "하지만 그 이야기를 꺼낼 시간이 주어지지 않았군요...",
  ui_story_5029_50290028_88_dialog_content = "무슨 헛소리야?!",
  ui_story_5029_50290028_89_dialog_content = "그...그럴 리가 없잖아!",
  ui_story_5029_50290028_90_dialog_content = "지금... 내가 널 오해했다는 얘기냐?",
  ui_story_5029_50290028_91_dialog_content = "말도 안 되는 소리!",
  ui_story_5029_50290028_92_dialog_content = "그동안 한 번도 나 따위는 거들떠보지도 않았으면서,\n나 때문에 그렇게 많은 생각을 했다는 게 가능한 얘기냐?",
  ui_story_5029_50290028_93_dialog_content = "그런 거짓말이 나한테 먹힐 줄 알고?!",
  ui_story_5029_50290028_94_dialog_content = "넌 그저 자기 변호를 위해 이야기를 지어냈을 뿐이야.",
  ui_story_5029_50290028_95_dialog_content = "그래, 백야성의 공주 앞이라서 차마 잘못을 인정할 수 없는 거겠지?",
  ui_story_5029_50290028_96_dialog_content = "그러니까 앞뒤도 안 맞는 핑계를 대고 있는 거지. 안 그러냐?",
  ui_story_5029_50290028_97_dialog_content = "영주님의 말은 사실입니다! 제가 증명할 수 있습니다!",
  ui_story_5029_50290028_98_dialog_content = "닥쳐!",
  ui_story_5029_50290028_99_dialog_content = "저도 사람을 잘못 볼 줄은 몰랐군요.",
  ui_story_5029_50290028_100_dialog_content = "......",
  ui_story_5029_50290028_101_dialog_content = "당신의 그 좁은 도량은 확실히 사업에는 걸맞지 않겠군요.",
  ui_story_5029_50290028_102_dialog_content = "내가 뭘 하든 네가 판단할 거 없잖아!",
  ui_story_5029_50290028_103_dialog_content = "그 오랜 시간을 널 위해 애썼는데, 이제 와서도 날 속이려 들다니...",
  ui_story_5029_50290028_104_dialog_content = "흥, 하하하하하!",
  ui_story_5029_50290028_105_dialog_content = "그런 헛소리는 바보나 믿을 거다!",
  ui_story_5029_50290028_106_dialog_content = "퉷!",
  ui_story_5029_50290028_107_dialog_content = "당신... 반드시 후회할 겁니다.",
  ui_story_5029_50290028_108_dialog_content = "주변에 사람이 많아지는군요.",
  ui_story_5029_50290028_109_dialog_content = "젠, 쿠크를 데리고 먼저 돌아가세요.",
  ui_story_5029_50290028_110_dialog_content = "예!",
  ui_story_5029_50290028_111_dialog_content = "영주님, 정말 미안해요...",
  ui_story_5029_50290028_112_dialog_content = "어찌 됐든 은 상자와 쿠크를 찾아 주셔서 감사합니다.",
  ui_story_5029_50290028_113_dialog_content = "아, 상자를 돌려드릴게요.",
  ui_story_5029_50290028_114_dialog_content = "바닥에 떨어지면서 좀 고장이 난 것 같아요.\n안에 내용물이 다 있는지 확인해 보세요.",
  ui_story_5029_50290028_115_dialog_content = "감사합니다.",
  ui_story_5029_50290028_116_dialog_content = "<color=#828282>철컥.</color>",
  ui_story_5029_50290028_117_dialog_content = "좋습니다. 내용물은 잘 들어 있군요.",
  ui_story_5029_50290028_118_dialog_content = "<color=#828282>휘이잉──</color>",
  ui_story_5029_50290028_119_dialog_content = "앗, 뭔가 바람에 날린 것 같은데요?",
  ui_story_5029_50290028_120_dialog_content = "제가 주울게요!",
  ui_story_5029_50290028_121_dialog_content = "어라, 이건...",
  ui_story_5029_50290028_122_dialog_content = "오래된 그림일 뿐입니다.",
  ui_story_5029_50290028_123_dialog_content = "가장 아끼는 상자에 넣어둔 거라면... 분명히 소중한 그림이겠죠?",
  ui_story_5029_50290028_124_dialog_content = "그렇습니다.",
  ui_story_5029_50290028_125_dialog_content = "하지만 이 시절로 다시는 돌아갈 수 없겠지요...",
  ui_story_5029_50290028_126_dialog_content = "이 이야기는 이제 그만합시다.",
  ui_story_5029_50290028_127_dialog_content = "PlayerName 님, 카렌 전하, 바이스 양, 그리고 피아 양. 감사합니다.",
  ui_story_5029_50290028_128_dialog_content = "오늘 밤 제 저택에서 하버 시티의 특별한 만찬을 열 것입니다만,\n괜찮으시다면 여러분도 꼭 와 주십시오.",
  ui_story_5029_50290028_129_dialog_content = "음, 뭔가 비싼 물건이 들어 있을 줄 알았는데.",
  ui_story_5029_50290028_130_dialog_content = "고작 그림 한 장이었다니, 이해가 안 돼.",
  ui_story_5029_50290028_131_dialog_content = "피아라면 스승의 책을 넣으려나?",
  ui_story_5029_50290028_132_dialog_content = "아니거든. 책을 넣을 거면 내 걸 넣어야지.",
  ui_story_5029_50290028_133_dialog_content = "그림 속 사람... 왠지 어디서 본 것 같았는데...",
  ui_story_5029_50290028_134_dialog_content = "PlayerName, 사건도 해결됐으니까, 더는 생각하지 말자.",
  ui_story_5029_50290028_135_dialog_content = "이 건은 엘비스가 알아서 잘 처리할 거야.",
  ui_story_5029_50290028_136_dialog_content = "그리고...",
  ui_story_5029_50290028_137_dialog_content = "이 근처 산꼭대기에 전망대가 있다고 들었어.\n이미 오랫동안 방치되어 있었지만, 그래도 전망은 아주 좋다고 해.",
  ui_story_5029_50290028_138_dialog_content = "다 같이 보러 가지 않을래?",
  ui_story_5029_50290028_139_dialog_content = "에이, 긴장을 풀려면 역시 몸을 움직이는 게 최고지!",
  ui_story_5029_50290028_140_dialog_content = "산 뒤에 풀밭이 있는데 달리기 딱 좋다고 들었어.",
  ui_story_5029_50290028_141_dialog_content = "PlayerName, 가자. 오늘 훈련을 빠트리면 안 되지~",
  ui_story_5029_50290028_142_dialog_content = "잠깐만, 저기 사람들이 다들 축제 음식을 먹으러 가더라고.",
  ui_story_5029_50290028_143_dialog_content = "밤에는 더 시끌벅적하댔어.",
  ui_story_5029_50290028_144_dialog_content = "PlayerName, 나랑 키아로한테 맛있는 거 먹게 해준다고 약속했잖아?",
  ui_story_5029_50290028_145_dialog_content = "야시장 가자~",
  ui_story_5029_50290028_146_dialog_content = "달리러 가자!",
  ui_story_5029_50290028_147_dialog_content = "전망대에서 경치를 보자!",
  ui_story_5029_50290028_148_dialog_content = "아...",
  ui_story_5029_50290028_149_dialog_content = "저기...",
  ui_story_5029_50290028_150_dialog_content = "난 어떻게 해야 되냐고...",
  ui_story_5029_50290028_151_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5029_50290028_152_dialog_content = "돌아오신 것을 환영합니다. 친애하는 손님.",
  ui_story_5029_50290028_153_dialog_content = "오늘 밤의 시간을 낭비하지 않으셨군요.",
  ui_story_5029_50290028_154_dialog_content = "축하합니다. 당신은 꿈속의 수수께끼를 멋지게 풀어냈습니다.",
  ui_story_5029_50290028_155_dialog_content = "친애하는 손님, 왜 그런 놀란 눈으로 저를 보시는지요.",
