  ui_story_5029_50290028_158_dialog_content = "왜 <color=#793f76>처음부터</color> 제 권유를 거절하지 않으셨는지요.",
  ui_story_5029_50290028_159_dialog_content = "다만... 제가 마술로 만들어낸 꿈의 그물에서 벗어날 수 있는 사람은\n이 세상에 그리 많지 않답니다.",
  ui_story_5029_50290028_160_dialog_content = "이렇게 된 이상, 당신은 「제노가 간섭하는 미래」를\n받아들일 수밖에 없습니다.",
